"use strict";(globalThis.webpackChunkistqb_quiz=globalThis.webpackChunkistqb_quiz||[]).push([[972],{972(e){e.exports=JSON.parse('[{"id":1001,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants est un objectif courant des tests logiciels ?  ","options":["Confirmer que le logiciel r\xe9pond aux exigences sp\xe9cifi\xe9es.","Garantir qu\'il n\'y a aucune erreur dans le code source.","D\xe9montrer que le syst\xe8me est totalement s\xe9curis\xe9 contre les attaques externes.","V\xe9rifier que tous les utilisateurs sont satisfaits du produit."],"correctAnswer":0,"explanation":"Confirmer le respect des exigences est un objectif courant (syllabus 1.1). Les tests ne peuvent pas garantir l\'absence d\'erreurs (faux), ni qu\'il est totalement s\xe9curis\xe9 ou que tout le monde est satisfait.","source":"Pr\xe1ctica Adicional"},{"id":1002,"chapter":1,"topic":"Fondamentaux des tests","question":"Une entreprise de logiciels d\xe9veloppe des applications pour le secteur financier. L\'\xe9quipe de direction demande au responsable des tests pourquoi les tests sont essentiels dans leur contexte, au-del\xe0 de la d\xe9tection des d\xe9fauts. Laquelle des raisons suivantes d\xe9crit le MIEUX pourquoi les tests sont n\xe9cessaires dans ce contexte ?  ","options":["Pour d\xe9montrer que le logiciel n\'a aucun d\xe9faut avant sa livraison.","Pour fournir de la confiance sur le niveau de qualit\xe9 du logiciel et respecter les exigences r\xe9glementaires du secteur.","Pour remplacer le processus de revue des exigences et r\xe9duire la documentation.","Pour s\'assurer que tous les d\xe9veloppeurs connaissent le code de l\'ensemble du syst\xe8me."],"correctAnswer":1,"explanation":"Dans le secteur financier, fournir de la confiance et respecter les r\xe9glementations est vital. Les tests ne peuvent pas d\xe9montrer l\'absence de d\xe9fauts (principe de l\'erreur de l\'absence de d\xe9fauts).","source":"Pr\xe1ctica Adicional"},{"id":1003,"chapter":1,"topic":"Fondamentaux des tests","question":"Vous \xe9valuez la qualit\xe9 des tests r\xe9alis\xe9s sur un logiciel avant sa mise en production. Vous observez que, bien que de nombreux tests aient \xe9t\xe9 ex\xe9cut\xe9s, des d\xe9fauts importants persistent. Lequel des sept principes des tests se refl\xe8te dans cette situation ?  ","options":["Les tests exhaustifs sont impossibles","Les d\xe9fauts se regroupent","Les tests s\'usent","L\'erreur de l\'absence de d\xe9fauts"],"correctAnswer":1,"explanation":"Les d\xe9fauts ont tendance \xe0 se regrouper dans des modules sp\xe9cifiques (regroupement de d\xe9fauts ou Pareto).","source":"Pr\xe1ctica Adicional"},{"id":1007,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des comp\xe9tences suivantes est essentielle pour un testeur lorsqu\'il \xe9value la qualit\xe9 d\'un produit logiciel ?  \\n  \\ni. Communication efficace  \\n  \\nii. Connaissances techniques  \\n  \\niii. Capacit\xe9 d\'analyse  \\n  \\niv. Gestion du temps  ","options":["i et ii sont essentielles ; iii et iv ne le sont pas","iii et iv sont essentielles ; i et ii ne le sont pas","ii et iii sont essentielles ; i et iv ne le sont pas","i et iii sont essentielles ; ii et iv ne le sont pas"],"correctAnswer":3,"explanation":"La communication efficace et la capacit\xe9 d\'analyse (i et iii) sont primordiales selon le syllabus pour signaler les probl\xe8mes et concevoir les tests, bien que ii et iv aident \xe9galement.","source":"Pr\xe1ctica Adicional"},{"id":1008,"chapter":1,"topic":"Fondamentaux des tests","question":"Quel est un avantage cl\xe9 de l\'approche d\'\xe9quipe enti\xe8re dans le processus de d\xe9veloppement logiciel ?  ","options":["Elle favorise une communication isol\xe9e entre les testeurs et les d\xe9veloppeurs.","Elle facilite la collaboration entre toutes les parties prenantes d\xe8s le d\xe9but du projet.","Elle augmente la dur\xe9e des tests en exigeant des revues approfondies.","Elle \xe9limine le besoin d\'une strat\xe9gie de test bien d\xe9finie."],"correctAnswer":1,"explanation":"L\'approche d\'\xe9quipe enti\xe8re favorise la collaboration mutuelle de tous les profils d\xe8s le d\xe9but.","source":"Pr\xe1ctica Adicional"},{"id":1038,"chapter":1,"topic":"Fondamentaux des tests","question":"Vous \xe9valuez la qualit\xe9 des tests r\xe9alis\xe9s sur un logiciel avant sa mise en production. Vous observez que, bien que de nombreux tests aient \xe9t\xe9 ex\xe9cut\xe9s, des d\xe9fauts importants persistent. Lequel des sept principes des tests se refl\xe8te dans cette situation ?  ","options":["Les tests exhaustifs sont impossibles","Les d\xe9fauts se regroupent","Les tests s\'usent","L\'erreur de l\'absence de d\xe9fauts"],"correctAnswer":1,"explanation":"Ce principe indique qu\'un petit nombre de composants peut contenir la majorit\xe9 des d\xe9fauts (regroupement), ce qui explique pourquoi des d\xe9fauts importants localis\xe9s persistent.","source":"Errores Reportados - Set 2"},{"id":1039,"chapter":1,"topic":"Fondamentaux des tests","question":"Lesquelles des comp\xe9tences suivantes (i-v) sont essentielles pour un testeur dans son travail quotidien ?  \\n  \\ni. Capacit\xe9 \xe0 r\xe9diger des rapports clairs  \\n  \\nii. Connaissance des langages de programmation  \\n  \\niii. Capacit\xe9 d\'analyse des risques  \\n  \\niv. \xcatre un bon communicant  \\n  \\nv. Conna\xeetre les outils d\'automatisation  ","options":["i, iii et iv sont essentielles ; ii et v ne le sont pas","ii, iii et v sont essentielles ; i et iv ne le sont pas","i, ii et iv sont essentielles ; iii et v ne le sont pas","iii, iv et v sont essentielles ; i et ii ne le sont pas"],"correctAnswer":0,"explanation":"R\xe9diger des rapports (i), l\'analyse des risques (iii) et la communication (iv) sont des comp\xe9tences essentielles (soft et hard skills de base). La programmation et l\'automatisation sont souhaitables mais pas strictement essentielles pour tout testeur au quotidien.","source":"Errores Reportados - Set 2"},{"id":1043,"chapter":1,"topic":"Fondamentaux des tests","question":"Vous examinez l\'avancement d\'un projet logiciel et remarquez que des d\xe9fauts ont \xe9t\xe9 corrig\xe9s, mais qu\'aucun nouveau test n\'a \xe9t\xe9 effectu\xe9. Le chef de projet est satisfait des r\xe9sultats, mais vous \xeates pr\xe9occup\xe9 par la qualit\xe9. Quel principe des tests pourrait justifier votre pr\xe9occupation ?  ","options":["Les tests s\'usent","L\'erreur de l\'absence de d\xe9fauts","Les d\xe9fauts se regroupent","Les tests exhaustifs sont impossibles"],"correctAnswer":1,"explanation":"Il fait r\xe9f\xe9rence \xe0 la croyance erron\xe9e selon laquelle la simple correction des d\xe9fauts existants signifie qu\'il n\'y a pas d\'autres probl\xe8mes dans le syst\xe8me (erreur de l\'absence de d\xe9fauts), ce qui est trompeur sans nouveaux tests le validant par rapport aux exigences.","source":"Errores Reportados - Set 2"},{"id":1068,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des options suivantes d\xe9crit le mieux pourquoi les tests sont n\xe9cessaires dans le d\xe9veloppement logiciel ?  ","options":["Les tests aident \xe0 identifier les erreurs avant que le logiciel ne soit livr\xe9 aux utilisateurs.","Les tests ne sont qu\'une exigence pour respecter les normes de qualit\xe9.","Les tests ne sont n\xe9cessaires que s\'il y a un changement dans les exigences du logiciel.","Les tests garantissent que le logiciel fonctionnera sur tous les appareils disponibles."],"correctAnswer":0,"explanation":"A. Correct. Les tests sont essentiels pour identifier et corriger les erreurs avant que les utilisateurs finaux n\'utilisent le logiciel. B. Incorrect. Leur valeur principale r\xe9side dans l\'identification des d\xe9fauts et l\'am\xe9lioration de la qualit\xe9. C. Incorrect. Les tests doivent \xeatre r\xe9alis\xe9s ind\xe9pendamment de la pr\xe9sence de changements dans les exigences. D. Incorrect. On ne peut pas garantir que le logiciel fonctionnera sur tous les appareils.","source":"Generadas (Why Testing)"},{"id":1069,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants est un objectif typique des tests logiciels ?  ","options":["S\'assurer que le logiciel r\xe9pond \xe0 toutes les exigences du client.","Identifier les d\xe9fauts dans le logiciel avant sa mise en production.","Tester toutes les combinaisons possibles d\'entr\xe9es du syst\xe8me.","Garantir que le syst\xe8me est totalement exempt d\'erreurs."],"correctAnswer":1,"explanation":"A. Incorrect. Les tests ne peuvent pas garantir le respect total de toutes les exigences. B. Correct. Un objectif fondamental des tests est d\'identifier les d\xe9fauts avant la mise en production du logiciel. C. Incorrect. Tester toutes les combinaisons est irr\xe9alisable (principe des tests n\xb02). D. Incorrect. Il est impossible de garantir qu\'un syst\xe8me soit totalement exempt d\'erreurs.","source":"Generadas (Test Objectives)"},{"id":1070,"chapter":1,"topic":"Fondamentaux des tests","question":"Lesquels des contextes suivants pourraient modifier l\'approche du processus de test dans un projet logiciel ? (i) Le type de client et ses attentes, (ii) L\'exp\xe9rience de l\'\xe9quipe de d\xe9veloppement, (iii) La dur\xe9e du projet, (iv) La m\xe9thodologie de d\xe9veloppement utilis\xe9e.  ","options":["i et ii sont des contextes qui modifient l\'approche de test","ii et iii sont des contextes qui modifient l\'approche de test","i, iii et iv sont des contextes qui modifient l\'approche de test","ii, iv sont des contextes qui modifient l\'approche de test"],"correctAnswer":2,"explanation":"C. Correct. Le type de client (i) influence l\'approche ; la dur\xe9e du projet (iii) affecte la planification ; et la m\xe9thodologie de d\xe9veloppement (iv) a un impact sur le type de tests \xe0 r\xe9aliser. Ces trois \xe9l\xe9ments ont plus de poids que l\'exp\xe9rience de l\'\xe9quipe seule.","source":"Generadas (Context)"},{"id":1071,"chapter":1,"topic":"Fondamentaux des tests","question":"Quels \xe9l\xe9ments du contexte peuvent modifier la strat\xe9gie de test dans un projet ? (i) L\'exp\xe9rience de l\'\xe9quipe de test, (ii) Le budget disponible pour les tests, (iii) Les outils d\'automatisation utilis\xe9s, (iv) La culture organisationnelle de l\'\xe9quipe.  ","options":["i, ii, iii modifient la strat\xe9gie de test","ii, iii, iv modifient la strat\xe9gie de test","i, iii, iv modifient la strat\xe9gie de test","i, ii, iv modifient la strat\xe9gie de test"],"correctAnswer":1,"explanation":"B. Correct. Le budget (ii) affecte directement la planification et l\'ex\xe9cution des tests. Les outils d\'automatisation (iii) peuvent changer la fa\xe7on dont les tests sont r\xe9alis\xe9s. La culture organisationnelle (iv) influence la communication et la collaboration. Ces trois \xe9l\xe9ments sont les plus d\xe9terminants pour modifier la strat\xe9gie.","source":"Generadas (Context)"},{"id":1072,"chapter":1,"topic":"Fondamentaux des tests","question":"Lors d\'une revue de tests, vous remarquez que des tests similaires sont utilis\xe9s dans diff\xe9rents projets sans aucune adaptation. Cela a entra\xeen\xe9 un taux de r\xe9ussite \xe9lev\xe9 mais de nombreux d\xe9fauts pass\xe9s inaper\xe7us. Quel principe des tests pourrait expliquer cette situation ?  ","options":["Les tests exhaustifs sont impossibles","Les tests s\'usent","Les d\xe9fauts se regroupent","L\'erreur de l\'absence de d\xe9fauts"],"correctAnswer":1,"explanation":"A. Incorrect. Ce principe concerne les combinaisons de donn\xe9es possibles. B. Correct. Les tests s\'usent (paradoxe du pesticide) : les m\xeames tests r\xe9p\xe9t\xe9s sans adaptation perdent en efficacit\xe9 et cessent de trouver de nouveaux d\xe9fauts. C. Incorrect. Le regroupement des d\xe9fauts concerne la concentration des d\xe9fauts dans des modules sp\xe9cifiques. D. Incorrect. L\'erreur se r\xe9f\xe8re \xe0 la croyance erron\xe9e selon laquelle l\'absence de d\xe9fauts signifie que le logiciel est parfait.","source":"Generadas (Test Principles)"},{"id":1073,"chapter":1,"topic":"Fondamentaux des tests","question":"Au cours d\'un projet, l\'\xe9quipe croit que son logiciel est parfait parce qu\'elle n\'a pas re\xe7u de rapports d\'erreurs depuis des semaines. En tant que testeur, vous savez que cela ne garantit pas la qualit\xe9. Quel principe des tests refl\xe8te cette situation ?  ","options":["L\'erreur de l\'absence de d\xe9fauts","Les tests s\'usent","Les d\xe9fauts se regroupent","Les tests exhaustifs sont impossibles"],"correctAnswer":0,"explanation":"A. Correct. Ce principe indique que l\'absence de d\xe9fauts signal\xe9s ne signifie pas que le logiciel est exempt de d\xe9fauts, car cela peut conduire \xe0 un faux sentiment de s\xe9curit\xe9. B. Incorrect. Ce principe se r\xe9f\xe8re aux tests r\xe9p\xe9titifs qui perdent en efficacit\xe9. C. Incorrect. Ce principe concerne la concentration des d\xe9fauts. D. Incorrect. Ce principe concerne l\'impossibilit\xe9 de tester toutes les combinaisons.","source":"Generadas (Test Principles)"},{"id":1074,"chapter":1,"topic":"Fondamentaux des tests","question":"Quelles comp\xe9tences sont essentielles pour un testeur travaillant dans une \xe9quipe agile ? (i) \xc9coute active, (ii) Connaissances techniques approfondies, (iii) Communication efficace, (iv) Capacit\xe9 \xe0 travailler sous pression.  ","options":["i et iii sont essentielles ; ii et iv ne le sont pas","i, ii et iv sont essentielles ; iii ne l\'est pas","iii et iv sont essentielles ; i et ii ne le sont pas","i, ii et iii sont essentielles ; iv ne l\'est pas"],"correctAnswer":3,"explanation":"D. Correct. L\'\xe9coute active (i), les connaissances techniques approfondies (ii) et la communication efficace (iii) sont des comp\xe9tences fondamentales pour un testeur dans une \xe9quipe agile. La capacit\xe9 \xe0 travailler sous pression (iv) est moins d\xe9terminante en tant que comp\xe9tence g\xe9n\xe9rique de test selon l\'ISTQB.","source":"Generadas (Tester Skills)"},{"id":1075,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des comp\xe9tences suivantes (i-v) est ESSENTIELLE pour un testeur ? (i) Analyse des risques, (ii) Communication efficace, (iii) Connaissances techniques en programmation, (iv) Cr\xe9ativit\xe9, (v) Gestion du temps.  ","options":["i et ii sont essentielles ; iii, iv et v ne le sont pas","iii et iv sont essentielles ; i, ii et v ne le sont pas","ii et v sont essentielles ; i, iii et iv ne le sont pas","i, ii et iv sont essentielles ; iii et v ne le sont pas"],"correctAnswer":3,"explanation":"D. Correct. L\'analyse des risques (i) et la communication efficace (ii) sont des comp\xe9tences fondamentales, et la cr\xe9ativit\xe9 (iv) joue \xe9galement un r\xf4le important dans l\'identification des probl\xe8mes de qualit\xe9. Les connaissances techniques approfondies (iii) et la gestion du temps (v) sont moins d\xe9terminantes en tant que comp\xe9tences essentielles.","source":"Generadas (Tester Skills)"},{"id":1076,"chapter":1,"topic":"Fondamentaux des tests","question":"Dans un projet de d\xe9veloppement logiciel, l\'\xe9quipe examine l\'approche de test pour une nouvelle fonctionnalit\xe9 de gestion des utilisateurs. Laquelle des activit\xe9s suivantes fait partie de la conception des tests ?  ","options":["D\xe9crire les crit\xe8res d\'acceptation pour la fonctionnalit\xe9 de gestion des utilisateurs.","Examiner les exigences du syst\xe8me pour identifier les conditions de test possibles.","Ex\xe9cuter les cas de test d\xe9finis pour v\xe9rifier la fonctionnalit\xe9 de gestion des utilisateurs.","Cr\xe9er des cas de test \xe0 partir des exigences et concevoir les conditions de test associ\xe9es."],"correctAnswer":3,"explanation":"A. Incorrect. D\xe9crire les crit\xe8res d\'acceptation fait partie de la sp\xe9cification des exigences. B. Incorrect. Examiner les exigences fait partie de l\'analyse des tests. C. Incorrect. Ex\xe9cuter les cas de test fait partie de la phase d\'ex\xe9cution. D. Correct. Cr\xe9er des cas de test et concevoir les conditions de test sont des activit\xe9s cl\xe9s de la conception des tests.","source":"Generadas (Test Design)"},{"id":250,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9nonc\xe9s suivants d\xe9crit un objectif de test valide\xa0?  ","options":["A) D\xe9montrer qu\'il n\'y a aucun d\xe9faut non corrig\xe9 dans le syst\xe8me test\xe9","B) D\xe9montrer qu\'il n\'y aura aucune panne apr\xe8s la mise en \u0153uvre du syst\xe8me en production","C) R\xe9duire le niveau de risque de l\'objet de test et renforcer la confiance dans le niveau de qualit\xe9 D) V\xe9rifier qu\'il n\'existe aucune combinaison d\'entr\xe9es non test\xe9e"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#1, LO\xa0: FL-1.1.1). Justification\xa0:\xa0R\xe9duire le niveau de risque de l\'objet de test et renforcer la confiance dans le niveau de qualit\xe9. D) V\xe9rifier qu\'il n\'existe aucune combinaison d\'entr\xe9es non test\xe9e.","source":"Official Sample Exam A Q#1"},{"id":251,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants montre un exemple d\u2019activit\xe9s de test qui contribuent au succ\xe8s\xa0?  ","options":["A) L\'implication des testeurs lors de diverses activit\xe9s du cycle de vie du d\xe9veloppement logiciel (SDLC) aidera \xe0 d\xe9tecter les d\xe9fauts dans les produits de travail.","B) Les testeurs essaient de ne pas d\xe9ranger les d\xe9veloppeurs pendant la programmation, afin que les d\xe9veloppeurs \xe9crivent un meilleur code","C) Les testeurs collaborant avec les utilisateurs finaux contribuent \xe0 am\xe9liorer la qualit\xe9 des rapports de d\xe9fauts lors des tests d\'int\xe9gration de composants et des tests du syst\xe8me."],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#2, LO : FL-1.2.1). Justification\xa0:\xa0l\'implication des testeurs lors de diverses activit\xe9s du cycle de vie du d\xe9veloppement logiciel (SDLC) aidera \xe0 d\xe9tecter les d\xe9fauts dans les produits de travail.","source":"Official Sample Exam A Q#2"},{"id":252,"chapter":1,"topic":"Fondamentaux des tests","question":"Vous avez \xe9t\xe9 affect\xe9 en tant que testeur \xe0 une \xe9quipe qui produit progressivement un nouveau syst\xe8me. Vous avez remarqu\xe9 qu\'aucune modification n\'a \xe9t\xe9 apport\xe9e aux cas de test de r\xe9gression existants depuis plusieurs it\xe9rations et qu\'aucun nouveau d\xe9faut de r\xe9gression n\'a \xe9t\xe9 identifi\xe9. Votre manager est content, mais vous ne l\'\xeates pas. Quel principe de preuve explique votre scepticisme ?  ","options":["A) Les tests s\'usent","B) Erreur d\'absence de d\xe9fauts","C) Les d\xe9fauts sont regroup\xe9s","D) Des tests exhaustifs sont impossibles"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#3, LO : FL-1.3.1). Justification\xa0:\xa0les preuves s\'usent","source":"Official Sample Exam A Q#3"},{"id":253,"chapter":1,"topic":"Fondamentaux des tests","question":"Vous travaillez dans une \xe9quipe qui d\xe9veloppe une application mobile pour commander de la nourriture. Dans l\'it\xe9ration actuelle, l\'\xe9quipe a d\xe9cid\xe9 d\'impl\xe9menter une fonctionnalit\xe9 de paiement. Laquelle des activit\xe9s suivantes fait partie de l\u2019analyse des tests\xa0?  ","options":["A) Estimez que le test de l\'int\xe9gration avec le service de paiement prendra 8 jours-personnes","B) D\xe9cidez que l\'\xe9quipe doit tester s\'il est possible de partager le paiement de mani\xe8re appropri\xe9e entre de nombreux utilisateurs.","C) Utiliser l\'analyse des valeurs limites (BVA) pour d\xe9river des donn\xe9es de test pour les cas de test qui v\xe9rifient le traitement correct des paiements pour le montant minimum autoris\xe9 \xe0 \xeatre pay\xe9.","D) Analyser l\'\xe9cart entre le r\xe9sultat r\xe9el et le r\xe9sultat attendu apr\xe8s avoir ex\xe9cut\xe9 un sc\xe9nario de test qui v\xe9rifie le processus de paiement par carte de cr\xe9dit et signaler un d\xe9faut"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#4, LO : FL-1.4.1). Justification\xa0:\xa0D\xe9cidez que l\'\xe9quipe doit tester s\'il est possible de partager le paiement de mani\xe8re appropri\xe9e entre de nombreux utilisateurs.","source":"Official Sample Exam A Q#4"},{"id":254,"chapter":1,"topic":"Fondamentaux des tests","question":"Parmi les facteurs suivants, lesquels ont une influence SIGNIFICATIVE sur l\'approche de test\xa0? Yo. Le SDLC  \\n  \\nii. Le nombre de d\xe9fauts d\xe9tect\xe9s dans les projets pr\xe9c\xe9dents  \\n  \\niii. Les risques li\xe9s aux produits identifi\xe9s  \\n  \\niv. Nouvelles exigences r\xe9glementaires exigeant des tests formels en bo\xeete blanche  \\n  \\nv. Mise en place de l\'environnement de test  ","options":["A) i, ii ont une influence significative","B) i, iii, iv ont une influence significative","C) ii, iv, v ont une influence significative","D) iii, v ont une influence significative"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#5, LO : FL-1.4.2). Justification\xa0:\xa0i, iii, iv ont une influence significative","source":"Official Sample Exam A Q#5"},{"id":255,"chapter":1,"topic":"Fondamentaux des tests","question":"Parmi les t\xe2ches suivantes, lesquelles appartiennent PRINCIPALEMENT \xe0 un r\xf4le de test\xa0?  ","options":["A) Mettre en place des environnements de test","B) Maintenir le backlog produit","C) Concevoir des solutions aux nouvelles exigences","D) Cr\xe9er le plan de test","E) Analyser la base de donn\xe9es factuelles"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#6, LO : FL-1.4.5). Justification\xa0: Mettre en place des environnements de test","source":"Official Sample Exam A Q#6"},{"id":256,"chapter":1,"topic":"Fondamentaux des tests","question":"Parmi les comp\xe9tences suivantes (i-v), lesquelles sont les PLUS importantes pour un testeur\xa0? Yo. Avoir une connaissance du domaine  \\n  \\nii. Cr\xe9er une vision du produit  \\n  \\niii. \xcatre un bon joueur d\'\xe9quipe  \\n  \\niv. Planifier et organiser le travail de l\'\xe9quipe  \\n  \\nv. Pens\xe9e critique  ","options":["A) ii et iv sont importants","B) i, iii et v sont importants","C) i, ii et v sont importants","D) iii et iv sont importants"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#7, LO : FL-1.5.1). Justification\xa0:\xa0i, iii et v sont importants","source":"Official Sample Exam A Q#7"},{"id":257,"chapter":1,"topic":"Fondamentaux des tests","question":"Comment l\u2019approche globale de l\u2019\xe9quipe est-elle pr\xe9sente dans les interactions entre testeurs et repr\xe9sentants m\xe9tiers ?  ","options":["A) Les repr\xe9sentants de l\'entreprise d\xe9cident des approches d\'automatisation des tests","B) Les testeurs aident les repr\xe9sentants de l\'entreprise \xe0 d\xe9finir une strat\xe9gie de test","C) Les repr\xe9sentants des entreprises ne font pas partie de l\'attention de toute l\'\xe9quipe","D) Les testeurs aident les repr\xe9sentants commerciaux \xe0 cr\xe9er des tests d\'acceptation appropri\xe9s"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#8, LO : FL-1.5.2). Justification\xa0: les testeurs aident les repr\xe9sentants des entreprises \xe0 cr\xe9er des tests d\'acceptation appropri\xe9s","source":"Official Sample Exam A Q#8"},{"id":289,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9nonc\xe9s suivants illustre pourquoi les tests sont n\xe9cessaires\xa0?  ","options":["A) Les tests dynamiques augmentent la qualit\xe9 en provoquant l\'\xe9chec des objets de test d\'une mani\xe8re que les utilisateurs ne pourraient jamais atteindre","B) Les tests statiques sont utilis\xe9s par les d\xe9veloppeurs pour identifier les bogues dans leur code plus t\xf4t que ne le permettent les tests dynamiques.","C) L\'analyse statique fournit la preuve aux clients que les \xe9l\xe9ments du syst\xe8me qui ne fournissent pas de r\xe9sultats peuvent \xeatre publi\xe9s.","D) Les r\xe9visions augmentent la qualit\xe9 des sp\xe9cifications des exigences et conduisent \xe0 moins de changements n\xe9cessaires dans les produits de travail d\xe9riv\xe9s"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon B, Q#1, LO : FL-1.2.1). Justification\xa0: Les r\xe9visions augmentent la qualit\xe9 des sp\xe9cifications des exigences et conduisent \xe0 moins de changements n\xe9cessaires dans les produits de travail d\xe9riv\xe9s.","source":"Official Sample Exam B Q#1"},{"id":290,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des affirmations suivantes sur l\'assurance qualit\xe9 (QA) et/ou le contr\xf4le qualit\xe9 (QC) est correcte ?  ","options":["A) La QA est r\xe9alis\xe9e dans le cadre des tests","B) Les tests sont r\xe9alis\xe9s dans le cadre du QC","C) Les tests sont un autre terme pour QC","D) Les tests sont r\xe9alis\xe9s dans le cadre de la QA"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#2, LO : FL-1.2.2). Justification : Les tests sont r\xe9alis\xe9s dans le cadre du QC.","source":"Official Sample Exam B Q#2"},{"id":291,"chapter":1,"topic":"Fondamentaux des tests","question":"L\'un des \xab principes des tests \xbb \xe9nonce que les tests exhaustifs sont impossibles. Lequel des \xe9l\xe9ments suivants est un exemple de la mani\xe8re d\'aborder ce principe en pratique ?  ","options":["A) Cr\xe9er des cas de test couvrant chaque sortie sp\xe9cifi\xe9e possible","B) Documenter toutes les variations d\'entr\xe9e de test possibles et les prioriser selon leur importance","C) Commencer les tests le plus t\xf4t possible avec des revues et d\'autres approches de tests statiques","D) Utiliser le partitionnement d\'\xe9quivalence et l\'analyse des valeurs limites pour g\xe9n\xe9rer des cas de test"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#3, LO : FL-1.3.1). Justification : Utiliser le partitionnement d\'\xe9quivalence et l\'analyse des valeurs limites pour g\xe9n\xe9rer des cas de test.","source":"Official Sample Exam B Q#3"},{"id":292,"chapter":1,"topic":"Fondamentaux des tests","question":"Quelle activit\xe9 de test consiste \xe0 travailler avec les exigences de donn\xe9es de test, les conditions de test, les exigences d\'environnement de test et les cas de test ?  ","options":["A) Conception des tests","B) Ex\xe9cution des tests","C) Analyse des tests","D) Impl\xe9mentation des tests"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#4, LO : FL-1.4.1). Justification : Conception des tests.","source":"Official Sample Exam B Q#4"},{"id":293,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants est le PLUS susceptible d\'avoir un impact sur la mani\xe8re dont les tests sont r\xe9alis\xe9s pour un objet de test donn\xe9 ?  ","options":["A) Le niveau d\'exp\xe9rience moyen de l\'\xe9quipe marketing de l\'organisation","B) La connaissance par les utilisateurs qu\'un nouveau syst\xe8me est d\xe9velopp\xe9 pour eux","C) Le nombre d\'ann\xe9es d\'exp\xe9rience des membres de l\'\xe9quipe de test","D) La structure organisationnelle de l\'utilisateur final pour une application commerciale de streaming musical"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#5, LO : FL-1.4.2). Justification : Le nombre d\'ann\xe9es d\'exp\xe9rience des membres de l\'\xe9quipe de test.","source":"Official Sample Exam B Q#5"},{"id":294,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des affirmations suivantes est un exemple CORRECT de la valeur de la tra\xe7abilit\xe9 ?  ","options":["A) La tra\xe7abilit\xe9 entre les risques att\xe9nu\xe9s et les cas de test r\xe9ussis fournit un moyen de d\xe9terminer le niveau de risque r\xe9siduel","B) La tra\xe7abilit\xe9 entre les exigences utilisateur et les r\xe9sultats des tests fournit un moyen de mesurer la progression du projet par rapport aux objectifs m\xe9tier","C) La tra\xe7abilit\xe9 entre les testeurs et les cas de test \xe9chou\xe9s fournit un moyen de d\xe9terminer le niveau de comp\xe9tence des testeurs","D) La tra\xe7abilit\xe9 entre les risques identifi\xe9s et les conditions de test \xe9crites fournit un moyen de d\xe9terminer quels risques valent la peine d\'\xeatre test\xe9s"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#6, LO : FL-1.4.4). Justification : La tra\xe7abilit\xe9 entre les exigences utilisateur et les r\xe9sultats des tests fournit un moyen de mesurer la progression du projet par rapport aux objectifs m\xe9tier.","source":"Official Sample Exam B Q#6"},{"id":295,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants est le PLUS probablement un exemple de testeur utilisant une comp\xe9tence g\xe9n\xe9rique lors des tests ?  ","options":["A) La connaissance approfondie du testeur d\'une vari\xe9t\xe9 de jeux vid\xe9o lui a permis de bien s\'entendre avec l\'un des d\xe9veloppeurs qui \xe9tait aussi un joueur","B) Le testeur \xe9tait un ancien pilote et a pu mieux comprendre les crit\xe8res d\'acceptation du syst\xe8me de contr\xf4le de l\'h\xe9licopt\xe8re","C) Le testeur avait travaill\xe9 auparavant comme programmeur et a utilis\xe9 ses comp\xe9tences dans ce domaine pour mieux communiquer avec les analystes m\xe9tier","D) Le testeur a pris grand soin de ne pas commettre d\'erreurs en g\xe9n\xe9rant m\xe9thodiquement des cas de test avant de commencer sa session de tests exploratoires"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#7, LO : FL-1.5.1). Justification : Le testeur \xe9tait un ancien pilote et a pu mieux comprendre les crit\xe8res d\'acceptation du syst\xe8me de contr\xf4le de l\'h\xe9licopt\xe8re.","source":"Official Sample Exam B Q#7"},{"id":296,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants est un avantage de l\'approche d\'\xe9quipe enti\xe8re (whole-team) ?  ","options":["A) Elle permet aux membres de l\'\xe9quipe d\'assumer n\'importe quel r\xf4le \xe0 tout moment","B) Elle n\'a besoin que d\'une seule \xe9quipe pour soutenir l\'ensemble du projet de d\xe9veloppement","C) Elle int\xe8gre les repr\xe9sentants m\xe9tier avec les d\xe9veloppeurs dans la m\xeame \xe9quipe","D) Elle g\xe9n\xe8re une synergie d\'\xe9quipe qui profite \xe0 l\'ensemble du projet"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#8, LO : FL-1.5.2). Justification : L\'approche d\'\xe9quipe enti\xe8re g\xe9n\xe8re une synergie qui profite \xe0 l\'ensemble du projet.","source":"Official Sample Exam B Q#8"},{"id":328,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants est un objectif typique des tests ?  ","options":["A) Valider que les exigences document\xe9es sont satisfaites","B) Provoquer des d\xe9faillances et identifier des d\xe9fauts","C) D\xe9clencher des erreurs et identifier les causes racines","D) V\xe9rifier que l\'objet de test r\xe9pond aux attentes de l\'utilisateur"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#1, LO : FL-1.1.1). Justification : Un objectif typique des tests est de provoquer des d\xe9faillances pour identifier des d\xe9fauts dans le logiciel.","source":"Official Sample Exam C Q#1"},{"id":329,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX la diff\xe9rence entre les tests et le d\xe9bogage (debugging) ?  ","options":["A) Les tests provoquent des d\xe9faillances tandis que le d\xe9bogage les corrige","B) Les tests sont une activit\xe9 n\xe9gative tandis que le d\xe9bogage est positif","C) Les tests d\xe9terminent que des d\xe9fauts existent tandis que le d\xe9bogage les \xe9limine","D) Les tests trouvent la cause des d\xe9fauts tandis que le d\xe9bogage la corrige"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#2, LO : FL-1.1.2). Justification : Les tests d\xe9terminent l\'existence de d\xe9fauts (au moyen des d\xe9faillances) ; le d\xe9bogage localise la cause racine et l\'\xe9limine.","source":"Official Sample Exam C Q#2"},{"id":330,"chapter":1,"topic":"Fondamentaux des tests","question":"L\'\xab erreur de l\'absence de d\xe9fauts \xbb (absence-of-defects fallacy) est l\'un des principes des tests. Lequel des \xe9l\xe9ments suivants est un exemple de la mani\xe8re d\'aborder ce principe en pratique ?  ","options":["A) Expliquer qu\'il n\'est pas possible pour les tests de prouver l\'absence de d\xe9fauts","B) Aider les utilisateurs finaux \xe0 r\xe9aliser des tests d\'acceptation","C) Garantir qu\'aucun d\xe9faut d\'impl\xe9mentation ne subsiste dans le syst\xe8me livr\xe9","D) Modifier les tests qui ne provoquent pas de d\xe9faillances pour s\'assurer qu\'il reste peu de d\xe9fauts"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#3, LO : FL-1.3.1). Justification : Aider les utilisateurs finaux dans les tests d\'acceptation garantit que le syst\xe8me r\xe9pond \xe0 leurs besoins r\xe9els, ce qui aborde l\'erreur selon laquelle \xab aucun d\xe9faut = syst\xe8me correct \xbb.","source":"Official Sample Exam C Q#3"},{"id":331,"chapter":1,"topic":"Fondamentaux des tests","question":"Quelles activit\xe9s de test sont le PLUS PROBABLEMENT celles qui impliquent l\'application de l\'analyse des valeurs limites et du partitionnement d\'\xe9quivalence ?  ","options":["A) Impl\xe9mentation des tests","B) Conception des tests","C) Ex\xe9cution des tests","D) Surveillance des tests","E) Analyse des tests"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#4, LO : FL-1.4.1). Justification : Les techniques de conception de tests comme l\'analyse des valeurs limites et le partitionnement d\'\xe9quivalence s\'appliquent pendant la conception des tests.","source":"Official Sample Exam C Q#4"},{"id":332,"chapter":1,"topic":"Fondamentaux des tests","question":"\xc9tant donn\xe9 le testware suivant : Laquelle des options suivantes montre le MIEUX le testware produit par chaque activit\xe9 ?\\n\\n1. \xc9l\xe9ments de couverture\\n2. Demandes de changement\\n3. Calendrier d\'ex\xe9cution des tests\\n4. Conditions de test prioris\xe9es\\n\\nA. Analyse des tests  \\nB. Conception des tests  \\nC. Impl\xe9mentation des tests  \\nD. Cl\xf4ture des tests","options":["A) 1B, 2D, 3C, 4A","B) 1B, 2D, 3A, 4C","C) 1D, 2C, 3A, 4B","D) 1D, 2C, 3B, 4A"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#5, LO : FL-1.4.3). Justification : Les \xe9l\xe9ments de couverture sont produits lors de la conception (1B), les demandes de changement lors de la cl\xf4ture (2D), le calendrier lors de l\'impl\xe9mentation (3C) et les conditions prioris\xe9es lors de l\'analyse (4A).","source":"Official Sample Exam C Q#5"},{"id":333,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des affirmations suivantes sur les diff\xe9rents r\xf4les de test est le PLUS PROBABLEMENT CORRECTE ?  ","options":["A) Dans le d\xe9veloppement logiciel agile, le r\xf4le de gestion des tests est principalement la responsabilit\xe9 de l\'\xe9quipe, tandis que le r\xf4le de test est la responsabilit\xe9 d\'un seul individu externe","B) Le r\xf4le de test est principalement responsable de la surveillance et du contr\xf4le des tests, tandis que le r\xf4le de gestion est responsable de la planification et de la cl\xf4ture","C) Dans le d\xe9veloppement logiciel agile, les activit\xe9s de gestion des tests couvrant plusieurs \xe9quipes sont g\xe9r\xe9es par un responsable des tests externe, tandis que certaines t\xe2ches de gestion sont assum\xe9es par l\'\xe9quipe elle-m\xeame","D) Le r\xf4le de gestion des tests est principalement responsable de l\'analyse et de la conception des tests, tandis que le r\xf4le de test est responsable de l\'impl\xe9mentation et de l\'ex\xe9cution"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#6, LO : FL-1.4.5). Justification : En Agile, les activit\xe9s de gestion qui concernent plusieurs \xe9quipes sont coordonn\xe9es par un responsable externe, tandis que l\'\xe9quipe g\xe8re ses propres activit\xe9s de test en interne.","source":"Official Sample Exam C Q#6"},{"id":334,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des affirmations suivantes sur l\'ind\xe9pendance des tests est CORRECTE ?  ","options":["A) Les testeurs ind\xe9pendants trouveront des d\xe9fauts gr\xe2ce \xe0 leur perspective technique diff\xe9rente de celle des d\xe9veloppeurs, bien que leur ind\xe9pendance puisse cr\xe9er une relation antagoniste","B) La familiarit\xe9 des d\xe9veloppeurs avec leur propre code fait qu\'ils ne trouvent que peu de d\xe9fauts ; cependant, leur formation similaire \xe0 celle des testeurs fait que ces derniers les trouveraient aussi","C) Les tests ind\xe9pendants n\xe9cessitent des testeurs ext\xe9rieurs \xe0 l\'\xe9quipe de d\xe9veloppement et id\xe9alement ext\xe9rieurs \xe0 l\'organisation, bien que ces personnes aient des difficult\xe9s \xe0 comprendre le domaine de l\'application","D) Les testeurs ext\xe9rieurs \xe0 l\'\xe9quipe du d\xe9veloppeur sont plus ind\xe9pendants, mais ceux \xe0 l\'int\xe9rieur de l\'\xe9quipe risquent davantage d\'\xeatre bl\xe2m\xe9s pour les retards de livraison"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#8, LO : FL-1.5.3). Justification : L\'ind\xe9pendance apporte une perspective diff\xe9rente qui aide \xe0 trouver plus de d\xe9fauts, mais peut cr\xe9er des tensions avec l\'\xe9quipe de d\xe9veloppement.","source":"Official Sample Exam C Q#8"},{"id":363,"chapter":1,"topic":"Fondamentaux des tests","question":"Un concepteur documente une conception d\'interface utilisateur qui ne sert pas correctement les utilisateurs malvoyants parce que le concepteur n\'\xe9tait pas au courant des exigences d\'accessibilit\xe9. Comment cela est-il class\xe9 selon la terminologie ISTQB ?  ","options":["A) Le concepteur a commis une d\xe9faillance qui a introduit une erreur dans la conception","B) Le concepteur a commis une erreur (mistake) qui a introduit un d\xe9faut dans la conception","C) Le concepteur a commis un d\xe9faut qui a entra\xeen\xe9 une d\xe9faillance dans la conception","D) Le concepteur a commis une erreur qui a introduit une d\xe9faillance dans la conception"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#1, LO : FL-1.2.2). Justification : Le manque de connaissance du concepteur (erreur humaine) entra\xeene un d\xe9faut dans le document de conception. Terminologie : Erreur -> D\xe9faut -> D\xe9faillance.","source":"Official Sample Exam D Q#2"},{"id":364,"chapter":1,"topic":"Fondamentaux des tests","question":"Les testeurs utilisent des conditions de test pour g\xe9n\xe9rer des cas de test et ex\xe9cuter des tests. Bien que les conditions de test restent les m\xeames, les cas de test varient \xe0 chaque fois. Lequel des \xab principes des tests \xbb est appliqu\xe9 en faisant varier les cas de test ?  ","options":["A) Les tests s\'usent (paradoxe du pesticide)","B) L\'erreur de l\'absence de d\xe9fauts","C) Les tests pr\xe9coces font gagner du temps et de l\'argent","D) Les d\xe9fauts se regroupent"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#3, LO : FL-1.3.1). Justification : Le paradoxe du pesticide (ou \xab les tests s\'usent \xbb) indique que r\xe9p\xe9ter les m\xeames cas de test cesse de d\xe9tecter de nouveaux d\xe9fauts, c\'est pourquoi il faut les faire varier.","source":"Official Sample Exam D Q#3"},{"id":365,"chapter":1,"topic":"Fondamentaux des tests","question":"\xc9tant donn\xe9 le testware suivant :  \\n  \\ni. Rapport de cl\xf4ture des tests  \\n  \\nii. Donn\xe9es dans une base de donn\xe9es utilis\xe9es comme entr\xe9es et r\xe9sultats attendus  \\n  \\niii. Liste des \xe9l\xe9ments n\xe9cessaires pour construire l\'environnement de test  \\n  \\niv. S\xe9quences document\xe9es de cas de test dans l\'ordre d\'ex\xe9cution  \\n  \\nv. Cas de test. Laquelle des options suivantes montre le MIEUX le testware produit \xe0 la suite de l\'impl\xe9mentation des tests ?  ","options":["A) ii, iv","B) iii, v","C) i, ii, v","D) i, iii, iv"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#5, LO : FL-1.4.3). Justification : Lors de l\'impl\xe9mentation des tests, les donn\xe9es de test (ii) et les s\xe9quences d\'ex\xe9cution/suites de test (iv) sont cr\xe9\xe9es.","source":"Official Sample Exam D Q#5"},{"id":366,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des options suivantes d\xe9crit le PLUS PROBABLEMENT une t\xe2che r\xe9alis\xe9e par quelqu\'un occupant un r\xf4le de gestion des tests ?  ","options":["A) \xc9valuer la base de test et l\'objet de test","B) D\xe9finir les exigences de l\'environnement de test","C) \xc9valuer la testabilit\xe9 de l\'objet de test","D) Cr\xe9er le rapport de cl\xf4ture des tests"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#6, LO : FL-1.4.5). Justification : Cr\xe9er le rapport de cl\xf4ture des tests est une t\xe2che de cl\xf4ture du processus, g\xe9n\xe9ralement la responsabilit\xe9 du responsable des tests.","source":"Official Sample Exam D Q#6"},{"id":367,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants est un avantage de l\'approche d\'\xe9quipe enti\xe8re (whole-team) ?  ","options":["A) Elle am\xe9liore la communication entre les membres de l\'\xe9quipe","B) Elle diminue la responsabilit\xe9 individuelle vis-\xe0-vis de la qualit\xe9","C) Elle acc\xe9l\xe8re le d\xe9ploiement des livrables aux utilisateurs finaux","D) Elle r\xe9duit la collaboration avec les utilisateurs m\xe9tier externes"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#7, LO : FL-1.5.2). Justification : L\'approche d\'\xe9quipe enti\xe8re favorise la collaboration entre tous les membres de l\'\xe9quipe, am\xe9liorant la communication.","source":"Official Sample Exam D Q#7"},{"id":368,"chapter":1,"topic":"Fondamentaux des tests","question":"\xc9tant donn\xe9s les avantages et inconv\xe9nients suivants de l\'ind\xe9pendance des tests :  \\n  \\ni. Les testeurs travaillent dans un lieu diff\xe9rent de celui des d\xe9veloppeurs  \\n  \\nii. Les testeurs remettent en question les hypoth\xe8ses que les programmeurs font en \xe9crivant le code  \\n  \\niii. Une dynamique de confrontation s\'est \xe9tablie entre testeurs et d\xe9veloppeurs  \\n  \\niv. Les d\xe9veloppeurs se sont convaincus que les testeurs sont les principaux responsables de la qualit\xe9  \\n  \\nv. Les testeurs ont des biais diff\xe9rents de ceux des d\xe9veloppeurs. Lesquels sont le PLUS PROBABLEMENT consid\xe9r\xe9s comme des avantages ?  ","options":["A) i, iv","B) ii, v","C) i, iii, iv","D) ii, iii, v"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#8, LO : FL-1.5.3). Justification : Remettre en question les hypoth\xe8ses (ii) et avoir des biais diff\xe9rents (v) sont des avantages de l\'ind\xe9pendance ; les autres sont des inconv\xe9nients ou des cons\xe9quences n\xe9gatives.","source":"Official Sample Exam D Q#8"},{"id":399,"chapter":1,"topic":"Fondamentaux des tests","question":"\xc9tant donn\xe9es les t\xe2ches de test suivantes : Quelle est la MEILLEURE correspondance ?\\n\\n1. D\xe9river les cas de test \xe0 partir des conditions\\n2. Identifier le testware r\xe9utilisable\\n3. Organiser les cas de test en proc\xe9dures\\n4. \xc9valuer la base de test ; et les activit\xe9s :\\n\\nA. Analyse  \\nB. Conception  \\nC. Impl\xe9mentation  \\nD. Cl\xf4ture","options":["A) 1B, 2A, 3D, 4C","B) 1B, 2D, 3C, 4A","C) 1C, 2A, 3B, 4D","D) 1C, 2D, 3A, 4B"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#4, LO : FL-1.4.1). Justification : 1B, 2D, 3C, 4A.","source":"Official Sample Exam D Q#4"},{"id":407,"chapter":1,"topic":"Fondamentaux des tests","question":"Votre \xe9quipe a d\xe9tect\xe9 45 d\xe9fauts dans le module A (5 000 lignes de code) et 12 d\xe9fauts dans le module B (8 000 lignes). Selon le principe du \xab regroupement des d\xe9fauts \xbb, quelle conclusion est la PLUS correcte ?  ","options":["A) Le module B pr\xe9sente plus de risque car il a plus de code","B) Le module A a une densit\xe9 de d\xe9fauts plus \xe9lev\xe9e et devrait recevoir plus d\'effort de test","C) Les deux modules ont le m\xeame niveau de risque","D) Les d\xe9fauts sont r\xe9partis uniform\xe9ment entre les deux modules"],"correctAnswer":1,"explanation":"Le module A a une densit\xe9 de 45/5000=0,009 d\xe9faut/ligne contre B avec 12/8000=0,0015. Le principe du regroupement indique que les d\xe9fauts se concentrent dans peu de modules ; A m\xe9rite plus d\'effort.","source":"banco"},{"id":408,"chapter":1,"topic":"Fondamentaux des tests","question":"Un testeur ex\xe9cute le m\xeame ensemble de tests de r\xe9gression pendant 6 sprints cons\xe9cutifs sans modifications. Selon les principes ISTQB, quel probl\xe8me survient et quelle est la solution ?  ","options":["A) Il n\'y a aucun probl\xe8me ; les tests de r\xe9gression doivent \xeatre stables","B) Paradoxe du pesticide : les tests cessent de trouver de nouveaux d\xe9fauts ; revoir et mettre \xe0 jour l\'ensemble de tests","C) Absence de d\xe9fauts : le logiciel n\'a plus de bugs","D) Les tests pr\xe9coces g\xe9n\xe8rent des faux positifs accumul\xe9s"],"correctAnswer":1,"explanation":"Le paradoxe du pesticide \xe9nonce que si les m\xeames tests sont r\xe9p\xe9t\xe9s sans changement, ils finissent par cesser de trouver de nouveaux d\xe9fauts. La solution est de revoir et mettre \xe0 jour p\xe9riodiquement les tests.","source":"banco"},{"id":419,"chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants est un exemple de test NON fonctionnel ?  ","options":["A) V\xe9rifier que la connexion rejette les mots de passe incorrects","B) V\xe9rifier que la page d\'accueil se charge en moins de 3 secondes avec 500 utilisateurs simultan\xe9s","C) Valider que le calcul de la TVA est correct","D) Confirmer que le bouton \xab Enregistrer \xbb stocke les donn\xe9es dans la base de donn\xe9es"],"correctAnswer":1,"explanation":"Les tests non fonctionnels \xe9valuent des attributs de qualit\xe9 comme la performance, l\'utilisabilit\xe9 et la s\xe9curit\xe9. L\'option B est un test de performance (charge), qui est non fonctionnel.","source":"banco"},{"id":429,"chapter":1,"topic":"Fondamentaux des tests","question":"Votre entreprise d\xe9veloppe un logiciel de contr\xf4le de vol. Le co\xfbt d\'une d\xe9faillance est catastrophique. Lequel des principes ISTQB suivants justifie d\'investir davantage dans les tests que dans des projets \xe0 faible risque ?  ","options":["A) Les tests exhaustifs sont possibles avec suffisamment de ressources","B) Les tests d\xe9pendent du contexte : le niveau de rigueur doit \xeatre adapt\xe9 au risque et aux cons\xe9quences de la d\xe9faillance","C) L\'absence de d\xe9fauts est une erreur","D) Les tests pr\xe9coces font gagner du temps et de l\'argent"],"correctAnswer":1,"explanation":"Le principe \xab Les tests d\xe9pendent du contexte \xbb \xe9nonce que l\'approche, les techniques et l\'intensit\xe9 des tests varient selon le domaine, le risque et les cons\xe9quences. Un logiciel critique exige une plus grande rigueur.","source":"banco"},{"id":430,"chapter":1,"topic":"Fondamentaux des tests","question":"Lors des tests syst\xe8me, un d\xe9faut est trouv\xe9 dans le module de facturation. Le d\xe9veloppeur le corrige. Ensuite, le testeur d\xe9couvre que la correction a introduit une nouvelle erreur dans le module d\'inventaire. Comment appelle-t-on ce type de d\xe9faut introduit ?  ","options":["A) D\xe9faut de r\xe9gression","B) D\xe9faut d\'int\xe9gration","C) D\xe9faut de mutation","D) D\xe9faut de confirmation"],"correctAnswer":0,"explanation":"Un d\xe9faut de r\xe9gression est un d\xe9faut introduit par inadvertance par un changement (comme une correction de bug). Les tests de r\xe9gression sont sp\xe9cifiquement con\xe7us pour les d\xe9tecter.","source":"banco"},{"id":440,"chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des activit\xe9s suivantes rel\xe8ve de la responsabilit\xe9 du responsable des tests (Test Manager) et non du testeur individuel ?  ","options":["A) Ex\xe9cuter les cas de test","B) Signaler les d\xe9fauts trouv\xe9s","C) Coordonner la strat\xe9gie de test et communiquer l\'\xe9tat au projet","D) Concevoir des donn\xe9es de test sp\xe9cifiques"],"correctAnswer":2,"explanation":"Le responsable des tests coordonne, planifie, surveille et contr\xf4le les activit\xe9s de test, d\xe9finit la strat\xe9gie et communique la progression. Les testeurs individuels ex\xe9cutent, con\xe7oivent des cas et signalent des d\xe9fauts.","source":"banco"},{"id":446,"chapter":1,"topic":"Fondamentaux des tests","question":"Selon l\'ISTQB CTFL v4.0, quels sont les 7 principes des tests ?  ","options":["A) Les tests montrent la pr\xe9sence de d\xe9fauts ; les tests exhaustifs sont impossibles ; tester t\xf4t ; regroupement des d\xe9fauts ; paradoxe du pesticide ; les tests d\xe9pendent du contexte ; l\'erreur de l\'absence de d\xe9fauts","B) Les tests \xe9liminent tous les d\xe9fauts ; les tests exhaustifs sont possibles ; tester \xe0 la fin ; d\xe9fauts uniformes ; les tests ne d\xe9pendent pas du contexte","C) Il n\'y a que 4 principes dans l\'ISTQB v4.0","D) Les 7 principes incluent : automatisation obligatoire, tests agiles, CI/CD, shift-left, shift-right, DevOps et TDD"],"correctAnswer":0,"explanation":"Les 7 principes ISTQB sont : 1) Les tests montrent la pr\xe9sence de d\xe9fauts 2) Les tests exhaustifs sont impossibles 3) Tester t\xf4t fait \xe9conomiser de l\'argent 4) Regroupement des d\xe9fauts 5) Paradoxe du pesticide 6) Les tests d\xe9pendent du contexte 7) Erreur de l\'absence de d\xe9fauts.","source":"banco"},{"id":454,"chapter":1,"topic":"Fondamentaux des tests","question":"CAS PRATIQUE : L\'\xe9quipe a ex\xe9cut\xe9 500 tests et trouv\xe9 0 d\xe9faut. Le product owner veut livrer le logiciel en affirmant qu\'il \xab est exempt de bugs \xbb. Quelle est votre r\xe9ponse bas\xe9e sur les principes ISTQB ?  ","options":["A) Vous \xeates d\'accord, 500 tests sans d\xe9faut est une preuve suffisante","B) Les tests montrent seulement qu\'aucun d\xe9faut n\'a \xe9t\xe9 trouv\xe9 avec cet ensemble de tests ; ils ne peuvent pas prouver leur absence totale (Principe 1). Livrer comporte un risque r\xe9siduel","C) Vous devez ajouter 500 tests de plus pour \xeatre s\xfbr","D) Demander des tests exhaustifs de tous les chemins possibles"],"correctAnswer":1,"explanation":"Principe 1 ISTQB : \xab Les tests montrent la pr\xe9sence de d\xe9fauts, pas leur absence \xbb. 0 d\xe9faut sur 500 tests ne garantit pas un logiciel exempt de bugs, seulement que cet ensemble de tests ne les a pas trouv\xe9s. Un risque r\xe9siduel existe toujours.","source":"banco"},{"id":460,"chapter":1,"topic":"Fondamentaux des tests","question":"Qu\'est-ce qui d\xe9crit le mieux le concept de \xab shift-left \xbb dans les tests ?  ","options":["A) D\xe9placer les tests vers le c\xf4t\xe9 gauche de l\'\xe9cran","B) Commencer les activit\xe9s de test plus t\xf4t dans le cycle de vie du d\xe9veloppement","C) R\xe9duire le nombre de testeurs dans l\'\xe9quipe","D) Automatiser tous les tests de r\xe9gression"],"correctAnswer":1,"explanation":"Le shift-left signifie avancer (d\xe9placer vers la gauche sur la ligne du temps) les activit\xe9s de test : revoir les exigences, faire des tests de composants plus t\xf4t, utiliser TDD/ATDD, etc. L\'objectif est de d\xe9tecter les d\xe9fauts plus t\xf4t pour r\xe9duire les co\xfbts.","source":"banco"},{"id":466,"chapter":1,"topic":"Fondamentaux des tests","question":"Quelle est la diff\xe9rence entre la v\xe9rification et la validation dans les tests ?  ","options":["A) Elles sont exactement identiques","B) V\xe9rification : construisons-nous le produit correctement ? Validation : construisons-nous le bon produit ?","C) La v\xe9rification est faite par les utilisateurs ; la validation par les testeurs","D) La v\xe9rification est dynamique ; la validation est statique"],"correctAnswer":1,"explanation":"La v\xe9rification contr\xf4le que le produit respecte ses sp\xe9cifications (\xab le construisons-nous correctement ? \xbb). La validation contr\xf4le que le produit satisfait les besoins r\xe9els de l\'utilisateur (\xab construisons-nous la bonne chose ? \xbb).","source":"banco"},{"id":"q_batch2_1thtnzqjs","chapter":1,"topic":"Fondamentaux des tests","question":"Quelles comp\xe9tences sont essentielles pour un testeur dans le contexte des tests logiciels ? Comprendre les exigences du client D\xe9velopper des comp\xe9tences en programmation R\xe9aliser uniquement des tests manuels Communiquer clairement les constatations des tests  ","options":["i et iv sont essentielles ; ii et iii ne le sont pas","ii et iii sont essentielles ; i et iv ne le sont pas","i et ii sont essentielles ; iii et iv ne le sont pas","ii et iv sont essentielles ; i et iii ne le sont pas"],"correctAnswer":0,"explanation":"A. i. Vrai. Comprendre les exigences du client est fondamental pour garantir l\'efficacit\xe9 des tests. iv. Vrai. Communiquer les constatations est crucial dans le processus de test. ii. Faux. Bien que d\xe9velopper des comp\xe9tences en programmation puisse \xeatre utile, ce n\'est pas essentiel pour tous les testeurs. iii. Faux. R\xe9aliser uniquement des tests manuels limite l\'approche du testeur et n\'est pas la seule fa\xe7on de tester. B, C et D sont incorrectes car elles classent mal certaines de ces comp\xe9tences (i et iv sont les essentielles).","source":"banco-extra"},{"id":"q_batch2_3ur6idl31","chapter":1,"topic":"Fondamentaux des tests","question":"Quelle est une raison cl\xe9 pour laquelle les tests sont n\xe9cessaires dans le d\xe9veloppement logiciel ?  ","options":["Pour garantir que le logiciel r\xe9pond aux exigences du client.","Pour augmenter le temps de d\xe9veloppement du projet.","Pour diminuer la satisfaction de l\'utilisateur final.","Pour r\xe9duire la collaboration entre les \xe9quipes de d\xe9veloppement."],"correctAnswer":0,"explanation":"A. Cette option est correcte car les tests aident \xe0 v\xe9rifier que le logiciel fonctionne comme pr\xe9vu et r\xe9pond aux besoins du client. B. Incorrect. Les tests sont con\xe7us pour identifier les probl\xe8mes et les erreurs, ce qui peut aider \xe0 r\xe9duire le temps de d\xe9veloppement \xe0 long terme. C. Incorrect. Les tests visent \xe0 am\xe9liorer la qualit\xe9 du logiciel, ce qui augmente g\xe9n\xe9ralement la satisfaction de l\'utilisateur final. D. Incorrect. Les tests ne doivent pas r\xe9duire la collaboration, mais plut\xf4t favoriser la communication et le travail d\'\xe9quipe pour obtenir un produit de qualit\xe9.","source":"banco-extra"},{"id":"q_batch2_7tzjynf4k","chapter":1,"topic":"Fondamentaux des tests","question":"Laquelle des affirmations suivantes d\xe9crit un avantage d\'obtenir un feedback pr\xe9coce et fr\xe9quent des parties prenantes ?  ","options":["Elle permet de r\xe9aliser des tests plus exhaustifs \xe0 la fin du cycle de d\xe9veloppement.","Elle facilite l\'identification pr\xe9coce des probl\xe8mes et des ajustements n\xe9cessaires.","Elle r\xe9duit le nombre de livraisons interm\xe9diaires au client.","Elle augmente la complexit\xe9 du processus de d\xe9veloppement."],"correctAnswer":1,"explanation":"A. Incorrect. Obtenir un feedback pr\xe9coce ne consiste pas \xe0 r\xe9aliser des tests exhaustifs \xe0 la fin, mais \xe0 traiter les probl\xe8mes plus t\xf4t dans le processus. B. Correct. Le feedback pr\xe9coce et fr\xe9quent permet d\'identifier les probl\xe8mes \xe0 temps, ce qui facilite les ajustements n\xe9cessaires. C. Incorrect. Le feedback fr\xe9quent peut en fait augmenter le nombre de livraisons interm\xe9diaires pour s\'assurer que les exigences sont respect\xe9es. D. Incorrect. Le feedback pr\xe9coce vise \xe0 simplifier le processus en clarifiant les exigences et les attentes avec les parties prenantes.","source":"banco-extra"},{"id":"q_batch2_butb18o4u","chapter":1,"topic":"Fondamentaux des tests","question":"Lequel des \xe9l\xe9ments suivants peut modifier l\'approche de test dans un projet logiciel ? Le nombre d\'employ\xe9s dans le service commercial de l\'entreprise La complexit\xe9 du logiciel \xe0 tester Le budget allou\xe9 au projet L\'utilisation d\'outils automatis\xe9s  ","options":["i, ii, iii peuvent modifier l\'approche de test","ii, iii, iv peuvent modifier l\'approche de test","i, iii, iv peuvent modifier l\'approche de test","i, ii, iv peuvent modifier l\'approche de test"],"correctAnswer":1,"explanation":"A. Incorrect. i. Faux : le nombre d\'employ\xe9s du service commercial n\'est pas un facteur du contexte de test selon le syllabus CTFL v4.0, section 1.4.2. ii, iii et iv sont vrais. En incluant i, cette option est incorrecte. B. Correct. i. Faux : le nombre d\'employ\xe9s du service commercial n\'est pas un facteur du contexte de test. ii. Vrai : la complexit\xe9 du logiciel est une caract\xe9ristique du produit reconnue comme facteur de contexte (syllabus 1.4.2). iii. Vrai : les contraintes de budget sont des facteurs op\xe9rationnels explicitement list\xe9s (syllabus 1.4.2). iv. Vrai : les outils disponibles font partie des facteurs techniques du contexte (syllabus 1.4.2). C. Incorrect. En incluant i (faux), cette option est incorrecte. D. Incorrect. En incluant i (faux), cette option est incorrecte.","source":"banco-extra"},{"id":"q_batch2_il2jaia8g","chapter":1,"topic":"Fondamentaux des tests","question":"Quel est l\'un des avantages les plus importants de l\'approche d\'\xe9quipe enti\xe8re dans le processus de test ?  ","options":["Elle am\xe9liore la communication et la collaboration entre tous les membres de l\'\xe9quipe.","Elle permet aux testeurs de travailler de mani\xe8re isol\xe9e pour mieux se concentrer sur leurs t\xe2ches.","Elle r\xe9duit le besoin de documentation approfondie dans le processus de test.","Elle facilite l\'attribution des t\xe2ches de test \xe0 diff\xe9rents services."],"correctAnswer":0,"explanation":"A. Correct. L\'approche d\'\xe9quipe enti\xe8re favorise la communication et la collaboration entre testeurs, d\xe9veloppeurs et repr\xe9sentants m\xe9tier, ce qui se traduit par un processus de test plus efficace. B. Incorrect. L\'approche d\'\xe9quipe enti\xe8re met l\'accent sur le travail d\'\xe9quipe, pas sur l\'isolement. C. Incorrect. Bien qu\'elle puisse r\xe9duire le besoin de documentation, l\'approche d\'\xe9quipe enti\xe8re ne vise pas \xe0 l\'\xe9liminer compl\xe8tement. D. Incorrect. L\'approche d\'\xe9quipe enti\xe8re favorise la collaboration plut\xf4t que l\'attribution des t\xe2ches entre services s\xe9par\xe9s.","source":"banco-extra"},{"id":1009,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le mieux l\'importance des tests dans le cycle de vie de d\xe9veloppement logiciel (SDLC) ?  ","options":["Les tests sont r\xe9alis\xe9s uniquement \xe0 la fin du SDLC pour v\xe9rifier le produit final.","Les tests doivent \xeatre planifi\xe9s et r\xe9alis\xe9s tout au long du SDLC pour d\xe9tecter les probl\xe8mes t\xf4t.","Les tests sont optionnels et ne sont n\xe9cessaires que si le client le demande.","Les tests se concentrent uniquement sur la fonctionnalit\xe9 du logiciel et pas sur d\'autres aspects."],"correctAnswer":1,"explanation":"R\xe9aliser les tests tout au long du SDLC (shift-left) est essentiel pour d\xe9tecter et corriger les probl\xe8mes le plus t\xf4t possible.","source":"Pr\xe1ctica Adicional"},{"id":1010,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des descriptions suivantes se rapporte le MIEUX au d\xe9veloppement pilot\xe9 par les tests (TDD) ?  ","options":["Dans le TDD, les tests sont \xe9crits avant le code et utilis\xe9s pour guider le d\xe9veloppement.","Dans le TDD, les d\xe9veloppeurs cr\xe9ent d\'abord le code puis les cas de test correspondants.","Dans le TDD, les tests ne sont r\xe9alis\xe9s qu\'\xe0 la fin du cycle de d\xe9veloppement pour v\xe9rifier le produit.","Dans le TDD, les cas de test d\'acceptation sont utilis\xe9s comme base pour la conception du code."],"correctAnswer":0,"explanation":"Le TDD consiste \xe0 \xe9crire les tests (unitaires) avant d\'\xe9crire le code source qui les fait passer.","source":"Pr\xe1ctica Adicional"},{"id":1011,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le mieux comment l\'approche \xab d\xe9calage vers la gauche \xbb (shift-left) peut am\xe9liorer la qualit\xe9 du logiciel ?  ","options":["Elle permet de d\xe9tecter et corriger les d\xe9fauts dans les \xe9tapes ult\xe9rieures du cycle de vie du d\xe9veloppement.","Elle facilite l\'int\xe9gration continue et la livraison pr\xe9coce de valeur au client en trouvant les erreurs t\xf4t.","Elle augmente la complexit\xe9 du processus de d\xe9veloppement en introduisant plus de tests dans les phases initiales.","Elle r\xe9duit le besoin de documentation en appliquant plus de tests utilisateur \xe0 la fin du cycle."],"correctAnswer":1,"explanation":"D\xe9placer les tests vers la gauche permet de trouver les erreurs plus t\xf4t, am\xe9liorant l\'int\xe9gration et r\xe9duisant les co\xfbts.","source":"Pr\xe1ctica Adicional"},{"id":1012,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Quel est un avantage cl\xe9 de la tenue de r\xe9trospectives dans une \xe9quipe de travail ?  ","options":["Elles permettent \xe0 l\'\xe9quipe d\'ignorer les probl\xe8mes de communication qui peuvent survenir pendant le projet.","Elles aident \xe0 identifier et promouvoir les pratiques qui ont \xe9t\xe9 efficaces par le pass\xe9 et qui peuvent \xeatre appliqu\xe9es dans les cycles futurs.","Elles sont une formalit\xe9 \xe0 accomplir sans g\xe9n\xe9rer d\'impact r\xe9el sur le projet.","Elles facilitent la prise de contr\xf4le total du processus par les responsables d\'\xe9quipe sans tenir compte des opinions."],"correctAnswer":1,"explanation":"Les r\xe9trospectives sont le moteur de l\'am\xe9lioration continue (identifier ce qui a fonctionn\xe9 et ce qui n\'a pas fonctionn\xe9).","source":"Pr\xe1ctica Adicional"},{"id":1013,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Lesquelles des affirmations suivantes d\xe9crivent correctement les niveaux de test et leurs approches ?\\n\\n1. Valide la fonctionnalit\xe9 compl\xe8te dans un environnement de production simul\xe9\\n2. V\xe9rifie que les modules individuels fonctionnent\\n3. Garantit que les modules s\'int\xe8grent ensemble\\n4. Valide les exigences du point de vue de l\'utilisateur final\\n\\nA. Tests syst\xe8me  \\nB. Tests de composants  \\nC. Tests d\'int\xe9gration  \\nD. Tests d\'acceptation","options":["1A, 2B, 3C, 4D","1C, 2A, 3D, 4B","1D, 2C, 3A, 4B","1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"1 : Syst\xe8me (A), 2 : Composants (B), 3 : Int\xe9gration (C), 4 : Acceptation (D).","source":"Pr\xe1ctica Adicional"},{"id":1037,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Identifiez les cat\xe9gories de test suivantes (1-4) et les quadrants de tests agiles (A-D). Quelles combinaisons sont correctes ?\\n\\n1. Tests d\'utilisabilit\xe9\\n2. Tests de composants\\n3. Tests fonctionnels\\n4. Tests de fiabilit\xe9\\n\\nA (Q1). Technologie / soutient l\'\xe9quipe  \\nB (Q2). M\xe9tier / soutient l\'\xe9quipe  \\nC (Q3). M\xe9tier / critique le produit  \\nD (Q4). Technologie / critique le produit","options":["1C, 2A, 3B, 4D","1D, 2A, 3C, 4B","1C, 2B, 3D, 4A","1D, 2B, 3C, 4A"],"correctAnswer":0,"explanation":"Utilisabilit\xe9 -> Q3 (1C). Composants -> Q1 (2A). Fonctionnels -> Q2 (3B). Fiabilit\xe9 -> Q4 (4D).","source":"Errores Reportados - Set 2"},{"id":1040,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le mieux l\'objectif des r\xe9trospectives dans une \xe9quipe agile ?  ","options":["Les r\xe9trospectives sont principalement utilis\xe9es pour planifier les prochaines t\xe2ches et attribuer les responsabilit\xe9s aux membres de l\'\xe9quipe.","Les r\xe9trospectives aident \xe0 identifier ce qui a fonctionn\xe9 et ce qui n\'a pas fonctionn\xe9, permettant \xe0 l\'\xe9quipe d\'ajuster son processus pour une am\xe9lioration continue.","Les r\xe9trospectives sont des r\xe9unions o\xf9 les r\xe9sultats finaux du projet sont pr\xe9sent\xe9s aux parties prenantes.","Les r\xe9trospectives sont essentielles pour \xe9valuer la satisfaction du client vis-\xe0-vis du produit livr\xe9."],"correctAnswer":1,"explanation":"L\'objectif principal des r\xe9trospectives est d\'identifier les axes d\'am\xe9lioration dans le processus de travail de l\'\xe9quipe, favorisant l\'am\xe9lioration continue.","source":"Errores Reportados - Set 2"},{"id":1047,"chapter":2,"topic":"Tests tout au long du SDLC","question":"\xc0 quel quadrant agile appartiennent les tests de performance, de s\xe9curit\xe9 et de fiabilit\xe9, et quel est leur objectif principal ?  ","options":["Quadrant Q1 ; orient\xe9s technologie pour soutenir l\'\xe9quipe.","Quadrant Q3 ; orient\xe9s m\xe9tier pour critiquer le produit.","Quadrant Q4 ; orient\xe9s technologie pour critiquer le produit.","Quadrant Q2 ; orient\xe9s m\xe9tier pour soutenir l\'\xe9quipe."],"correctAnswer":2,"explanation":"Les tests d\'attributs de qualit\xe9 (performance, s\xe9curit\xe9, fiabilit\xe9) se trouvent dans le quadrant Q4. Ils sont orient\xe9s technologie et leur objectif est de \xab critiquer le produit \xbb (\xe9valuer le produit par rapport \xe0 des m\xe9triques techniques).","source":"Generadas (Agile/Metrics)"},{"id":1048,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Pendant le d\xe9veloppement d\'un sprint, l\'\xe9quipe r\xe9alise des tests exploratoires et des tests d\'utilisabilit\xe9 pour \xe9valuer le syst\xe8me du point de vue de l\'utilisateur r\xe9el. Dans quel quadrant agile ces tests se situent-ils ?  ","options":["Q1 (Support technologique, orient\xe9s technologie)","Q2 (Support m\xe9tier, orient\xe9s m\xe9tier)","Q3 (Critique du produit, orient\xe9s m\xe9tier)","Q4 (Critique du produit, orient\xe9s technologie)"],"correctAnswer":2,"explanation":"Les tests exploratoires et d\'utilisabilit\xe9 font partie du quadrant Q3. Leur objectif est de critiquer le produit en l\'\xe9valuant du point de vue orient\xe9 m\xe9tier (l\'utilisateur r\xe9el).","source":"Generadas (Agile/Metrics)"},{"id":1056,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le mieux l\'importance des tests dans le cycle de vie de d\xe9veloppement logiciel (SDLC) ?  ","options":["Les tests sont r\xe9alis\xe9s uniquement \xe0 la fin du SDLC pour v\xe9rifier le produit final.","Les tests doivent \xeatre planifi\xe9s et r\xe9alis\xe9s tout au long du SDLC pour d\xe9tecter les probl\xe8mes t\xf4t.","Les tests sont optionnels et ne sont n\xe9cessaires que si le client le demande.","Les tests se concentrent uniquement sur la fonctionnalit\xe9 du logiciel et pas sur d\'autres aspects."],"correctAnswer":1,"explanation":"A. Incorrect. Les tests doivent \xeatre int\xe9gr\xe9s \xe0 chaque phase du SDLC, pas seulement \xe0 la fin. B. Correct. Planifier et r\xe9aliser les tests tout au long du SDLC aide \xe0 identifier et r\xe9soudre les probl\xe8mes \xe0 temps. C. Incorrect. Les tests sont fondamentaux et ne doivent pas \xeatre optionnels. D. Incorrect. Les tests doivent traiter \xe0 la fois la fonctionnalit\xe9 et d\'autres aspects comme l\'utilisabilit\xe9 et la performance.","source":"Generadas (SDLC)"},{"id":1058,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Quel est l\'un des principaux avantages de la tenue de r\xe9trospectives p\xe9riodiques dans une \xe9quipe de d\xe9veloppement ?  ","options":["Elles permettent aux membres de l\'\xe9quipe de partager leurs opinions sur le produit final sans restrictions.","Elles facilitent l\'identification de sch\xe9mas de communication qui peuvent am\xe9liorer la collaboration au sein de l\'\xe9quipe.","Elles offrent un espace pour que l\'\xe9quipe \xe9value et ajuste son processus de travail en fonction de ce qui a \xe9t\xe9 appris au cycle pr\xe9c\xe9dent.","Elles aident \xe0 \xe9tablir des m\xe9triques pour mesurer la performance du produit fini."],"correctAnswer":2,"explanation":"A. Incorrect. L\'objectif principal des r\xe9trospectives porte sur le processus, pas sur le produit. B. Incorrect. Identifier des sch\xe9mas de communication n\'est pas l\'objectif principal. C. Correct. Les r\xe9trospectives sont fondamentales pour que l\'\xe9quipe \xe9value et ajuste son processus en fonction de l\'exp\xe9rience pr\xe9c\xe9dente, contribuant \xe0 l\'am\xe9lioration continue. D. Incorrect. Les r\xe9trospectives ne sont pas centr\xe9es sur l\'\xe9tablissement de m\xe9triques pour le produit.","source":"Generadas (Retrospectivas)"},{"id":1059,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Quel est un avantage cl\xe9 de la tenue de r\xe9trospectives \xe0 la fin d\'un projet ?  ","options":["Permettre aux membres de l\'\xe9quipe de partager leurs opinions sur la derni\xe8re livraison du projet.","G\xe9n\xe9rer un environnement de critique o\xf9 seules les erreurs de l\'\xe9quipe sont mentionn\xe9es.","Faciliter l\'identification des le\xe7ons apprises qui peuvent \xeatre appliqu\xe9es dans de futurs projets.","S\'assurer que tous les membres de l\'\xe9quipe ont l\'occasion de s\'exprimer sans une attention claire port\xe9e aux processus."],"correctAnswer":2,"explanation":"A. Incorrect. Bien que partager des opinions fasse partie des r\xe9trospectives, l\'objectif principal est l\'am\xe9lioration continue. B. Incorrect. Les r\xe9trospectives ne doivent pas \xeatre un espace de critique n\xe9gative. C. Correct. Identifier les le\xe7ons apprises est fondamental pour appliquer des am\xe9liorations dans de futurs projets. D. Incorrect. Les r\xe9trospectives doivent avoir une attention claire port\xe9e \xe0 l\'am\xe9lioration des processus.","source":"Generadas (Retrospectivas)"},{"id":1060,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des descriptions suivantes est le mieux associ\xe9e au d\xe9veloppement pilot\xe9 par les tests (TDD) ?  ","options":["Dans le TDD, les cas de test sont cr\xe9\xe9s d\'abord puis le code est d\xe9velopp\xe9 pour les faire passer.","Dans le TDD, le code est \xe9crit puis des tests manuels sont g\xe9n\xe9r\xe9s pour v\xe9rifier son fonctionnement.","Dans le TDD, les tests ne sont r\xe9alis\xe9s qu\'apr\xe8s que toute la fonctionnalit\xe9 a \xe9t\xe9 impl\xe9ment\xe9e.","Dans le TDD, on se concentre uniquement sur les tests d\'int\xe9gration et pas sur les tests unitaires."],"correctAnswer":0,"explanation":"A. Correct. Le TDD repose sur le cycle consistant \xe0 \xe9crire un test, le faire \xe9chouer, impl\xe9menter le code, puis refactoriser. B. Incorrect. Dans le TDD, les tests font partie du processus de d\xe9veloppement ; ils ne sont pas g\xe9n\xe9r\xe9s manuellement apr\xe8s. C. Incorrect. Le TDD implique que les tests sont \xe9crits avant d\'impl\xe9menter la fonctionnalit\xe9. D. Incorrect. Le TDD se concentre principalement sur les tests unitaires.","source":"Generadas (TDD)"},{"id":1061,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX l\'approche de d\xe9veloppement pilot\xe9 par les tests unitaires (TDD) ?  ","options":["Dans le TDD, les tests sont \xe9crits apr\xe8s le code pour valider son fonctionnement.","Dans le TDD, les tests sont cr\xe9\xe9s d\'abord puis le code n\xe9cessaire est d\xe9velopp\xe9 pour les faire passer.","Dans le TDD, les d\xe9veloppeurs se concentrent sur la documentation au lieu des tests automatis\xe9s.","Dans le TDD, l\'accent est mis exclusivement sur les tests d\'int\xe9gration et pas sur les tests unitaires."],"correctAnswer":1,"explanation":"A. Incorrect. Dans le TDD, les tests sont \xe9crits avant le code, pas apr\xe8s. B. Correct. Dans le TDD, les tests sont \xe9crits d\'abord puis le code est d\xe9velopp\xe9 pour satisfaire ces tests. C. Incorrect. Le TDD se concentre sur les tests automatis\xe9s. D. Incorrect. Le TDD se concentre sur les tests unitaires, pas exclusivement sur les tests d\'int\xe9gration.","source":"Generadas (TDD)"},{"id":1062,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Une \xe9quipe a corrig\xe9 plusieurs d\xe9fauts et publi\xe9 une nouvelle version. Avant la correction, certains cas de test avaient \xe9chou\xe9. L\'\xe9quipe doit v\xe9rifier que les d\xe9fauts ont \xe9t\xe9 corrig\xe9s et que les changements n\'ont pas affect\xe9 d\'autres parties du syst\xe8me. Laquelle des descriptions suivantes correspond le mieux aux tests qui seront r\xe9alis\xe9s ?  ","options":["Les tests de confirmation se concentrent uniquement sur les cas de test qui avaient \xe9chou\xe9 auparavant.","Les tests de r\xe9gression garantissent que les fonctionnalit\xe9s qui n\'ont pas \xe9t\xe9 modifi\xe9es continuent de fonctionner correctement.","Les tests de confirmation incluent les cas de test qui avaient \xe9chou\xe9 dans les versions pr\xe9c\xe9dentes et ceux qui sont ex\xe9cut\xe9s pour la premi\xe8re fois.","Les tests de r\xe9gression ne s\'appliquent qu\'aux nouveaux d\xe9fauts d\xe9couverts dans la nouvelle version."],"correctAnswer":1,"explanation":"A. Incorrect. Les tests de confirmation v\xe9rifient que les d\xe9fauts corrig\xe9s fonctionnent, mais ne se limitent pas aux cas qui avaient \xe9chou\xe9. B. Correct. Les tests de r\xe9gression v\xe9rifient que les modifications n\'ont pas affect\xe9 les fonctionnalit\xe9s existantes. C. Incorrect. Les tests de confirmation ne concernent que les d\xe9fauts corrig\xe9s. D. Incorrect. Les tests de r\xe9gression s\'appliquent \xe0 toutes les fonctionnalit\xe9s existantes.","source":"Generadas (Confirmation/Regression)"},{"id":1063,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Vous avez trouv\xe9 des d\xe9fauts dans une nouvelle fonctionnalit\xe9 du logiciel et, apr\xe8s les avoir corrig\xe9s, vous ex\xe9cutez \xe0 nouveau des tests. Quel type de tests r\xe9alisez-vous si vous validez que les d\xe9fauts ont \xe9t\xe9 corrig\xe9s ?  ","options":["Tests de r\xe9gression","Tests de confirmation","Tests fonctionnels","Tests en bo\xeete noire"],"correctAnswer":1,"explanation":"A. Incorrect. Les tests de r\xe9gression se concentrent sur la v\xe9rification que les fonctionnalit\xe9s qui fonctionnaient d\xe9j\xe0 continuent de fonctionner. B. Correct. Les tests de confirmation sont r\xe9alis\xe9s pour s\'assurer que les d\xe9fauts identifi\xe9s ont effectivement \xe9t\xe9 corrig\xe9s. C. Incorrect. Les tests fonctionnels \xe9valuent le comportement du logiciel par rapport aux exigences. D. Incorrect. Les tests en bo\xeete noire ne sont pas sp\xe9cifiquement li\xe9s \xe0 la correction des d\xe9fauts.","source":"Generadas (Confirmation/Regression)"},{"id":1064,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX l\'objectif des tests syst\xe8me par rapport aux tests d\'int\xe9gration ? (1) Les tests syst\xe8me se concentrent sur le comportement du syst\xe8me complet dans son ensemble. (2) Les tests d\'int\xe9gration v\xe9rifient l\'interaction entre les modules individuels. (3) Les tests syst\xe8me sont plus sp\xe9cifiques et se concentrent sur des composants isol\xe9s. (4) Les tests d\'int\xe9gration sont r\xe9alis\xe9s apr\xe8s les tests d\'acceptation.  ","options":["1 et 2 sont correctes","1 et 3 sont correctes","2 et 4 sont correctes","1, 2 et 3 sont correctes"],"correctAnswer":0,"explanation":"A. Correct. Les tests syst\xe8me \xe9valuent le comportement du syst\xe8me complet (1) et les tests d\'int\xe9gration se concentrent sur la fa\xe7on dont les modules interagissent entre eux (2). B. Incorrect. L\'affirmation 3 est fausse ; les tests syst\xe8me ne sont pas plus sp\xe9cifiques. C. Incorrect. L\'affirmation 4 est fausse ; les tests d\'int\xe9gration sont r\xe9alis\xe9s AVANT les tests d\'acceptation. D. Incorrect. L\'affirmation 3 est incorrecte.","source":"Generadas (Test Levels)"},{"id":1065,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Lequel des niveaux de test suivants se concentre principalement sur la v\xe9rification de l\'interaction entre diff\xe9rents modules du syst\xe8me ?  ","options":["Tests d\'acceptation","Tests syst\xe8me","Tests d\'int\xe9gration","Tests de composants"],"correctAnswer":2,"explanation":"A. Les tests d\'acceptation valident que le syst\xe8me r\xe9pond aux exigences de l\'utilisateur d\'un point de vue m\xe9tier. B. Les tests syst\xe8me v\xe9rifient la conformit\xe9 globale aux exigences. C. Correct. Les tests d\'int\xe9gration se concentrent sur la v\xe9rification de l\'interaction entre diff\xe9rents modules, garantissant qu\'ils fonctionnent correctement ensemble. D. Les tests de composants v\xe9rifient le fonctionnement d\'un module individuel.","source":"Generadas (Test Levels)"},{"id":1066,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le mieux un avantage de l\'approche \xab d\xe9calage vers la gauche \xbb (shift-left) ?  ","options":["Elle r\xe9duit le co\xfbt total du cycle de vie en identifiant les d\xe9fauts plus tard dans le processus.","Elle am\xe9liore la collaboration entre les \xe9quipes de d\xe9veloppement et de test d\xe8s le d\xe9but du projet.","Elle augmente la quantit\xe9 de tests r\xe9alis\xe9s dans l\'environnement de production.","Elle \xe9limine le besoin de tests manuels \xe0 la fin du cycle de d\xe9veloppement."],"correctAnswer":1,"explanation":"A. Incorrect. Le shift-left cherche \xe0 identifier les d\xe9fauts t\xf4t, ce qui r\xe9duit les co\xfbts. B. Correct. Il favorise la collaboration pr\xe9coce entre les \xe9quipes pour d\xe9tecter et r\xe9soudre les probl\xe8mes plus t\xf4t. C. Incorrect. Augmenter les tests en production n\'est pas un objectif du shift-left. D. Incorrect. Bien que l\'on cherche \xe0 automatiser, l\'approche n\'\xe9limine pas les tests manuels.","source":"Generadas (Shift Left)"},{"id":1067,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le mieux comment l\'approche \xab d\xe9calage vers la gauche \xbb peut am\xe9liorer la qualit\xe9 du logiciel ?  ","options":["Elle permet de d\xe9tecter et corriger les d\xe9fauts dans les \xe9tapes ult\xe9rieures du cycle de vie du d\xe9veloppement.","Elle facilite l\'int\xe9gration continue et la livraison pr\xe9coce de valeur au client.","Elle augmente la complexit\xe9 du processus de d\xe9veloppement en introduisant plus de tests dans les phases initiales.","Elle r\xe9duit le besoin de documentation en appliquant plus de tests utilisateur \xe0 la fin du cycle."],"correctAnswer":1,"explanation":"A. Incorrect. Le shift-left se concentre sur la d\xe9tection des d\xe9fauts le plus t\xf4t possible, pas dans les \xe9tapes ult\xe9rieures. B. Correct. Cette approche permet d\'int\xe9grer et de livrer un logiciel de valeur au client plus rapidement, am\xe9liorant la qualit\xe9 d\xe8s le d\xe9but. C. Incorrect. L\'objectif est de simplifier le processus en am\xe9liorant la qualit\xe9 initiale. D. Incorrect. Le shift-left n\'\xe9limine pas le besoin de documentation.","source":"Generadas (Shift Left)"},{"id":1080,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des activit\xe9s suivantes est un exemple de l\'approche \xab d\xe9calage vers la gauche \xbb (shift-left) dans le processus de d\xe9veloppement logiciel ?  ","options":["A) R\xe9aliser des revues de code apr\xe8s l\'ach\xe8vement du d\xe9veloppement du logiciel.","B) Impliquer l\'\xe9quipe de test dans les \xe9tapes initiales du projet pour d\xe9finir les crit\xe8res d\'acceptation.","C) R\xe9aliser des tests d\'int\xe9gration une fois l\'impl\xe9mentation du syst\xe8me termin\xe9e.","D) R\xe9diger la documentation utilisateur seulement apr\xe8s l\'ach\xe8vement du d\xe9veloppement."],"correctAnswer":1,"explanation":"B. Correct. Impliquer l\'\xe9quipe de test d\xe8s le d\xe9but aide \xe0 identifier les probl\xe8mes t\xf4t.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1081,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit correctement l\'approche de d\xe9veloppement pilot\xe9 par les tests (TDD) ?  ","options":["A) Dans le TDD, on \xe9crit d\'abord un cas de test qui d\xe9finit une fonction souhait\xe9e avant de d\xe9velopper le code.","B) Dans le TDD, les tests sont cr\xe9\xe9s apr\xe8s l\'ach\xe8vement du d\xe9veloppement du logiciel.","C) Dans le TDD, on se concentre sur les tests de performance et pas sur les tests unitaires.","D) Dans le TDD, les cas de test sont sans importance pour le processus de d\xe9veloppement."],"correctAnswer":0,"explanation":"A. Correct. Dans le TDD, on \xe9crit d\'abord un cas de test qui guide le d\xe9veloppement du code, favorisant une approche it\xe9rative.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1082,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX la m\xe9thodologie de d\xe9veloppement pilot\xe9 par les tests (TDD) ?  ","options":["A) Dans le TDD, les tests sont \xe9crits apr\xe8s l\'ach\xe8vement du d\xe9veloppement du logiciel.","B) Dans le TDD, on cr\xe9e d\'abord un test qui \xe9choue avant d\'\xe9crire le code pour faire passer le test.","C) Dans le TDD, seuls des tests d\'acceptation sont d\xe9velopp\xe9s \xe0 la fin du cycle de d\xe9veloppement.","D) Dans le TDD, le code et les tests sont d\xe9velopp\xe9s de mani\xe8re compl\xe8tement ind\xe9pendante."],"correctAnswer":1,"explanation":"B. Correct. Dans le TDD, on r\xe9dige un test qui \xe9choue initialement, ce qui guide le d\xe9veloppement ult\xe9rieur du code.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1083,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Lesquelles des affirmations suivantes d\xe9crivent correctement les niveaux de test (1-4) et leurs approches sp\xe9cifiques (A-D) ?\\n\\n1. Tests r\xe9alis\xe9s pour valider la fonctionnalit\xe9 compl\xe8te du syst\xe8me dans un environnement de production simul\xe9\\n2. Tests ax\xe9s sur la v\xe9rification du bon fonctionnement des modules individuels\\n3. Tests qui garantissent que les diff\xe9rents modules s\'int\xe8grent et fonctionnent ensemble\\n4. Tests impliquant la validation des exigences du point de vue de l\'utilisateur final\\n\\nA. Tests syst\xe8me  \\nB. Tests de composants  \\nC. Tests d\'int\xe9gration  \\nD. Tests d\'acceptation","options":["A) 1A, 2B, 3C, 4D","B) 1C, 2A, 3D, 4B","C) 1D, 2C, 3A, 4B","D) 1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"A. Correct. L\'affirmation 1 d\xe9crit correctement les tests syst\xe8me (1A), qui valident le syst\xe8me dans son ensemble. L\'affirmation 2 se r\xe9f\xe8re aux tests de composants (2B). La 3 se rapporte aux tests d\'int\xe9gration (3C). La 4 correspond aux tests d\'acceptation (4D).","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1084,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le mieux un avantage de la tenue de r\xe9trospectives apr\xe8s chaque it\xe9ration dans une \xe9quipe de travail ?  ","options":["A) Les r\xe9trospectives garantissent que tous les membres de l\'\xe9quipe sont d\'accord sur les d\xe9cisions prises pendant l\'it\xe9ration.","B) Les r\xe9trospectives permettent d\'identifier et de traiter les probl\xe8mes du processus de travail, facilitant ainsi l\'am\xe9lioration continue.","C) Les r\xe9trospectives sont une occasion pour l\'\xe9quipe de c\xe9l\xe9brer ses succ\xe8s sans se concentrer sur les axes d\'am\xe9lioration.","D) Les r\xe9trospectives ne sont qu\'une formalit\xe9 r\xe9alis\xe9e pour respecter les exigences du cadre agile."],"correctAnswer":1,"explanation":"B. Correct. Les r\xe9trospectives sont cruciales pour identifier les probl\xe8mes et faciliter l\'am\xe9lioration continue dans le processus de travail de l\'\xe9quipe.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1085,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le mieux l\'objectif d\'une r\xe9trospective dans une \xe9quipe agile ?  ","options":["A) Les r\xe9trospectives sont des r\xe9unions o\xf9 l\'\xe9quipe partage les t\xe2ches termin\xe9es et planifie le prochain sprint.","B) Les r\xe9trospectives permettent \xe0 l\'\xe9quipe de r\xe9fl\xe9chir \xe0 ce qui a bien fonctionn\xe9 et \xe0 ce qui n\'a pas fonctionn\xe9, et de g\xe9n\xe9rer des actions pour s\'am\xe9liorer \xe0 l\'avenir.","C) Les r\xe9trospectives sont des sessions o\xf9 l\'on discute des lacunes des membres de l\'\xe9quipe pour qu\'elles ne se r\xe9p\xe8tent pas.","D) Les r\xe9trospectives ne sont utiles qu\'\xe0 la fin du projet pour \xe9valuer la performance globale de l\'\xe9quipe."],"correctAnswer":1,"explanation":"B. Correct. L\'objectif principal d\'une r\xe9trospective est de r\xe9fl\xe9chir au travail r\xe9alis\xe9 et de trouver des moyens d\'am\xe9liorer le processus pour les futurs sprints.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1086,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Imaginez que vous avez test\xe9 une nouvelle fonctionnalit\xe9 du logiciel et trouv\xe9 quelques d\xe9fauts. Apr\xe8s avoir corrig\xe9 ces d\xe9fauts, vous ex\xe9cutez \xe0 nouveau une s\xe9rie de tests. Quel type de tests r\xe9alisez-vous si vous validez que les d\xe9fauts ont \xe9t\xe9 corrig\xe9s ?  ","options":["A) Tests de r\xe9gression","B) Tests de confirmation","C) Tests fonctionnels","D) Tests en bo\xeete noire"],"correctAnswer":1,"explanation":"B. Correct. Les tests de confirmation sont r\xe9alis\xe9s pour s\'assurer que les d\xe9fauts identifi\xe9s ont effectivement \xe9t\xe9 corrig\xe9s.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":1087,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Une \xe9quipe de test a ex\xe9cut\xe9 un ensemble de tests sur une nouvelle fonctionnalit\xe9 d\'une application. Lors de la premi\xe8re ex\xe9cution, des d\xe9fauts ont \xe9t\xe9 trouv\xe9s et des corrections ont \xe9t\xe9 apport\xe9es. Lors de la deuxi\xe8me ex\xe9cution des tests, certains tests ont \xe9t\xe9 r\xe9p\xe9t\xe9s. Laquelle des affirmations suivantes d\xe9crit correctement les tests r\xe9alis\xe9s ?  ","options":["A) Les tests r\xe9p\xe9t\xe9s sont des tests de confirmation, tandis que les tests de la nouvelle fonctionnalit\xe9 sont des tests de r\xe9gression.","B) Les tests de la nouvelle fonctionnalit\xe9 sont consid\xe9r\xe9s comme des tests de confirmation et les tests r\xe9p\xe9t\xe9s sont des tests de r\xe9gression.","C) Les tests r\xe9p\xe9t\xe9s sont des tests de confirmation et les tests de la nouvelle fonctionnalit\xe9 sont des tests de r\xe9gression.","D) Tous les tests ex\xe9cut\xe9s sont des tests de r\xe9gression."],"correctAnswer":2,"explanation":"C. Correct. Les tests r\xe9p\xe9t\xe9s valident des corrections, class\xe9s comme tests de confirmation, tandis que ceux de la nouvelle fonctionnalit\xe9 sont consid\xe9r\xe9s comme des tests de r\xe9gression.","source":"A\xf1adidas Usuario (Tema 2)"},{"id":258,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Consid\xe9rez la r\xe8gle suivante : \xab\xa0\xe0 chaque activit\xe9 SDLC, il existe une activit\xe9 de test correspondante\xa0\xbb. Dans quels mod\xe8les SDLC cette r\xe8gle s\u2019applique-t-elle\xa0?  ","options":["A) Uniquement dans les mod\xe8les de d\xe9veloppement s\xe9quentiel","B) Uniquement dans les mod\xe8les de d\xe9veloppement it\xe9ratifs","C) Uniquement dans les mod\xe8les de d\xe9veloppement it\xe9ratifs et incr\xe9mentaux","D) Dans les mod\xe8les de d\xe9veloppement s\xe9quentiel, incr\xe9mental et it\xe9ratif"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#9, LO : FL-2.1.2). Justification\xa0: Dans les mod\xe8les de d\xe9veloppement s\xe9quentiel, incr\xe9mentiel et it\xe9ratif","source":"Official Sample Exam A Q#9"},{"id":259,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX l\u2019approche de d\xe9veloppement pilot\xe9 par les tests d\u2019acceptation (ATDD)\xa0?  ","options":["A) Dans ATDD, les crit\xe8res d\'acceptation sont g\xe9n\xe9ralement cr\xe9\xe9s en fonction du format donn\xe9/quand/alors.","B) Dans ATDD, les cas de tests sont principalement cr\xe9\xe9s dans les tests de composants et sont orient\xe9s code","C) Dans ATDD, les tests sont cr\xe9\xe9s sur la base de crit\xe8res d\'acceptation pour guider le d\xe9veloppement des logiciels associ\xe9s","D) Dans ATDD, les tests sont bas\xe9s sur le comportement souhait\xe9 du logiciel, ce qui facilite la compr\xe9hension des membres de l\'\xe9quipe"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#10, LO : FL-2.1.3). Justification\xa0: Dans ATDD, les tests sont cr\xe9\xe9s sur la base de crit\xe8res d\'acceptation pour guider le d\xe9veloppement de logiciels associ\xe9s.","source":"Official Sample Exam A Q#10"},{"id":260,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Lequel des \xe9nonc\xe9s suivants n\u2019est PAS un exemple de l\u2019approche Shift-Gauche\xa0?  ","options":["A) Examiner les exigences des utilisateurs avant qu\'elles ne soient formellement accept\xe9es par les parties prenantes","B) \xc9crire un test de composant avant d\'\xe9crire le code correspondant","C) Ex\xe9cuter un test d\'efficacit\xe9 des performances pour un composant pendant les tests de composants","D) \xc9crivez un script de test avant de configurer le processus de gestion de la configuration"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#11, LO : FL-2.1.5). Justification\xa0: \xc9crivez un script de test avant de configurer le processus de gestion de la configuration.","source":"Official Sample Exam A Q#11"},{"id":261,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Lequel des arguments suivants utiliseriez-vous pour convaincre votre manager d\u2019organiser des r\xe9trospectives\xa0?  ","options":["A) Les r\xe9trospectives sont tr\xe8s populaires de nos jours et les clients appr\xe9cieraient que nous les ajoutions \xe0 nos processus","B) L\'organisation de r\xe9trospectives permettra \xe0 l\'organisation d\'\xe9conomiser de l\'argent, car sans elles, les repr\xe9sentants des utilisateurs finaux ne fournissent pas de commentaires imm\xe9diats sur le produit.","C) Les faiblesses des processus identifi\xe9es lors de la r\xe9trospective peuvent \xeatre analys\xe9es et servir de liste de t\xe2ches pour le programme d\'am\xe9lioration continue des processus de l\'organisation.","D) Les r\xe9trospectives englobent cinq valeurs, dont le courage et le respect, qui sont essentielles au maintien de l\'am\xe9lioration continue de l\'organisation."],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#12, LO : FL-2.1.6). Justification\xa0: Les faiblesses des processus identifi\xe9es au cours de la r\xe9trospective peuvent \xeatre analys\xe9es et servir de liste de t\xe2ches pour le programme d\'am\xe9lioration continue des processus de l\'organisation.","source":"Official Sample Exam A Q#12"},{"id":262,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Quels types de d\xe9fauts (1-4) correspondent le MIEUX \xe0 quels niveaux de test (A-D) ?\\n\\n1. D\xe9faillances dans le comportement du syst\xe8me en s\'\xe9cartant des besoins professionnels de l\'utilisateur\\n2. D\xe9faillances dans la communication entre les composants\\n3. D\xe9faillances dans la logique du code\\n4. D\xe9faillances dues \xe0 des r\xe8gles m\xe9tier mal mises en \u0153uvre\\n\\nA. Tests de composants  \\nB. Tests d\'int\xe9gration de composants  \\nC. Tests du syst\xe8me  \\nD. Tests d\'acceptation","options":["A)1D, 2B, 3A, 4C","B)1D, 2B, 3C, 4A","C)1B, 2A, 3D, 4C","D) 1C, 2B, 3A, 4D"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#13, LO : FL-2.2.1). Justification\xa0: 1D, 2B, 3A, 4C","source":"Official Sample Exam A Q#13"},{"id":297,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes sur le cycle de vie de d\xe9veloppement logiciel choisi est CORRECTE ?  ","options":["A) Si le d\xe9veloppement logiciel agile est utilis\xe9, l\'automatisation des tests syst\xe8me remplace le besoin de tests de r\xe9gression","B) Si un mod\xe8le de d\xe9veloppement s\xe9quentiel est utilis\xe9, les tests dynamiques sont g\xe9n\xe9ralement limit\xe9s aux \xe9tapes ult\xe9rieures du cycle de vie","C) Si un mod\xe8le de d\xe9veloppement it\xe9ratif est utilis\xe9, les tests de composants sont g\xe9n\xe9ralement r\xe9alis\xe9s manuellement par les d\xe9veloppeurs","D) Si un mod\xe8le de d\xe9veloppement incr\xe9mental est utilis\xe9, les tests statiques sont r\xe9alis\xe9s dans les premiers incr\xe9ments et les tests dynamiques dans les derniers"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#9, LO : FL-2.1.1). Justification : Dans un mod\xe8le de d\xe9veloppement s\xe9quentiel, les tests dynamiques sont g\xe9n\xe9ralement limit\xe9s aux phases finales du cycle de vie.","source":"Official Sample Exam B Q#9"},{"id":298,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des pratiques suivantes est une bonne pratique de test applicable \xe0 tous les cycles de vie de d\xe9veloppement logiciel ?  ","options":["A) Les testeurs doivent revoir les produits de travail dans le cadre de la phase de d\xe9veloppement suivante","B) Les testeurs doivent revoir les produits de travail d\xe8s que des brouillons sont disponibles","C) Les testeurs doivent revoir les produits de travail avant que l\'analyse et la conception des tests ne commencent","D) Les testeurs doivent revoir les produits de travail imm\xe9diatement apr\xe8s leur publication"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#10, LO : FL-2.1.2). Justification : Les testeurs doivent revoir les produits de travail d\xe8s que des brouillons sont disponibles.","source":"Official Sample Exam B Q#10"},{"id":299,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Lequel des \xe9l\xe9ments suivants est un exemple d\'approche de d\xe9veloppement test-d\'abord (test-first) ?  ","options":["A) D\xe9veloppement pilot\xe9 par les tests (TDD)","B) D\xe9veloppement pilot\xe9 par la couverture","C) D\xe9veloppement pilot\xe9 par la qualit\xe9","D) D\xe9veloppement pilot\xe9 par les fonctionnalit\xe9s"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#11, LO : FL-2.1.3). Justification : Le d\xe9veloppement pilot\xe9 par les tests (TDD) est l\'exemple classique d\'approche test-d\'abord.","source":"Official Sample Exam B Q#11"},{"id":300,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des activit\xe9s suivantes est le PLUS PROBABLEMENT r\xe9alis\xe9e dans le cadre des tests syst\xe8me ?  ","options":["A) Tests de s\xe9curit\xe9 d\'un syst\xe8me de gestion de cr\xe9dits r\xe9alis\xe9s par une \xe9quipe de test ind\xe9pendante","B) Tests de l\'interface d\'un syst\xe8me de change de devises avec un syst\xe8me bancaire externe","C) Tests b\xeata d\'un syst\xe8me d\'apprentissage \xe0 distance r\xe9alis\xe9s par les d\xe9veloppeurs du logiciel","D) Tests des interactions entre l\'interface utilisateur et la base de donn\xe9es d\'un syst\xe8me de ressources humaines"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#13, LO : FL-2.2.1). Justification : Les tests de s\xe9curit\xe9 r\xe9alis\xe9s par une \xe9quipe ind\xe9pendante sont caract\xe9ristiques des tests syst\xe8me.","source":"Official Sample Exam B Q#13"},{"id":301,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes est CORRECTE ?  ","options":["A) Les tests de r\xe9gression augmentent en nombre \xe0 mesure que le projet avance, tandis que les tests de confirmation diminuent","B) Les tests de r\xe9gression sont cr\xe9\xe9s et ex\xe9cut\xe9s lorsque l\'objet de test est corrig\xe9, tandis que les tests de confirmation sont ex\xe9cut\xe9s lorsque l\'objet de test est am\xe9lior\xe9","C) Les tests de r\xe9gression v\xe9rifient que l\'environnement d\'exploitation reste inchang\xe9, tandis que les tests de confirmation testent les changements dans l\'objet de test","D) Les tests de r\xe9gression v\xe9rifient les effets ind\xe9sirables sur le code non modifi\xe9, tandis que les tests de confirmation testent le code modifi\xe9"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#14, LO : FL-2.2.3). Justification : Les tests de r\xe9gression traitent des effets ind\xe9sirables sur le code non modifi\xe9, tandis que les tests de confirmation traitent du code modifi\xe9.","source":"Official Sample Exam B Q#14"},{"id":335,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des options suivantes fournit la MEILLEURE description du concept \xab shift-left \xbb (d\xe9calage vers la gauche) ?  ","options":["A) Lorsque les d\xe9veloppeurs sont d\'accord, les activit\xe9s manuelles du c\xf4t\xe9 gauche du processus de test sont automatis\xe9es pour soutenir le principe \xab les tests pr\xe9coces font gagner du temps et de l\'argent \xbb","B) Lorsque c\'est rentable, les activit\xe9s de test sont avanc\xe9es dans le SDLC pour r\xe9duire le co\xfbt total de la qualit\xe9 en diminuant le nombre de d\xe9fauts trouv\xe9s dans les phases tardives","C) Lorsqu\'ils ont du temps libre, les testeurs doivent automatiser les tests de r\xe9gression en commen\xe7ant par les tests de composants et d\'int\xe9gration de composants","D) Lorsqu\'ils sont disponibles, les testeurs sont form\xe9s pour r\xe9aliser des t\xe2ches au d\xe9but du SDLC afin de permettre d\'automatiser davantage d\'activit\xe9s de test dans les phases ult\xe9rieures"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#11, LO : FL-2.1.5). Justification : Le shift-left consiste \xe0 avancer les activit\xe9s de test au d\xe9but du cycle de vie pour d\xe9tecter les d\xe9fauts plus t\xf4t, lorsqu\'ils sont moins co\xfbteux \xe0 corriger.","source":"Official Sample Exam C Q#11"},{"id":336,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des options suivantes est la MOINS SUSCEPTIBLE de se produire \xe0 la suite d\'une r\xe9trospective ?  ","options":["A) La qualit\xe9 des futurs objets de test s\'am\xe9liore en identifiant des am\xe9liorations dans les pratiques de d\xe9veloppement","B) L\'efficacit\xe9 des tests s\'am\xe9liore en rationalisant la configuration des environnements de test gr\xe2ce \xe0 l\'automatisation","C) La compr\xe9hension des utilisateurs finaux des processus de d\xe9veloppement et de test s\'am\xe9liore","D) Les scripts de test automatis\xe9s sont am\xe9lior\xe9s gr\xe2ce au feedback des d\xe9veloppeurs"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#12, LO : FL-2.1.6). Justification : Les r\xe9trospectives sont des r\xe9unions internes de l\'\xe9quipe ; elles n\'ont pas pour objectif d\'am\xe9liorer la compr\xe9hension des utilisateurs finaux des processus.","source":"Official Sample Exam C Q#12"},{"id":337,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Quel niveau de test est le PLUS PROBABLEMENT r\xe9alis\xe9 si les tests sont ax\xe9s sur la validation et ne sont pas r\xe9alis\xe9s par des testeurs ?  ","options":["A) Tests de composants","B) Tests d\'int\xe9gration de composants","C) Tests d\'int\xe9gration de syst\xe8mes","D) Tests d\'acceptation"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#13, LO : FL-2.2.1). Justification : Les tests d\'acceptation sont orient\xe9s vers la validation (est-ce le bon syst\xe8me ?) et sont g\xe9n\xe9ralement r\xe9alis\xe9s par les utilisateurs ou les clients, pas par les testeurs.","source":"Official Sample Exam C Q#13"},{"id":338,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Le logiciel d\'un syst\xe8me de navigation a \xe9t\xe9 mis \xe0 jour parce qu\'il sugg\xe9rait des itin\xe9raires enfreignant le code de la route, comme rouler \xe0 contresens dans des rues \xe0 sens unique. Laquelle des options suivantes d\xe9crit le MIEUX les tests \xe0 r\xe9aliser ?  ","options":["A) Uniquement des tests de confirmation","B) Tests de confirmation puis tests de r\xe9gression","C) Uniquement des tests de r\xe9gression","D) Tests de r\xe9gression puis tests de confirmation"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#14, LO : FL-2.2.3). Justification : On effectue d\'abord un test de confirmation pour v\xe9rifier que le d\xe9faut est corrig\xe9, puis des tests de r\xe9gression pour v\xe9rifier que la correction n\'a pas introduit de nouveaux d\xe9fauts.","source":"Official Sample Exam C Q#14"},{"id":369,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Lequel des \xe9l\xe9ments suivants est le PLUS PROBABLEMENT un d\xe9fi lors de la mise en \u0153uvre de DevOps ?  ","options":["A) S\'assurer que les caract\xe9ristiques de qualit\xe9 non fonctionnelles ne sont pas n\xe9glig\xe9es","B) G\xe9rer des environnements de test qui changent continuellement","C) Le besoin de davantage de testeurs manuels ayant une exp\xe9rience appropri\xe9e","D) Configurer l\'automatisation des tests dans le cadre du pipeline de livraison"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#11, LO : FL-2.1.4). Justification : Configurer et int\xe9grer l\'automatisation des tests au sein du pipeline de livraison continue est l\'un des plus grands d\xe9fis lors de l\'adoption de DevOps.","source":"Official Sample Exam D Q#11"},{"id":370,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des options suivantes d\xe9crit le MIEUX les r\xe9trospectives ?  ","options":["A) Les r\xe9trospectives permettent aux membres de l\'\xe9quipe d\'identifier les autres membres qui n\'ont pas suffisamment contribu\xe9 \xe0 la qualit\xe9 selon l\'approche d\'\xe9quipe enti\xe8re","B) Les r\xe9trospectives donnent aux testeurs l\'occasion d\'identifier les activit\xe9s qui ont r\xe9ussi afin de les conserver lors d\'am\xe9liorations futures","C) Les r\xe9trospectives sont l\'endroit o\xf9 les membres de l\'\xe9quipe agile peuvent exprimer leurs pr\xe9occupations sur la gestion et les clients dans un environnement sans reproches","D) Les r\xe9trospectives donnent aux membres de l\'\xe9quipe agile un forum pour discuter du plan et des d\xe9cisions techniques de la prochaine it\xe9ration"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#12, LO : FL-2.1.6). Justification : Les r\xe9trospectives servent \xe0 identifier ce qui a bien fonctionn\xe9 (pour le conserver) et ce qui peut \xeatre am\xe9lior\xe9 au prochain cycle.","source":"Official Sample Exam D Q#12"},{"id":371,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Lequel des tests suivants est le PLUS PROBABLEMENT celui r\xe9alis\xe9 dans le cadre des tests fonctionnels ?  ","options":["A) Le test v\xe9rifie que la fonction de tri place les \xe9l\xe9ments de la liste par ordre croissant","B) Le test v\xe9rifie que la fonction de tri termine le processus en moins d\'une seconde","C) Le test v\xe9rifie avec quelle facilit\xe9 la fonction de tri peut \xeatre chang\xe9e de croissant \xe0 d\xe9croissant","D) Le test v\xe9rifie que la fonction de tri continue de fonctionner correctement lors de la migration d\'une architecture 32 bits \xe0 64 bits"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#13, LO : FL-2.2.2). Justification : V\xe9rifier que la fonction de tri fait ce qu\'elle doit faire (trier correctement) est un test fonctionnel ; les autres options sont non fonctionnelles.","source":"Official Sample Exam D Q#13"},{"id":372,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Lequel des \xe9l\xe9ments suivants est le PLUS PROBABLEMENT le d\xe9clencheur menant \xe0 r\xe9aliser des tests de maintenance d\'un syst\xe8me de change de devises ?  ","options":["A) Les d\xe9veloppeurs ont signal\xe9 que modifier le syst\xe8me \xe9tait difficile et les testeurs ont d\xe9cid\xe9 de v\xe9rifier si c\'\xe9tait vrai","B) L\'option de remboursement du syst\xe8me a \xe9t\xe9 supprim\xe9e car elle ne renvoyait pas toujours le montant correct aux clients","C) L\'\xe9quipe agile a commenc\xe9 \xe0 d\xe9velopper une user story qui ajoute une fonctionnalit\xe9 de fid\xe9lisation des clients","D) L\'option de prise en charge des langues du syst\xe8me a \xe9t\xe9 utilis\xe9e pour permettre des transactions en anglais et dans la langue locale"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#14, LO : FL-2.3.1). Justification : Supprimer une fonctionnalit\xe9 d\xe9fectueuse du syst\xe8me en production est un d\xe9clencheur classique des tests de maintenance.","source":"Official Sample Exam D Q#14"},{"id":409,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Dans un projet avec mod\xe8le en V, l\'\xe9quipe re\xe7oit les exigences du syst\xe8me le jour 1. \xc0 quel moment la conception des tests syst\xe8me devrait-elle commencer ?  ","options":["A) Lorsque le code du syst\xe8me est enti\xe8rement d\xe9velopp\xe9","B) Apr\xe8s l\'ach\xe8vement des tests d\'int\xe9gration","C) En parall\xe8le de la conception du syst\xe8me, d\xe8s que les exigences sont disponibles","D) Seulement apr\xe8s que les exigences sont formellement approuv\xe9es par le client"],"correctAnswer":2,"explanation":"L\'approche \xab shift-left \xbb et le mod\xe8le en V \xe9tablissent que la conception des tests syst\xe8me doit se faire en parall\xe8le de la conception du syst\xe8me, et non apr\xe8s le d\xe9veloppement, en profitant des exigences pr\xe9coces.","source":"banco"},{"id":410,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Votre \xe9quipe travaille en Scrum avec des sprints de 2 semaines. Au d\xe9but du sprint, l\'\xe9quipe a 8 user stories. Quand les testeurs devraient-ils commencer \xe0 travailler sur ces stories ?  ","options":["A) Le dernier jour du sprint, pendant la d\xe9mo","B) D\xe8s le premier jour, en collaborant \xe0 la d\xe9finition des crit\xe8res d\'acceptation et des cas de test","C) \xc0 mi-sprint, lorsque le d\xe9veloppement est \xe0 50 %","D) Au sprint suivant, en r\xe9alisant des tests de r\xe9gression"],"correctAnswer":1,"explanation":"En Agile/Scrum, les testeurs participent d\xe8s le d\xe9but du sprint au raffinement, \xe0 la d\xe9finition des crit\xe8res d\'acceptation et \xe0 la conception des tests, int\xe9grant les tests en continu (approche d\'\xe9quipe enti\xe8re).","source":"banco"},{"id":420,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Quelle est la diff\xe9rence entre les tests de confirmation (re-test) et les tests de r\xe9gression ?  ","options":["A) Ce sont les m\xeames, juste des noms diff\xe9rents","B) La confirmation v\xe9rifie qu\'un d\xe9faut sp\xe9cifique a \xe9t\xe9 corrig\xe9 ; la r\xe9gression v\xe9rifie que les changements n\'ont rien cass\xe9 d\'autre","C) La r\xe9gression n\'est faite que par les d\xe9veloppeurs ; la confirmation par les testeurs","D) La confirmation se fait avant le d\xe9veloppement ; la r\xe9gression apr\xe8s"],"correctAnswer":1,"explanation":"Le re-test (confirmation) ex\xe9cute le cas de test qui a \xe9chou\xe9 pour v\xe9rifier que le d\xe9faut concret a \xe9t\xe9 corrig\xe9. Les tests de r\xe9gression v\xe9rifient que le changement n\'a pas introduit de nouvelles d\xe9faillances dans d\'autres zones.","source":"banco"},{"id":431,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Dans le TDD (Test Driven Development), quel est l\'ordre correct du cycle ?  ","options":["A) \xc9crire le code -> \xc9crire le test -> Refactoriser","B) \xc9crire le test (qui \xe9choue) -> \xc9crire le code minimal pour passer le test -> Refactoriser","C) Concevoir -> \xc9crire le test -> \xc9crire le code -> Refactoriser","D) \xc9crire le test -> D\xe9ployer -> Refactoriser -> \xc9crire le code"],"correctAnswer":1,"explanation":"Le TDD suit le cycle Red-Green-Refactor : 1) \xc9crire un test qui \xe9choue (Red), 2) \xc9crire le code minimal pour qu\'il passe (Green), 3) Refactoriser le code en gardant les tests au vert.","source":"banco"},{"id":432,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes sur les tests d\'int\xe9gration de syst\xe8mes est CORRECTE ?  ","options":["A) Ils v\xe9rifient la logique interne de chaque composant individuel","B) Ils v\xe9rifient les interactions entre le syst\xe8me et des syst\xe8mes externes ou des interfaces","C) Ils ne sont ex\xe9cut\xe9s que par les utilisateurs finaux","D) Ils ne s\'appliquent que dans les mod\xe8les de d\xe9veloppement en cascade"],"correctAnswer":1,"explanation":"Les tests d\'int\xe9gration de syst\xe8mes v\xe9rifient les interfaces et les communications entre le syst\xe8me test\xe9 et d\'autres syst\xe8mes externes, services, API ou mat\xe9riels avec lesquels il interagit.","source":"banco"},{"id":433,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Une \xe9quipe DevOps met en \u0153uvre CI/CD. Les tests s\'ex\xe9cutent automatiquement \xe0 chaque commit. Quel type de tests est le PLUS appropri\xe9 \xe0 ex\xe9cuter \xe0 chaque build du pipeline de CI ?  ","options":["A) Tests d\'acceptation utilisateur complets","B) Tests exploratoires manuels","C) Tests de composants et d\'int\xe9gration automatis\xe9s et rapides","D) Tests de performance complets avec charge maximale"],"correctAnswer":2,"explanation":"En CI, les tests doivent \xeatre rapides et automatis\xe9s pour fournir un feedback imm\xe9diat. Les tests de composants et d\'int\xe9gration automatis\xe9s sont id\xe9aux. Les tests lents (UAT, charge compl\xe8te) vont dans des phases s\xe9par\xe9es.","source":"banco"},{"id":442,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Que sont les \xab crit\xe8res d\'entr\xe9e \xbb (entry criteria) dans le processus de test ?  ","options":["A) Les exigences que le logiciel doit satisfaire pour pouvoir \xeatre lanc\xe9 sur le march\xe9","B) Les conditions qui doivent \xeatre remplies avant qu\'une activit\xe9 de test puisse commencer","C) Les crit\xe8res pour accepter un nouveau testeur dans l\'\xe9quipe","D) Les m\xe9triques de couverture minimale pour terminer les tests"],"correctAnswer":1,"explanation":"Les crit\xe8res d\'entr\xe9e d\xe9finissent les pr\xe9conditions qui doivent \xeatre remplies pour d\xe9marrer une phase ou activit\xe9 de test, par exemple : logiciel compil\xe9 sans erreurs, environnement disponible, donn\xe9es de test pr\xe9par\xe9es.","source":"banco"},{"id":447,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Que sont les \xab stubs de test \xbb (test stubs) dans les tests d\'int\xe9gration ?  ","options":["A) Des outils d\'automatisation des tests","B) Des substituts de composants appel\xe9s par le composant test\xe9 qui ne sont pas encore disponibles","C) Des rapports de d\xe9fauts trouv\xe9s pendant l\'int\xe9gration","D) Des donn\xe9es de test g\xe9n\xe9r\xe9es automatiquement"],"correctAnswer":1,"explanation":"Les stubs sont des composants substituts qui simulent les modules appel\xe9s par le composant test\xe9 (composants \xab vers le bas \xbb dans la hi\xe9rarchie) qui ne sont pas encore disponibles pendant les tests d\'int\xe9gration.","source":"banco"},{"id":455,"chapter":2,"topic":"Tests tout au long du SDLC","question":"CAS PRATIQUE : Un syst\xe8me d\'e-commerce comporte 3 niveaux : Frontend (React), API Backend (Java), Base de donn\xe9es (PostgreSQL). Lors du test de la fonction \xab ajouter au panier \xbb, elle \xe9choue. Le backend renvoie une erreur 500. Quel type de test d\'int\xe9gration vous faut-il ?  ","options":["A) Test de composant du frontend","B) Test d\'int\xe9gration entre le frontend et l\'API backend pour v\xe9rifier le contrat de l\'interface","C) Test syst\xe8me de bout en bout complet","D) Test d\'acceptation utilisateur"],"correctAnswer":1,"explanation":"L\'erreur 500 du backend indique une d\xe9faillance dans l\'interface entre le frontend et le backend. Le test d\'int\xe9gration de composants v\xe9rifie les interfaces et les contrats entre les modules int\xe9gr\xe9s, ce qui est exactement ce que vous devez diagnostiquer.","source":"banco"},{"id":461,"chapter":2,"topic":"Tests tout au long du SDLC","question":"Quel est l\'objectif principal des tests d\'acceptation utilisateur (UAT) ?  ","options":["A) V\xe9rifier que le code n\'a pas d\'erreurs de syntaxe","B) Confirmer que le syst\xe8me r\xe9pond aux besoins m\xe9tier et est apte \xe0 \xeatre utilis\xe9 par les utilisateurs finaux","C) Tester la performance du syst\xe8me sous charge","D) V\xe9rifier que les composants s\'int\xe8grent correctement"],"correctAnswer":1,"explanation":"L\'UAT v\xe9rifie que le syst\xe8me r\xe9pond aux exigences m\xe9tier et aux besoins des utilisateurs. Les utilisateurs ou repr\xe9sentants m\xe9tier confirment si le syst\xe8me est adapt\xe9 \xe0 son objectif avant l\'acceptation formelle.","source":"banco"},{"id":"q_batch2_4a5g1mcwu","chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le mieux l\'importance des tests pendant le cycle de vie de d\xe9veloppement logiciel ?  ","options":["Les tests ne sont n\xe9cessaires qu\'\xe0 la fin du cycle de d\xe9veloppement pour v\xe9rifier le produit final.","Les tests doivent \xeatre int\xe9gr\xe9s \xe0 toutes les phases du cycle de d\xe9veloppement pour d\xe9tecter les d\xe9fauts t\xf4t.","Les tests sont principalement utiles dans les projets de grande taille et complexes.","Les tests peuvent \xeatre ignor\xe9s si des m\xe9thodologies agiles sont utilis\xe9es."],"correctAnswer":1,"explanation":"A. Incorrect. Les tests doivent \xeatre r\xe9alis\xe9s tout au long du cycle de vie, pas seulement \xe0 la fin. B. Correct. Int\xe9grer les tests \xe0 toutes les phases aide \xe0 identifier les erreurs d\xe8s le d\xe9part. C. Incorrect. Les tests sont importants dans tous les projets, quelle que soit leur taille. D. Incorrect. Bien que les m\xe9thodologies agiles favorisent la collaboration, les tests sont essentiels dans tout mod\xe8le.","source":"banco-extra"},{"id":"q_batch2_6ody8pkik","chapter":2,"topic":"Tests tout au long du SDLC","question":"Identifiez les cat\xe9gories de test suivantes (1-4) et les quadrants de tests agiles (A-D). Quelles combinaisons sont correctes ?\\n\\n1. Tests d\'acceptation utilisateur\\n2. Tests de performance\\n3. Tests d\'int\xe9gration de composants\\n4. Tests de user stories\\n\\nA (Q1). Orient\xe9 technologie, soutient l\'\xe9quipe de d\xe9veloppement  \\nB (Q2). Orient\xe9 m\xe9tier, soutient l\'\xe9quipe de d\xe9veloppement  \\nC (Q3). Orient\xe9 m\xe9tier, critique le produit  \\nD (Q4). Orient\xe9 technologie, critique le produit","options":["1A, 2B, 3C, 4D","1B, 2A, 3D, 4C","1D, 2C, 3B, 4A","1C, 2D, 3A, 4B"],"correctAnswer":3,"explanation":"A. Incorrect. Les tests d\'acceptation utilisateur (1) appartiennent au Q3 (m\xe9tier, critique le produit), pas au Q1. Les tests de performance (2) appartiennent au Q4, pas au Q2. B. Incorrect. Les tests d\'acceptation utilisateur (1) appartiennent au Q3, pas au Q2. Les tests d\'int\xe9gration de composants (3) appartiennent au Q1, pas au Q4. C. Incorrect. Les tests d\'acceptation utilisateur (1) appartiennent au Q3, pas au Q4. Les tests de user stories (4) appartiennent au Q2, pas au Q1. D. Correct. Tests d\'acceptation utilisateur (1) -> Q3 (m\xe9tier, critique le produit). Tests de performance (2) -> Q4 (technologie, critique le produit). Tests d\'int\xe9gration de composants (3) -> Q1 (technologie, soutient l\'\xe9quipe). Tests de user stories (4) -> Q2 (m\xe9tier, soutient l\'\xe9quipe).","source":"banco-extra"},{"id":"q_batch2_ne2ycbfxp","chapter":2,"topic":"Tests tout au long du SDLC","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX la m\xe9thodologie de d\xe9veloppement pilot\xe9 par les tests (TDD) ?  ","options":["Dans le TDD, les tests sont \xe9crits apr\xe8s l\'ach\xe8vement du d\xe9veloppement du logiciel.","Dans le TDD, on cr\xe9e d\'abord un test qui \xe9choue avant d\'\xe9crire le code pour faire passer le test.","Dans le TDD, seuls des tests d\'acceptation sont d\xe9velopp\xe9s \xe0 la fin du cycle de d\xe9veloppement.","Dans le TDD, le code et les tests sont d\xe9velopp\xe9s de mani\xe8re compl\xe8tement ind\xe9pendante."],"correctAnswer":1,"explanation":"A. Incorrect. Dans le TDD, les tests sont cr\xe9\xe9s avant d\'\xe9crire le code pour s\'assurer qu\'il r\xe9pond aux exigences. B. Correct. Dans le TDD, on r\xe9dige un test qui \xe9choue initialement, ce qui guide le d\xe9veloppement ult\xe9rieur du code. C. Incorrect. Dans le TDD, les tests sont \xe9crits en continu pendant le d\xe9veloppement, pas seulement \xe0 la fin. D. Incorrect. Dans le TDD, le d\xe9veloppement du code et les tests sont li\xe9s et non ind\xe9pendants.","source":"banco-extra"},{"id":1015,"chapter":3,"topic":"Tests statiques","question":"Laquelle des affirmations suivantes est VRAIE \xe0 propos des tests statiques ?  ","options":["Les tests statiques aident \xe0 r\xe9duire le temps de d\xe9veloppement en trouvant des d\xe9fauts d\xe8s les premi\xe8res \xe9tapes.","Les tests statiques d\xe9tectent toujours tous les types de d\xe9fauts dans le code source.","Les tests statiques sont plus efficaces que les tests dynamiques pour valider la fonctionnalit\xe9.","Les tests statiques ne peuvent pas \xeatre utilis\xe9s pour am\xe9liorer la qualit\xe9 de la documentation."],"correctAnswer":0,"explanation":"Trouver des probl\xe8mes de mani\xe8re statique (sans ex\xe9cuter le code) permet d\'\xe9conomiser beaucoup d\'argent et de temps.","source":"Pr\xe1ctica Adicional"},{"id":1016,"chapter":3,"topic":"Tests statiques","question":"Quel avantage le feedback pr\xe9coce et fr\xe9quent des parties prenantes apporte-t-il pendant le d\xe9veloppement du logiciel ?  ","options":["Il favorise l\'innovation dans les solutions propos\xe9es.","Il r\xe9duit la possibilit\xe9 de retravail en identifiant les probl\xe8mes \xe0 temps.","Il augmente la dur\xe9e du cycle de vie du produit.","Il am\xe9liore la satisfaction de l\'\xe9quipe de d\xe9veloppement."],"correctAnswer":1,"explanation":"Le feedback continu \xe9vite de construire le mauvais produit, r\xe9duisant un retravail co\xfbteux.","source":"Pr\xe1ctica Adicional"},{"id":1017,"chapter":3,"topic":"Tests statiques","question":"Dans votre organisation : Il n\'y a pas de r\xf4le de mod\xe9rateur. L\'objectif est de trouver des d\xe9fauts et de s\'am\xe9liorer. La discussion est ouverte. Aucune documentation formelle n\'est requise \xe0 la fin. De quel type de revue s\'agit-il ?  ","options":["Revue informelle","Revue technique","Inspection","Revue guid\xe9e"],"correctAnswer":0,"explanation":"Sans mod\xe9rateur, sans documentation et orient\xe9e vers l\'am\xe9lioration avec une discussion ouverte : Revue informelle.","source":"Pr\xe1ctica Adicional"},{"id":1018,"chapter":3,"topic":"Tests statiques","question":"Lequel des facteurs suivants est essentiel pour garantir l\'efficacit\xe9 d\'une revue ?  ","options":["Disposer d\'un facilitateur pour guider le processus de revue.","N\'autoriser que les experts \xe0 participer \xe0 toutes les revues.","Mener la revue de mani\xe8re improvis\xe9e sans pr\xe9paration pr\xe9alable.","Limiter le temps de discussion pour ne pas trop s\'\xe9tendre."],"correctAnswer":0,"explanation":"Un facilitateur ou d\'autres r\xf4les clairs am\xe9liorent le succ\xe8s. Cependant, dans certaines m\xe9thodologies, un autre facteur cl\xe9 est la \xab pr\xe9paration pr\xe9alable \xbb.","source":"Pr\xe1ctica Adicional"},{"id":1041,"chapter":3,"topic":"Tests statiques","question":"Laquelle des affirmations suivantes est un facteur cl\xe9 pour le succ\xe8s des revues ?  ","options":["La revue doit \xeatre r\xe9alis\xe9e dans un environnement d\xe9tendu et sans pressions externes.","Les relecteurs doivent avoir une connaissance pr\xe9alable du contenu qu\'ils revoient.","Il est pr\xe9f\xe9rable qu\'un seul participant parle pendant la revue pour \xe9viter les confusions.","L\'objectif de la revue doit \xeatre d\'identifier uniquement les erreurs critiques."],"correctAnswer":0,"explanation":"Un environnement d\xe9tendu permet une meilleure communication et collaboration entre les participants.","source":"Errores Reportados - Set 2"},{"id":1044,"chapter":3,"topic":"Tests statiques","question":"L\'auteur d\'un document de conception dirige une session de revue. Un scribe consigne les d\xe9fauts trouv\xe9s. Les participants peuvent poser des questions librement et l\'auteur explique sa conception. Aucun crit\xe8re d\'entr\xe9e ou de sortie formel n\'est utilis\xe9. Quel type de revue ce sc\xe9nario d\xe9crit-il ?  ","options":["Inspection","Revue technique","Walkthrough","Revue informelle"],"correctAnswer":2,"explanation":"Le walkthrough est dirig\xe9 par l\'auteur, dispose d\'un scribe et n\'a pas de crit\xe8res d\'entr\xe9e ou de sortie formels.","source":"Errores Reportados - Set 2"},{"id":264,"chapter":3,"topic":"Tests statiques","question":"Lequel des \xe9l\xe9ments suivants ne repr\xe9sente PAS un avantage des tests statiques\xa0?  ","options":["A) Avoir une gestion des d\xe9fauts moins co\xfbteuse en raison de la facilit\xe9 de d\xe9tection des d\xe9fauts plus tard dans le SDLC","B) La r\xe9paration des d\xe9fauts d\xe9tect\xe9s lors des tests statiques est g\xe9n\xe9ralement beaucoup moins co\xfbteuse que la r\xe9paration des d\xe9fauts d\xe9tect\xe9s lors des tests dynamiques","C) Rechercher des d\xe9fauts de codage qui n\'auraient peut-\xeatre pas \xe9t\xe9 d\xe9tect\xe9s en effectuant uniquement des tests dynamiques","D) D\xe9tecter les lacunes et les incoh\xe9rences dans les exigences"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#15, LO : FL-3.1.2). Justification\xa0: Avoir une gestion des d\xe9fauts moins co\xfbteuse en raison de la facilit\xe9 de d\xe9tection des d\xe9fauts plus tard dans le SDLC","source":"Official Sample Exam A Q#15"},{"id":265,"chapter":3,"topic":"Tests statiques","question":"Lequel des \xe9l\xe9ments suivants constitue un avantage d\u2019un retour d\u2019information pr\xe9coce et fr\xe9quent\xa0?  ","options":["A) Am\xe9liorer le processus de test pour les projets futurs","B) Force les clients \xe0 prioriser leurs exigences en fonction des risques convenus","C) Fournit une mesure de la qualit\xe9 des changements","D) Aide \xe0 \xe9viter les malentendus dans les exigences"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#16, LO : FL-3.2.1). Justification\xa0: Aide \xe0 \xe9viter les malentendus concernant les exigences","source":"Official Sample Exam A Q#16"},{"id":266,"chapter":3,"topic":"Tests statiques","question":"Les \xe9valuations utilis\xe9es dans votre organisation ont les attributs suivants\xa0: \u2022 Il y a un r\xf4le de scribe. \u2022 L\'objectif principal est d\'\xe9valuer la qualit\xe9. \u2022 La r\xe9union est dirig\xe9e par l\'auteur du produit du travail. \u2022 Il y a une pr\xe9paration individuelle. \u2022 Un rapport d\'\xe9valuation est produit. Lequel des types d\'\xe9valuation suivants est le PLUS susceptible d\'\xeatre utilis\xe9\xa0?  ","options":["A) Examen informel","B) Proc\xe9dure pas \xe0 pas","C) Examen technique","D) Contr\xf4le"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#17, LO : FL-3.2.4). Justification\xa0: Proc\xe9dure pas \xe0 pas","source":"Official Sample Exam A Q#17"},{"id":267,"chapter":3,"topic":"Tests statiques","question":"Laquelle de ces affirmations ne contribue PAS \xe0 la r\xe9ussite des \xe9valuations\xa0?  ","options":["A) Les participants doivent pr\xe9voir suffisamment de temps pour l\u2019examen","B) Divisez les gros produits de travail en petites parties afin que l\'effort requis soit moins intense","C) Les participants doivent \xe9viter les comportements pouvant indiquer de l\'ennui, de l\'exasp\xe9ration ou de l\'hostilit\xe9 envers les autres participants.","D) Les d\xe9faillances constat\xe9es doivent \xeatre reconnues, appr\xe9ci\xe9es et trait\xe9es objectivement"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#18, LO : FL-3.2.5). Justification\xa0:\xa0les d\xe9faillances constat\xe9es doivent \xeatre reconnues, appr\xe9ci\xe9es et trait\xe9es de mani\xe8re objective","source":"Official Sample Exam A Q#18"},{"id":302,"chapter":3,"topic":"Tests statiques","question":"Lequel des \xe9l\xe9ments suivants est un exemple de d\xe9faut qui peut \xeatre trouv\xe9 par les tests statiques mais PAS par les tests dynamiques ?  ","options":["A) Manque d\'utilisabilit\xe9 de l\'interface utilisateur","B) Code qu\'aucun chemin d\'ex\xe9cution n\'atteint (code mort)","C) Temps de r\xe9ponse m\xe9diocres pour la plupart des utilisateurs attendus","D) Fonctionnalit\xe9s requises qui ne sont pas impl\xe9ment\xe9es dans le code"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#15, LO : FL-3.1.3). Justification : Le code inatteignable (code mort) ne peut \xeatre d\xe9tect\xe9 que par analyse statique, car il n\'est jamais ex\xe9cut\xe9.","source":"Official Sample Exam B Q#15"},{"id":303,"chapter":3,"topic":"Tests statiques","question":"Lequel des \xe9l\xe9ments suivants est un avantage du feedback pr\xe9coce et fr\xe9quent des parties prenantes ?  ","options":["A) Les managers savent quels d\xe9veloppeurs sont les moins productifs","B) Il permet aux chefs de projet de prioriser leurs interactions avec les parties prenantes","C) Il facilite la communication pr\xe9coce des probl\xe8mes de qualit\xe9 potentiels","D) Les utilisateurs finaux comprennent mieux pourquoi la livraison du produit de travail est retard\xe9e"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#16, LO : FL-3.2.1). Justification : Le feedback pr\xe9coce facilite la communication anticip\xe9e des probl\xe8mes de qualit\xe9 potentiels.","source":"Official Sample Exam B Q#16"},{"id":304,"chapter":3,"topic":"Tests statiques","question":"\xc9tant donn\xe9es les descriptions de t\xe2ches suivantes : Laquelle des options suivantes \xe9tablit la MEILLEURE correspondance entre les descriptions de t\xe2ches et les activit\xe9s ?\\n\\n1. On s\xe9lectionne les caract\xe9ristiques de qualit\xe9 \xe0 \xe9valuer et les crit\xe8res de sortie\\n2. Tout le monde a acc\xe8s au produit de travail\\n3. On identifie des anomalies dans le produit de travail\\n4. On discute des anomalies\\n\\nA. Revue individuelle  \\nB. Lancement de la revue  \\nC. Planification  \\nD. Communication et analyse","options":["A) 1B, 2C, 3D, 4A","B) 1B, 2D, 3C, 4A","C) 1C, 2A, 3B, 4D","D) 1C, 2B, 3A, 4D"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#17, LO : FL-3.2.2). Justification : La planification d\xe9finit les crit\xe8res (1C), le lancement donne acc\xe8s au document (2B), la revue individuelle identifie les anomalies (3A) et la communication et l\'analyse les discutent (4D).","source":"Official Sample Exam B Q#17"},{"id":305,"chapter":3,"topic":"Tests statiques","question":"\xc9tant donn\xe9s les r\xf4les de revue suivants : Laquelle des options suivantes \xe9tablit la MEILLEURE correspondance entre les r\xf4les et les responsabilit\xe9s ?\\n\\n1. Secr\xe9taire/Scribe\\n2. Responsable de la revue\\n3. Facilitateur\\n4. Manager\\n\\nA. Garantit le d\xe9roulement efficace des r\xe9unions de revue et \xe9tablit un environnement s\xfbr  \\nB. Consigne les informations de la revue, comme les d\xe9cisions et les nouvelles anomalies trouv\xe9es  \\nC. D\xe9cide de ce qui sera revu et fournit des ressources comme du personnel et du temps  \\nD. Assume la responsabilit\xe9 globale de la revue : quand et o\xf9 elle aura lieu","options":["A) 1A, 2B, 3D, 4C","B) 1A, 2C, 3B, 4D","C) 1B, 2D, 3A, 4C","D) 1B, 2D, 3C, 4A"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#18, LO : FL-3.2.3). Justification : Le Scribe consigne (1B), le Responsable organise la revue (2D), le Facilitateur g\xe8re la r\xe9union (3A) et le Manager d\xe9cide des ressources (4C).","source":"Official Sample Exam B Q#18"},{"id":339,"chapter":3,"topic":"Tests statiques","question":"\xc9tant donn\xe9s les exemples de d\xe9fauts suivants :  \\n  \\ni. Deux parties diff\xe9rentes de la sp\xe9cification de conception se contredisent en raison de la complexit\xe9 de la conception  \\n  \\nii. Un temps de r\xe9ponse est trop long et fait perdre patience aux utilisateurs  \\n  \\niii. Un chemin dans le code ne peut pas \xeatre atteint pendant l\'ex\xe9cution  \\n  \\niv. Une variable est d\xe9clar\xe9e mais jamais utilis\xe9e dans le programme  \\n  \\nv. La quantit\xe9 de m\xe9moire dont le programme a besoin pour g\xe9n\xe9rer un rapport est excessive. Laquelle des options suivantes identifie le MIEUX les d\xe9fauts qui pourraient \xeatre trouv\xe9s par les tests statiques (plut\xf4t que dynamiques) ?  ","options":["A) ii, v","B) iii, v","C) i, ii, iv","D) i, iii, iv"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#15, LO : FL-3.1.3). Justification : Les contradictions dans la sp\xe9cification (i), le code inatteignable (iii) et les variables inutilis\xe9es (iv) sont d\xe9tect\xe9s par revue ou analyse statique sans ex\xe9cuter le code.","source":"Official Sample Exam C Q#15"},{"id":340,"chapter":3,"topic":"Tests statiques","question":"\xc9tant donn\xe9s les types de revue suivants : Laquelle des options suivantes \xe9tablit la MEILLEURE correspondance ?\\n\\n1. Revue technique\\n2. Revue informelle\\n3. Inspection\\n4. Walkthrough\\n\\nA. Inclut des objectifs comme atteindre un consensus, g\xe9n\xe9rer de nouvelles id\xe9es et motiver les auteurs \xe0 s\'am\xe9liorer  \\nB. Inclut des objectifs comme former les relecteurs, atteindre un consensus, g\xe9n\xe9rer de nouvelles id\xe9es et d\xe9tecter des d\xe9fauts potentiels  \\nC. L\'objectif principal est de d\xe9tecter des d\xe9fauts potentiels et n\xe9cessite la collecte de m\xe9triques pour l\'am\xe9lioration du processus  \\nD. L\'objectif principal est de d\xe9tecter des d\xe9fauts potentiels et ne g\xe9n\xe8re pas de documentation de sortie formelle","options":["A) 1A, 2B, 3C, 4D","B) 1A, 2D, 3C, 4B","C) 1B, 2C, 3D, 4A","D) 1C, 2D, 3A, 4B"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#16, LO : FL-3.2.1). Justification : Revue technique->consensus et nouvelles id\xe9es (1A), Informelle->sans documentation formelle (2D), Inspection->m\xe9triques (3C), Walkthrough->forme les relecteurs et g\xe9n\xe8re des id\xe9es (4B).","source":"Official Sample Exam C Q#17"},{"id":341,"chapter":3,"topic":"Tests statiques","question":"Lequel des \xe9l\xe9ments suivants est un facteur qui contribue \xe0 une revue r\xe9ussie ?  ","options":["A) Les relecteurs sont des experts du domaine de l\'objet \xe0 revoir","B) Les relecteurs effectuent leurs revues \xe0 voix haute pendant la r\xe9union de revue","C) L\'auteur ne participe pas \xe0 la planification de la revue","D) Les participants revoient leurs propres produits de travail"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#17, LO : FL-3.2.4). Justification : Que les relecteurs soient des experts du domaine garantit qu\'ils peuvent d\xe9tecter des d\xe9fauts pertinents.","source":"Official Sample Exam C Q#18"},{"id":373,"chapter":3,"topic":"Tests statiques","question":"Lequel des \xe9l\xe9ments suivants NE PEUT PAS \xeatre examin\xe9 par les tests statiques ?  ","options":["A) Contrat","B) Plan de test","C) Code chiffr\xe9","D) Charte de test (test charter)"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#15, LO : FL-3.1.1). Justification : Le code chiffr\xe9 ne peut pas \xeatre analys\xe9 statiquement car son contenu est illisible pour les outils d\'analyse statique et les relecteurs.","source":"Official Sample Exam D Q#15"},{"id":374,"chapter":3,"topic":"Tests statiques","question":"Laquelle des affirmations suivantes sur la valeur des tests statiques est CORRECTE ?  ","options":["A) Les types de d\xe9fauts trouv\xe9s par les tests statiques sont diff\xe9rents de ceux que les tests dynamiques peuvent trouver","B) Les tests dynamiques peuvent d\xe9tecter les types de d\xe9fauts trouv\xe9s par les tests statiques, plus quelques-uns suppl\xe9mentaires","C) Les tests dynamiques peuvent identifier certains des d\xe9fauts trouv\xe9s par les tests statiques, mais pas tous","D) Les tests statiques peuvent identifier les types de d\xe9fauts trouv\xe9s par les tests dynamiques, plus quelques-uns suppl\xe9mentaires"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#16, LO : FL-3.1.2). Justification : Les tests dynamiques ne peuvent pas trouver des d\xe9fauts comme le code inatteignable, les variables inutilis\xe9es ou les incoh\xe9rences de documentation, que seuls les tests statiques d\xe9tectent.","source":"Official Sample Exam D Q#16"},{"id":375,"chapter":3,"topic":"Tests statiques","question":"\xc9tant donn\xe9es les descriptions suivantes d\'activit\xe9s de revue :  \\n  \\n1. Les anomalies d\xe9tect\xe9es sont discut\xe9es et des d\xe9cisions sont prises sur leur statut, leur propri\xe9taire et les \xe9tapes suivantes  \\n  \\n2. Les d\xe9fauts sont consign\xe9s et les mises \xe0 jour n\xe9cessaires sont trait\xe9es avant l\'acceptation du produit de travail  \\n  \\n3. Les relecteurs emploient des techniques pour g\xe9n\xe9rer des suggestions et des questions sur le produit de travail et identifier des anomalies  \\n  \\n4. L\'objectif de la revue et son calendrier sont \xe9tablis pour garantir une revue cibl\xe9e et efficace  \\n  \\n5. Les participants re\xe7oivent l\'acc\xe8s \xe0 l\'\xe9l\xe9ment \xe0 revoir. Quelle est la s\xe9quence CORRECTE des activit\xe9s du processus de revue ?  ","options":["A) 4 - 3 - 5 - 2 - 1","B) 4 - 5 - 3 - 1 - 2","C) 5 - 4 - 1 - 3 - 2","D) 5 - 4 - 3 - 2 - 1"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#17, LO : FL-3.2.2). Justification : S\xe9quence correcte : Planification (4) -> Lancement de la revue/acc\xe8s (5) -> Revue individuelle (3) -> Communication et analyse (1) -> Correction et rapport (2).","source":"Official Sample Exam D Q#17"},{"id":376,"chapter":3,"topic":"Tests statiques","question":"Quel participant au processus de revue est responsable de garantir que les r\xe9unions de revue se d\xe9roulent efficacement et que chacun peut exprimer librement ses opinions ?  ","options":["A) Manager","B) Mod\xe9rateur","C) Pr\xe9sident","D) Responsable de la revue"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#18, LO : FL-3.2.3). Justification : Mod\xe9rateur.","source":"Official Sample Exam D Q#18"},{"id":411,"chapter":3,"topic":"Tests statiques","question":"Lors d\'une inspection des exigences, le mod\xe9rateur trouve la phrase : \xab Le syst\xe8me devra \xeatre rapide \xbb. Quel type de d\xe9faut d\'exigence cette affirmation repr\xe9sente-t-elle ?  ","options":["A) Exigence dupliqu\xe9e","B) Exigence ambigu\xeb et non v\xe9rifiable","C) Exigence en conflit","D) Exigence hors p\xe9rim\xe8tre"],"correctAnswer":1,"explanation":"\xab Rapide \xbb est ambigu et non v\xe9rifiable car cela ne sp\xe9cifie pas de crit\xe8re mesurable. Une exigence correcte dirait, par exemple, \xab Le syst\xe8me devra r\xe9pondre en moins de 2 secondes pour 95 % des requ\xeates \xbb.","source":"banco"},{"id":412,"chapter":3,"topic":"Tests statiques","question":"Un outil d\'analyse statique signale : \xab Variable x d\xe9clar\xe9e mais jamais utilis\xe9e dans la fonction calculerTotal() \xbb. Comment cette constatation est-elle class\xe9e dans la terminologie ISTQB ?  ","options":["A) D\xe9faillance (failure)","B) Erreur (mistake)","C) D\xe9faut (bug/fault)","D) Incident"],"correctAnswer":2,"explanation":"L\'analyse statique trouve des d\xe9fauts (faults/bugs) dans le code sans l\'ex\xe9cuter. Une variable d\xe9clar\xe9e mais inutilis\xe9e est un d\xe9faut de code d\xe9tect\xe9 statiquement.","source":"banco"},{"id":421,"chapter":3,"topic":"Tests statiques","question":"Lequel des documents suivants peut faire l\'objet d\'une revue statique ?  ","options":["A) Uniquement le code source","B) Uniquement les exigences","C) Tout produit de travail : exigences, conception, code, cas de test, plans","D) Uniquement les documents livr\xe9s au client"],"correctAnswer":2,"explanation":"Les tests statiques peuvent s\'appliquer \xe0 tout produit de travail \xe9crit : exigences, sp\xe9cifications de conception, code source, cas de test, plans de test, contrats, etc.","source":"banco"},{"id":434,"chapter":3,"topic":"Tests statiques","question":"Une organisation r\xe9alise une revue o\xf9 : il y a un mod\xe9rateur ind\xe9pendant, les relecteurs se pr\xe9parent individuellement, des m\xe9triques de d\xe9fauts sont enregistr\xe9es et un rapport formel est produit. De quel type de revue s\'agit-il ?  ","options":["A) Revue informelle","B) Walkthrough","C) Revue technique","D) Inspection"],"correctAnswer":3,"explanation":"L\'Inspection est la revue la plus formelle : elle a un mod\xe9rateur form\xe9, une pr\xe9paration individuelle, des r\xf4les d\xe9finis (auteur, mod\xe9rateur, scribe, relecteurs), des m\xe9triques collect\xe9es et un rapport de sortie formel.","source":"banco"},{"id":435,"chapter":3,"topic":"Tests statiques","question":"Quelle est la principale diff\xe9rence entre une inspection et un walkthrough dans les revues statiques ?  ","options":["A) Le walkthrough est plus formel que l\'inspection","B) Dans le walkthrough, l\'auteur dirige la r\xe9union ; dans l\'inspection, c\'est un mod\xe9rateur ind\xe9pendant","C) L\'inspection ne n\xe9cessite aucune pr\xe9paration pr\xe9alable ; le walkthrough oui","D) Le walkthrough produit des m\xe9triques formelles ; pas l\'inspection"],"correctAnswer":1,"explanation":"Dans le Walkthrough, l\'auteur guide les participants \xe0 travers son produit de travail. Dans l\'Inspection, un mod\xe9rateur ind\xe9pendant dirige le processus en suivant un processus d\xe9fini avec plus de formalit\xe9 et de rigueur.","source":"banco"},{"id":441,"chapter":3,"topic":"Tests statiques","question":"Lequel des d\xe9fauts suivants est plus susceptible d\'\xeatre trouv\xe9 par analyse statique que par tests dynamiques ?  ","options":["A) Un calcul qui renvoie un r\xe9sultat incorrect dans des conditions sp\xe9cifiques","B) Une variable qui peut \xeatre nulle (null pointer) sur un certain chemin du code jamais atteint dans les tests dynamiques","C) Un bouton de l\'IHM qui ne fonctionne pas dans Firefox","D) Un temps de r\xe9ponse lent sous forte charge"],"correctAnswer":1,"explanation":"L\'analyse statique peut d\xe9tecter d\'\xe9ventuelles exceptions de pointeur nul (null pointer), du code mort ou des chemins jamais ex\xe9cut\xe9s que les tests dynamiques ne couvrent pas. Elle est particuli\xe8rement utile pour les d\xe9fauts dans les chemins de code rarement ex\xe9cut\xe9s.","source":"banco"},{"id":453,"chapter":3,"topic":"Tests statiques","question":"CAS PRATIQUE : Dans une revue de sp\xe9cification des exigences, vous trouvez : \xab Le syst\xe8me devra traiter les transactions rapidement et l\'interface devra \xeatre conviviale \xbb. Quels types de d\xe9fauts d\'exigences sont pr\xe9sents ?  ","options":["A) Uniquement de l\'ambigu\xeft\xe9","B) Ambigu\xeft\xe9 (\xab rapidement \xbb, \xab conviviale \xbb) et manque de v\xe9rifiabilit\xe9 : ni mesurables ni testables","C) Contradiction entre exigences","D) Exigences dupliqu\xe9es"],"correctAnswer":1,"explanation":"\xab Rapidement \xbb et \xab conviviale \xbb sont des termes ambigus et non v\xe9rifiables. De bonnes exigences doivent \xeatre sp\xe9cifiques et mesurables (ex. : \xab traiter en <2 s \xbb, \xab score SUS >75 \xbb). C\'est le d\xe9faut le plus courant dans les revues d\'exigences.","source":"banco"},{"id":458,"chapter":3,"topic":"Tests statiques","question":"CAS PRATIQUE : Votre organisation met en place des revues de code obligatoires. L\'\xe9quipe de d\xe9veloppement se plaint qu\'elles ralentissent le processus. Quel est l\'argument le PLUS solide pour justifier les revues ?  ","options":["A) Elles sont obligatoires par r\xe9glementation, il n\'y a pas d\'alternative","B) Le co\xfbt de correction des d\xe9fauts trouv\xe9s en revue est nettement inf\xe9rieur \xe0 celui de leur correction en production","C) Les revues am\xe9liorent le moral de l\'\xe9quipe","D) L\'outil de revue a \xe9t\xe9 pay\xe9 et doit \xeatre amorti"],"correctAnswer":1,"explanation":"L\'argument \xe9conomique est le plus solide : trouver un d\xe9faut en revue de code co\xfbte ~1x ; en test syst\xe8me ~10x ; en production ~100x. Les revues ont le meilleur ROI pour la d\xe9tection pr\xe9coce des d\xe9fauts.","source":"banco"},{"id":465,"chapter":3,"topic":"Tests statiques","question":"Lequel des \xe9l\xe9ments suivants est un exemple de technique d\'analyse statique ?  ","options":["A) Ex\xe9cuter le logiciel avec des donn\xe9es de test","B) Utiliser un linter ou un outil d\'analyse de code pour d\xe9tecter les violations de standards","C) Tester l\'interface utilisateur manuellement","D) Mesurer le temps de r\xe9ponse du syst\xe8me"],"correctAnswer":1,"explanation":"L\'analyse statique examine le code sans l\'ex\xe9cuter. Les outils linter (comme SonarQube, ESLint, Checkstyle) d\xe9tectent les violations de standards, le code mort, les \xe9ventuels pointeurs nuls, etc. sans ex\xe9cuter le programme.","source":"banco"},{"id":"q_batch2_j6kuaxygc","chapter":3,"topic":"Tests statiques","question":"Laquelle des affirmations suivantes d\xe9crit le mieux un avantage des tests statiques ?  ","options":["Les tests statiques sont utiles pour identifier les d\xe9fauts qui ne se manifestent que pendant l\'ex\xe9cution du logiciel.","Les tests statiques permettent la revue de documents et de code sans avoir besoin d\'ex\xe9cuter le logiciel.","Les tests statiques n\xe9cessitent g\xe9n\xe9ralement plus de temps que les tests dynamiques pour \xeatre efficaces.","Les tests statiques sont moins efficaces pour d\xe9tecter les d\xe9fauts de conception que les tests dynamiques."],"correctAnswer":1,"explanation":"A. Incorrect. Les tests statiques n\'impliquent pas l\'ex\xe9cution du logiciel, ils ne peuvent donc pas identifier les d\xe9fauts qui ne se manifestent qu\'\xe0 l\'ex\xe9cution. B. Correct. C\'est l\'un des principaux avantages des tests statiques, car ils permettent de revoir documents et code sans ex\xe9cution. C. Incorrect. Les tests statiques sont g\xe9n\xe9ralement plus rapides que les tests dynamiques car ils ne n\xe9cessitent pas d\'ex\xe9cution. D. Incorrect. Les tests statiques peuvent \xeatre efficaces pour d\xe9tecter les d\xe9fauts de conception, contrairement \xe0 ce qui est sugg\xe9r\xe9 ici.","source":"banco-extra"},{"id":"q_batch2_n23h74aj8","chapter":3,"topic":"Tests statiques","question":"Dans votre organisation, des revues sont men\xe9es avec les caract\xe9ristiques suivantes : Aucun scribe n\'est requis. L\'objectif est de d\xe9tecter des anomalies de mani\xe8re non structur\xe9e. Les participants sont des experts du domaine. Il n\'y a pas de mod\xe9rateur d\xe9sign\xe9. Quel type de revue est le PLUS probablement men\xe9 ?  ","options":["Revue informelle","Revue technique","Inspection","Revue guid\xe9e"],"correctAnswer":0,"explanation":"A. Correct. Les revues informelles sont le type de revue d\xe9crit. Selon le syllabus CTFL v4.0, section 3.2.4, les revues informelles ne suivent pas de processus d\xe9fini et ne n\xe9cessitent pas de sortie formellement document\xe9e. Leur objectif principal est de d\xe9tecter des anomalies. Les caract\xe9ristiques du sc\xe9nario - sans scribe, sans mod\xe9rateur d\xe9sign\xe9, participants experts, objectif de d\xe9tection d\'anomalies de mani\xe8re non structur\xe9e - sont totalement coh\xe9rentes avec ce type de revue. B. Les revues techniques n\xe9cessitent g\xe9n\xe9ralement un mod\xe9rateur et une approche plus structur\xe9e de la qualit\xe9 du produit, ce qui n\'est pas mentionn\xe9 dans les caract\xe9ristiques donn\xe9es. C. Incorrect. Les inspections sont le type de revue le plus formel. Elles requi\xe8rent des r\xf4les sp\xe9cifiques (mod\xe9rateur form\xe9, scribe, auteur), suivent un processus structur\xe9 et collectent des m\xe9triques pour l\'am\xe9lioration du processus du SDLC. Le sc\xe9nario ne d\xe9crit aucun de ces \xe9l\xe9ments formels. D. Les revues guid\xe9es n\xe9cessitent une pr\xe9paration et un mod\xe9rateur, qui ne sont pas mentionn\xe9s dans la description, et leur objectif principal est d\'\xe9valuer la qualit\xe9, pas d\'am\xe9liorer le processus.","source":"banco-extra"},{"id":1019,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes d\xe9crit le mieux une technique de test en bo\xeete blanche ?  ","options":["Elle repose sur la connaissance du fonctionnement interne du logiciel et de sa structure de code.","Elle est principalement utilis\xe9e pour \xe9valuer l\'exp\xe9rience utilisateur et l\'utilisabilit\xe9 du syst\xe8me.","Les cas de test sont con\xe7us sans tenir compte de la logique interne du syst\xe8me.","Elle se concentre sur l\'identification des d\xe9fauts dans les exigences via des tests d\'interface."],"correctAnswer":0,"explanation":"La bo\xeete blanche repose sur la structure interne (code, architecture).","source":"Pr\xe1ctica Adicional"},{"id":1020,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un syst\xe8me de notation accepte des scores 0-100. \xc9chec : 0-59, R\xe9ussi : 60-69, Bien : 70-89, Excellent : 90-100. En utilisant le partitionnement d\'\xe9quivalence, quel est le nombre MINIMUM de cas de test pour atteindre 100 % de couverture des partitions VALIDES ?  ","options":["3","4","5","6"],"correctAnswer":1,"explanation":"Il y a 4 partitions valides : [0,59], [60,69], [70,89], [90,100]. Un cas est n\xe9cessaire pour chacune, soit 4 cas.","source":"Pr\xe1ctica Adicional"},{"id":1021,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Le champ \xab \xc2ge \xbb accepte de 16 \xe0 65 ans. Votre ensemble inclut : 15, 16, 17, 64, 65, 66. Quel pourcentage de couverture de l\'analyse des valeurs limites (AVL) \xe0 3 valeurs atteignez-vous ?  ","options":["50 %","67 %","83 %","100 %"],"correctAnswer":3,"explanation":"En AVL \xe0 3 valeurs, une limite \xab X \xbb n\xe9cessite X-1, X, X+1. Pour 16 il faut 15,16,17. Pour 65 il faut 64,65,66. Vous les avez tous, couverture 100 %.","source":"Pr\xe1ctica Adicional"},{"id":1022,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Dans une table de d\xe9cision pour des pr\xeats, vous avez 4 conditions. Si vous vouliez minimiser la table en raison du grand nombre de combinaisons, quelle serait la meilleure strat\xe9gie ?  ","options":["Supprimer toutes les conditions les moins importantes","Utiliser une approche bas\xe9e sur les risques pour r\xe9duire les r\xe8gles \xe0 tester","Combiner toutes les conditions en une seule r\xe8gle","Cr\xe9er plusieurs petites tables s\xe9par\xe9es"],"correctAnswer":1,"explanation":"Lorsqu\'une table est massive (ex. 2^N r\xe8gles), la strat\xe9gie sugg\xe9r\xe9e par l\'ISTQB est de minimiser en utilisant une approche bas\xe9e sur les risques.","source":"Pr\xe1ctica Adicional"},{"id":1023,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes sur les crit\xe8res de couverture dans les tests de transition d\'\xe9tats est CORRECTE ?  ","options":["La couverture de tous les \xe9tats est plus forte que la couverture des transitions valides","La couverture des transitions valides garantit une couverture compl\xe8te de tous les \xe9tats","La couverture de toutes les transitions inclut uniquement les transitions valides","Pour atteindre la couverture des transitions valides, vous ne devez tester qu\'une seule transition par cas de test"],"correctAnswer":1,"explanation":"Si vous couvrez toutes les transitions valides (fl\xe8ches), vous avez n\xe9cessairement visit\xe9 tous les \xe9tats (n\u0153uds). Par cons\xe9quent, la couverture des transitions valides est plus forte que la couverture des \xe9tats.","source":"Pr\xe1ctica Adicional"},{"id":1024,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes est vraie concernant la couverture des instructions dans les tests logiciels ?  ","options":["La couverture des instructions garantit que tous les cas de test ont trouv\xe9 des d\xe9fauts.","Atteindre 100 % de couverture des instructions signifie que toutes les instructions du code ont \xe9t\xe9 ex\xe9cut\xe9es au moins une fois.","La couverture des instructions est sans importance si des tests fonctionnels exhaustifs sont r\xe9alis\xe9s.","Une couverture des instructions de 100 % garantit qu\'il n\'y a pas de boucles dans le code."],"correctAnswer":1,"explanation":"100 % de couverture des instructions signifie que chaque ligne/instruction a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois.","source":"Pr\xe1ctica Adicional"},{"id":1025,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes d\xe9crit le mieux un avantage des tests en bo\xeete blanche ?  ","options":["Les tests en bo\xeete blanche permettent de v\xe9rifier la logique interne du code et son flux d\'ex\xe9cution.","Les tests en bo\xeete blanche sont utiles pour valider l\'exp\xe9rience utilisateur dans l\'interface graphique.","Les tests en bo\xeete blanche garantissent que toutes les exigences fonctionnelles ont \xe9t\xe9 correctement impl\xe9ment\xe9es.","Les tests en bo\xeete blanche sont toujours plus efficaces que les tests en bo\xeete noire sans besoin d\'analyse de conception."],"correctAnswer":0,"explanation":"Ils permettent de v\xe9rifier la logique interne, de trouver des branches mortes et de contr\xf4ler les structures du code.","source":"Pr\xe1ctica Adicional"},{"id":1026,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes SE R\xc9F\xc8RE \xe0 la pr\xe9diction d\'erreurs dans un processus de test ?  ","options":["La pr\xe9diction d\'erreurs repose uniquement sur des m\xe9triques quantitatives de d\xe9fauts ant\xe9rieurs.","La pr\xe9diction d\'erreurs consiste \xe0 identifier les zones du logiciel les plus susceptibles de contenir des d\xe9fauts \xe0 partir de l\'exp\xe9rience.","La pr\xe9diction d\'erreurs exige que les testeurs r\xe9alisent des tests unitaires sur toutes les fonctions.","La pr\xe9diction d\'erreurs est un processus que seuls les d\xe9veloppeurs peuvent r\xe9aliser."],"correctAnswer":1,"explanation":"L\'error guessing (pr\xe9diction d\'erreurs) d\xe9pend \xe9norm\xe9ment de l\'exp\xe9rience du testeur pour deviner o\xf9 les d\xe9veloppeurs se sont typiquement tromp\xe9s.","source":"Pr\xe1ctica Adicional"},{"id":1027,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Une \xe9quipe cr\xe9e une application mobile innovante, et les tests exploratoires seront utilis\xe9s en raison du manque de documentation. Laquelle des affirmations suivantes sur les tests exploratoires est CORRECTE ?  ","options":["Les tests exploratoires sont toujours moins efficaces que les tests bas\xe9s sur les exigences.","Les tests exploratoires permettent aux testeurs de s\'adapter rapidement aux changements du logiciel.","Les tests exploratoires n\xe9cessitent un plan de test d\xe9taill\xe9 avant d\'\xeatre r\xe9alis\xe9s.","Les tests exploratoires ne conviennent pas aux applications complexes."],"correctAnswer":1,"explanation":"Ils sont flexibles, adaptatifs et id\xe9aux quand la documentation est rare ou changeante.","source":"Pr\xe1ctica Adicional"},{"id":1028,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes d\xe9crit UNE technique appropri\xe9e pour r\xe9diger des crit\xe8res d\'acceptation ?  ","options":["\xc9tablir les crit\xe8res sous forme de questions ouvertes pour encourager la discussion.","Utiliser des exemples concrets qui illustrent comment la fonctionnalit\xe9 est cens\xe9e fonctionner.","Documenter les crit\xe8res dans un document s\xe9par\xe9 pour am\xe9liorer l\'organisation.","R\xe9diger les crit\xe8res dans un langage technique pour garantir la pr\xe9cision des d\xe9tails."],"correctAnswer":1,"explanation":"Dans les approches agiles/ATDD, les exemples concrets (ex. Behavior Driven Development avec Given-When-Then) sont la meilleure mani\xe8re de documenter les crit\xe8res d\'acceptation.","source":"Pr\xe1ctica Adicional"},{"id":1029,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Une \xe9quipe agile utilise l\'ATDD. Quand les cas de test d\'acceptation sont-ils cr\xe9\xe9s dans l\'approche ATDD ?  ","options":["Apr\xe8s que le d\xe9veloppeur a termin\xe9 d\'impl\xe9menter la user story.","Pendant l\'atelier de sp\xe9cification, avant que le d\xe9veloppement ne commence.","Uniquement pendant la phase de tests de r\xe9gression \xe0 la fin du sprint.","Lorsque le client r\xe9alise le test d\'acceptation utilisateur (UAT)."],"correctAnswer":1,"explanation":"La cl\xe9 de l\'Acceptance Test Driven Development (ATDD) est de r\xe9diger le test d\'acceptation en collaboration *avant* d\'\xe9crire du code.","source":"Pr\xe1ctica Adicional"},{"id":1031,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes sur les crit\xe8res de couverture dans les tests de transition d\'\xe9tats est CORRECTE ?  ","options":["La couverture de tous les \xe9tats est plus forte que la couverture des transitions valides","La couverture des transitions valides garantit une couverture compl\xe8te de tous les \xe9tats","La couverture de toutes les transitions inclut uniquement les transitions valides","Pour atteindre la couverture des transitions valides, vous ne devez tester qu\'une seule transition par cas de test"],"correctAnswer":1,"explanation":"Atteindre une couverture compl\xe8te des transitions valides garantit une couverture compl\xe8te de tous les \xe9tats, car pour exercer toutes les transitions valides, il faut n\xe9cessairement visiter tous les \xe9tats.","source":"Errores Reportados - Set 2"},{"id":1032,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes est vraie concernant la couverture des instructions dans les tests logiciels ?  ","options":["La couverture des instructions garantit que tous les cas de test ont trouv\xe9 des d\xe9fauts.","Atteindre 100 % de couverture des instructions signifie que toutes les instructions du code ont \xe9t\xe9 ex\xe9cut\xe9es au moins une fois.","La couverture des instructions est sans importance si des tests fonctionnels exhaustifs sont r\xe9alis\xe9s.","Une couverture des instructions de 100 % garantit qu\'il n\'y a pas de boucles dans le code."],"correctAnswer":1,"explanation":"100 % de couverture des instructions signifie que chaque instruction du code a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois pendant les tests.","source":"Errores Reportados - Set 2"},{"id":1033,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes est correcte concernant les tests en bo\xeete blanche ?  ","options":["Les tests en bo\xeete blanche se concentrent sur la fonctionnalit\xe9 du logiciel sans consid\xe9rer sa structure interne.","L\'analyse du flux de donn\xe9es est une technique utilis\xe9e dans les tests en bo\xeete blanche pour identifier d\'\xe9ventuelles erreurs.","Les tests en bo\xeete blanche sont moins efficaces que ceux en bo\xeete noire pour d\xe9tecter les d\xe9fauts de la logique m\xe9tier.","Les tests en bo\xeete blanche se limitent \xe0 v\xe9rifier la bonne impl\xe9mentation des exigences de l\'utilisateur."],"correctAnswer":1,"explanation":"L\'analyse du flux de donn\xe9es est une technique de test en bo\xeete blanche qui aide \xe0 identifier les erreurs dans l\'utilisation des variables et leur flux \xe0 travers le code.","source":"Errores Reportados - Set 2"},{"id":1034,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes d\xe9crit le plus ad\xe9quatement comment les crit\xe8res d\'acceptation peuvent \xeatre d\xe9finis pour une user story ?  ","options":["En sp\xe9cifiant uniquement les exigences fonctionnelles sans d\xe9tails sur la validation.","En d\xe9crivant les r\xe9sultats attendus \xe0 l\'aide d\'un format clair et concis incluant des exemples concrets.","En se concentrant uniquement sur l\'impl\xe9mentation technique \xe0 r\xe9aliser pour satisfaire la user story.","En g\xe9n\xe9rant un document volumineux incluant tous les aspects du projet, pas seulement ceux li\xe9s \xe0 la user story."],"correctAnswer":1,"explanation":"Utiliser un format clair et des exemples concrets aide toutes les parties prenantes \xe0 mieux comprendre les crit\xe8res d\'acceptation.","source":"Errores Reportados - Set 2"},{"id":1045,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous \xeates responsable d\'un projet logiciel o\xf9 plusieurs risques ont \xe9t\xe9 identifi\xe9s, mais le temps pour les tests est limit\xe9. L\'\xe9quipe de d\xe9veloppement a livr\xe9 l\'application sans documentation d\xe9taill\xe9e. Quelle serait la meilleure technique de test \xe0 utiliser dans cette situation ?  ","options":["Tests bas\xe9s sur les risques","Tests exploratoires","Tests automatis\xe9s","Tests de r\xe9gression"],"correctAnswer":1,"explanation":"Les tests exploratoires conviennent quand il y a peu de documentation et que le temps est limit\xe9 ; les testeurs utilisent leur exp\xe9rience pour explorer et \xe9valuer le syst\xe8me de mani\xe8re heuristique.","source":"Errores Reportados - Set 2"},{"id":1049,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous avez un bloc de code avec 120 instructions ex\xe9cutables. Apr\xe8s l\'ex\xe9cution de votre ensemble de tests, les rapports indiquent que exactement 90 instructions ont \xe9t\xe9 exerc\xe9es. Quel niveau de couverture des instructions a \xe9t\xe9 atteint ?  ","options":["25 %","90 %","120 %","75 %"],"correctAnswer":3,"explanation":"La couverture des instructions se calcule comme : (instructions ex\xe9cut\xe9es / total des instructions) * 100. Dans ce cas : (90 / 120) * 100 = 75 %.","source":"Generadas (Agile/Metrics)"},{"id":1050,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un testeur logiciel veut calculer la couverture atteinte par ses tests. Le composant test\xe9 a 50 instructions ex\xe9cutables et 12 branches possibles. Pendant les tests, 45 instructions et 9 branches ont \xe9t\xe9 ex\xe9cut\xe9es. Quelle est la m\xe9trique de couverture des BRANCHES atteinte ?  ","options":["90 %","75 %","45 %","12 %"],"correctAnswer":1,"explanation":"La couverture des branches se concentre uniquement sur le nombre de branches (d\xe9cisions) exerc\xe9es. Elle se calcule : (branches exerc\xe9es / total des branches) * 100. Donc : (9 / 12) * 100 = 75 %. Les instructions ex\xe9cut\xe9es (45/50 = 90 %) sont sans importance pour calculer la couverture des branches.","source":"Generadas (Agile/Metrics)"},{"id":1051,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un ensemble de tests couvre 8 des 10 transitions valides totales d\'un diagramme d\'\xe9tats. Quel pourcentage de couverture des transitions valides a \xe9t\xe9 atteint, et que peut-on affirmer avec une certitude totale sur la couverture des \xe9tats ?  ","options":["80 % ; Il est garanti que tous les \xe9tats ont \xe9t\xe9 visit\xe9s (100 % de couverture des \xe9tats).","80 % ; Pas n\xe9cessairement tous les \xe9tats ont \xe9t\xe9 visit\xe9s.","20 % ; Pas n\xe9cessairement tous les \xe9tats ont \xe9t\xe9 visit\xe9s.","100 % ; Il est garanti que tous les \xe9tats ont \xe9t\xe9 visit\xe9s."],"correctAnswer":1,"explanation":"La couverture des transitions est de 8/10 = 80 %. Selon le syllabus ISTQB, seule une couverture des transitions valides de 100 % GARANTIT une couverture de 100 % des \xe9tats. \xc9tant de 80 %, chaque \xe9tat a peut-\xeatre \xe9t\xe9 visit\xe9, mais cela NE peut PAS \xeatre garanti.","source":"Generadas (Agile/Metrics)"},{"id":268,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Lequel des \xe9l\xe9ments suivants est une caract\xe9ristique des techniques de test bas\xe9es sur l\u2019exp\xe9rience\xa0?  ","options":["A) Les cas de test sont cr\xe9\xe9s sur la base d\'informations de conception d\xe9taill\xe9es","B) Les \xe9l\xe9ments test\xe9s dans la section du code d\'interface sont utilis\xe9s pour mesurer la couverture","C) Les techniques de test d\xe9pendent en grande partie de la connaissance du logiciel et du domaine m\xe9tier du testeur.","D) Les cas de test sont utilis\xe9s pour identifier les \xe9carts par rapport aux exigences"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#19, LO : FL-4.1.1). Justification\xa0: Les techniques de test d\xe9pendent en grande partie de la connaissance du logiciel et du domaine m\xe9tier par le testeur.","source":"Official Sample Exam A Q#19"},{"id":269,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous testez un formulaire de recherche d\'appartement simplifi\xe9 qui ne comporte que deux crit\xe8res de recherche : \u2022 \xe9tage (avec trois options possibles : rez-de-chauss\xe9e ; premier \xe9tage ; deuxi\xe8me \xe9tage ou sup\xe9rieur) \u2022 type de jardin (avec trois options possibles : pas de jardin ; petit jardin ; grand jardin) Tous les appartements du rez-de-chauss\xe9e ont un jardin, les appartements des \xe9tages n\'en ont pas. Le formulaire dispose d\'un m\xe9canisme de validation int\xe9gr\xe9 qui ne vous permettra pas d\'utiliser des crit\xe8res de recherche qui enfreignent cette r\xe8gle. Chaque test comporte deux valeurs d\'entr\xe9e\xa0: le type de sol et le type de jardin. Vous souhaitez appliquer un cloisonnement d\'\xe9quivalence (EP) pour couvrir chaque \xe9tage et chaque type de jardin dans vos tests. Quel est le nombre minimum de cas de test pour obtenir une couverture EP \xe0 100\xa0% pour les partitions valides\xa0?  ","options":["A)3","B)4","C)5","D)6"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#20, LO : FL-4.2.1). Justification : 4","source":"Official Sample Exam A Q#20"},{"id":271,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Votre magasin de location de v\xe9los \xe0 la journ\xe9e pr\xe9f\xe9r\xe9 vient de pr\xe9senter un nouveau syst\xe8me de gestion de la relation client (CRM) et vous a demand\xe9, en tant que l\'un de ses membres les plus fid\xe8les, de l\'essayer. Les fonctionnalit\xe9s mises en place sont les suivantes : \u2022 Tout le monde peut louer un v\xe9lo, mais les membres b\xe9n\xe9ficient d\'une r\xe9duction de 20 %. \u2022 Toutefois, si la date limite de retour est d\xe9pass\xe9e, la r\xe9duction n\'est plus disponible. \u2022 Apr\xe8s 15 locations, les membres re\xe7oivent un cadeau : un t-shirt. La table de d\xe9cision d\xe9crivant les fonctionnalit\xe9s mises en \u0153uvre ressemble \xe0 ceci : Conditions R1 R2 R3 R4 R5 R6 R7 R8 \xcatre membre T T T T F F F F D\xe9lai non respect\xe9 T F T F T F F T 15\xe8me location F F T T F F T T Actions Remise de 20 % X  ","options":["A)R4","B)R2","C)R6","D) R8"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#22, LO : FL-4.2.3). Justification : R8","source":"Official Sample Exam A Q#22"},{"id":272,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Testez un syst\xe8me dont le cycle de vie est mod\xe9lis\xe9 par le diagramme de transition d\'\xe9tat pr\xe9sent\xe9 ci-dessous. Le syst\xe8me d\xe9marre \xe0 l\'\xe9tat INIT et termine son fonctionnement \xe0 l\'\xe9tat OFF. Quel est le nombre MINIMUM de cas de test pour obtenir une couverture de transition valide\xa0?  ","options":["A)4","B)2","C)7","D)3"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#23, LO : FL-4.2.4). Justification : 3","source":"Official Sample Exam A Q#23"},{"id":273,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Leur suite de tests a atteint une couverture de phrases \xe0 100\xa0%. Quelle est la cons\xe9quence de ce fait ?  ","options":["A) Chaque instruction du code contenant un d\xe9faut a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois","B) Toute suite de tests contenant plus de cas de test que votre suite de tests atteindra \xe9galement une couverture des d\xe9clarations \xe0 100 %","C) Chaque route du code a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois","D) Chaque combinaison de valeurs d\'entr\xe9e a \xe9t\xe9 test\xe9e au moins une fois"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#24, LO : FL-4.3.1). Justification\xa0: chaque instruction du code contenant un d\xe9faut a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois.","source":"Official Sample Exam A Q#24"},{"id":274,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes n\u2019est PAS vraie pour les tests en bo\xeete blanche\xa0?  ","options":["A) Lors des tests en bo\xeete blanche, l\'ensemble de la mise en \u0153uvre du logiciel est pris en compte","B) Les m\xe9triques de couverture en bo\xeete blanche peuvent aider \xe0 identifier des tests suppl\xe9mentaires pour augmenter la couverture du code","C) Les techniques de test en bo\xeete blanche peuvent \xeatre utilis\xe9es dans les tests statiques","D) Les tests en bo\xeete blanche peuvent aider \xe0 identifier les lacunes dans la mise en \u0153uvre des exigences"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#25, LO : FL-4.3.3). Justification\xa0: les tests en bo\xeete blanche peuvent aider \xe0 identifier les lacunes dans la mise en \u0153uvre des exigences.","source":"Official Sample Exam A Q#25"},{"id":275,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Lequel des \xe9nonc\xe9s suivants d\xe9crit le MIEUX le concept derri\xe8re la supposition d\u2019erreur\xa0?  ","options":["A) La pr\xe9diction des bogues implique d\'utiliser vos connaissances et votre exp\xe9rience sur les d\xe9fauts trouv\xe9s dans le pass\xe9 et les erreurs typiques commises par les d\xe9veloppeurs.","B) La pr\xe9diction des bugs implique d\'utiliser votre exp\xe9rience de d\xe9veloppement personnel et les erreurs que vous avez commises en tant que d\xe9veloppeur","C) La pr\xe9diction des erreurs vous oblige \xe0 imaginer que vous \xeates l\'utilisateur de l\'objet de test et \xe0 deviner les erreurs que l\'utilisateur pourrait commettre en interagissant avec lui.","D) La pr\xe9diction des bogues vous oblige \xe0 dupliquer rapidement la t\xe2che de d\xe9veloppement pour identifier le type de bogues qu\'un d\xe9veloppeur pourrait cr\xe9er."],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#26, LO : FL-4.4.1). Justification\xa0:\xa0La pr\xe9diction des bogues implique d\'utiliser vos connaissances et votre exp\xe9rience sur les d\xe9fauts d\xe9tect\xe9s dans le pass\xe9 et les erreurs typiques commises par les d\xe9veloppeurs.","source":"Official Sample Exam A Q#26"},{"id":276,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"A commenc\xe9 tardivement mais poss\xe8de une connaissance tr\xe8s d\xe9taill\xe9e du domaine et de bonnes comp\xe9tences analytiques. La liste compl\xe8te des exigences n\'a pas encore \xe9t\xe9 partag\xe9e avec l\'\xe9quipe, mais la direction demande que certains r\xe9sultats de tests soient soumis. Quelle technique de test convient le mieux \xe0 cette situation\xa0?  ","options":["A) Tests bas\xe9s sur des listes de contr\xf4le","B) Pr\xe9diction des erreurs","C) Tests exploratoires","D) Tests de branche"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#27, LO : FL-4.4.2). Justification\xa0: tests exploratoires","source":"Official Sample Exam A Q#27"},{"id":277,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Lequel des \xe9nonc\xe9s suivants d\xe9crit le MIEUX comment les crit\xe8res d\u2019acceptation peuvent \xeatre document\xe9s\xa0?  ","options":["A) R\xe9aliser des r\xe9trospectives pour d\xe9terminer les besoins r\xe9els des parties prenantes concernant une user story donn\xe9e","B) Utiliser le format donn\xe9/quand/alors pour d\xe9crire un exemple de condition de test li\xe9e \xe0 une user story donn\xe9e","C) Utiliser la communication verbale pour r\xe9duire le risque que d\'autres personnes comprennent mal les crit\xe8res d\'acceptation","D) Documenter les risques li\xe9s \xe0 une user story donn\xe9e dans un plan de test pour faciliter les tests bas\xe9s sur les risques d\'une user story donn\xe9e"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#28, LO : FL-4.5.2). Justification\xa0: Utiliser le format donn\xe9/quand/alors pour d\xe9crire un exemple de condition de test li\xe9e \xe0 une user story donn\xe9e","source":"Official Sample Exam A Q#28"},{"id":278,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Consid\xe9rez l\'histoire d\'utilisateur suivante\xa0: En tant qu\'\xe9diteur, je souhaite v\xe9rifier le contenu avant sa publication pour m\'assurer que la grammaire est correcte et ses crit\xe8res d\'acceptation\xa0: \u2022 L\'utilisateur peut se connecter au syst\xe8me de gestion de contenu avec le r\xf4le d\'\xab \xc9diteur \xbb \u2022 L\'\xe9diteur peut afficher les pages de contenu existantes \u2022 L\'\xe9diteur peut modifier le contenu de la page \u2022 L\'\xe9diteur peut ajouter des commentaires de balisage \u2022 L\'\xe9diteur peut enregistrer les modifications \u2022 L\'\xe9diteur peut r\xe9affecter le r\xf4le de \xab propri\xe9taire de contenu \xbb pour effectuer des mises \xe0 jour. Lequel des \xe9l\xe9ments suivants est le MEILLEUR exemple de test ATDD pour cela histoire d\'utilisateur ?  ","options":["A) Testez si l\'\xe9diteur peut enregistrer le document apr\xe8s avoir modifi\xe9 le contenu de la page","B) Testez si le propri\xe9taire du contenu peut se connecter et effectuer des mises \xe0 jour du contenu","C) Testez si l\'\xe9diteur peut planifier la publication du contenu \xe9dit\xe9","D) Testez si l\'\xe9diteur peut se r\xe9affecter \xe0 un autre \xe9diteur pour effectuer des mises \xe0 jour"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#29, LO : FL-4.5.3). Justification\xa0:\xa0tester si l\'\xe9diteur peut enregistrer le document apr\xe8s avoir modifi\xe9 le contenu de la page","source":"Official Sample Exam A Q#29"},{"id":306,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX la diff\xe9rence entre les tests par table de d\xe9cision et les tests des branches ?  ","options":["A) Dans les tests par table de d\xe9cision, les cas de test sont d\xe9riv\xe9s des instructions de d\xe9cision du code. Dans les tests des branches, ils sont d\xe9riv\xe9s de la connaissance du flux de contr\xf4le de l\'objet de test.","B) Dans les tests par table de d\xe9cision, les cas de test sont d\xe9riv\xe9s de la sp\xe9cification d\xe9crivant la logique m\xe9tier. Dans les tests des branches, ils reposent sur l\'anticipation de d\xe9fauts possibles dans le code source.","C) Dans les tests par table de d\xe9cision, les cas de test sont d\xe9riv\xe9s de la connaissance du flux de contr\xf4le de l\'objet de test. Dans les tests des branches, ils sont d\xe9riv\xe9s de la sp\xe9cification d\xe9crivant la logique m\xe9tier.","D) Dans les tests par table de d\xe9cision, les cas de test sont ind\xe9pendants de la mani\xe8re dont le logiciel est impl\xe9ment\xe9. Dans les tests des branches, ils ne peuvent \xeatre cr\xe9\xe9s qu\'apr\xe8s la conception ou l\'impl\xe9mentation du code."],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#19, LO : FL-4.1.1). Justification : Les tables de d\xe9cision sont ind\xe9pendantes de l\'impl\xe9mentation (bo\xeete noire), tandis que les tests des branches n\xe9cessitent de conna\xeetre le code (bo\xeete blanche).","source":"Official Sample Exam B Q#19"},{"id":307,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Les clients de la cha\xeene de lavage de voitures TestWash ont des cartes avec le nombre de lavages achet\xe9s. La valeur initiale est 0. En entrant dans le lavage, le syst\xe8me incr\xe9mente le num\xe9ro sur la carte de un. Cette valeur repr\xe9sente le num\xe9ro du lavage actuel. \xc0 partir de ce num\xe9ro, le syst\xe8me d\xe9cide la remise : chaque dixi\xe8me lavage donne 10 % de remise et chaque vingti\xe8me lavage donne 40 % suppl\xe9mentaires (soit 50 % au total). Lequel des ensembles de donn\xe9es d\'entr\xe9e suivants (les num\xe9ros du lavage actuel) atteint la plus grande couverture de partitions d\'\xe9quivalence ?  ","options":["A) 19, 20, 30","B) 11, 12, 20","C) 1, 10, 50","D) 10, 29, 30, 31"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#20, LO : FL-4.2.1). Justification : Les partitions sont : sans remise (non multiple de 10), 10 % (multiple de 10 mais pas de 20) et 50 % (multiple de 20). 19 (sans remise), 20 (50 %) et 30 (10 %) couvrent 3 partitions distinctes.","source":"Official Sample Exam B Q#20"},{"id":308,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous testez un formulaire qui v\xe9rifie si la longueur du mot de passe saisi est correcte. Le formulaire accepte les mots de passe de longueur correcte et rejette ceux qui sont trop courts ou trop longs. La longueur est correcte si elle est comprise entre 6 et 12 caract\xe8res inclus. Le formulaire est initialement vide (longueur = 0). Vous appliquez l\'analyse des valeurs limites \xe0 la variable \'longueur du mot de passe\'. Votre ensemble de cas de test atteint 100 % de couverture des valeurs limites \xe0 2 valeurs. L\'\xe9quipe d\xe9cide que, en raison du risque \xe9lev\xe9 du composant, il faut ajouter des cas pour atteindre 100 % de couverture des valeurs limites \xe0 3 valeurs. Quelles longueurs de mot de passe suppl\xe9mentaires faut-il tester ?  ","options":["A) 4, 5, 13, 14","B) 7, 11","C) 1, 5, 13","D) 1, 4, 7, 11, 14"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#21, LO : FL-4.2.2). Justification : Avec 2 valeurs nous avons d\xe9j\xe0 0, 6, 12 et une valeur au-dessus de la plage sup\xe9rieure. Avec 3 valeurs nous avons aussi besoin des voisins : 5, 7, 11, 13 et la valeur 1 pour la limite inf\xe9rieure gauche.","source":"Official Sample Exam B Q#21"},{"id":310,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un syst\xe8me de stockage peut contenir jusqu\'\xe0 trois \xe9l\xe9ments et est mod\xe9lis\xe9 par le diagramme de transition d\'\xe9tats suivant. La variable N repr\xe9sente le nombre d\'\xe9l\xe9ments actuellement stock\xe9s. Lequel des cas de test suivants, repr\xe9sent\xe9s comme des s\xe9quences d\'\xe9v\xe9nements, atteint le plus haut niveau de couverture des transitions valides ?  ","options":["A) Ajouter, Supprimer, Ajouter, Ajouter, Ajouter","B) Ajouter, Ajouter, Ajouter, Ajouter, Supprimer, Supprimer","C) Ajouter, Ajouter, Ajouter, Supprimer, Supprimer","D) Ajouter, Ajouter, Ajouter, Supprimer, Ajouter"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#23, LO : FL-4.2.4). Justification : La s\xe9quence Ajouter x3, Supprimer x2 parcourt toutes les transitions valides du diagramme d\'\xe9tats.","source":"Official Sample Exam B Q#23"},{"id":311,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous ex\xe9cutez deux cas de test, T1 et T2, sur le m\xeame code. T1 atteint 40 % de couverture des instructions et T2 atteint 65 %. Laquelle des affirmations suivantes est n\xe9cessairement vraie ?  ","options":["A) L\'ensemble de tests T1+T2 atteint 105 % de couverture des instructions","B) Il existe au moins une instruction qui a \xe9t\xe9 ex\xe9cut\xe9e \xe0 la fois par T1 et T2","C) Au moins 5 % des instructions du code test\xe9 ne sont pas ex\xe9cutables","D) L\'ensemble de tests T1+T2 atteint une couverture totale des branches"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#24, LO : FL-4.3.1). Justification : Si T1 couvre 40 % et T2 65 %, et que la couverture totale ne peut d\xe9passer 100 %, il existe n\xe9cessairement un chevauchement : les deux ont ex\xe9cut\xe9 au moins une instruction commune.","source":"Official Sample Exam B Q#24"},{"id":312,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"La m\xe9trique de couverture des branches est d\xe9finie comme : BCov = (X / Y) x 100 %. Que repr\xe9sentent X et Y dans cette formule ?  ","options":["A) X = nombre de r\xe9sultats de d\xe9cision exerc\xe9s par les cas de test. Y = nombre total de r\xe9sultats de d\xe9cision dans le code","B) X = nombre de branches conditionnelles exerc\xe9es par les cas de test. Y = nombre total de branches dans le code","C) X = nombre de branches exerc\xe9es par les cas de test. Y = nombre total de branches dans le code","D) X = nombre de branches conditionnelles exerc\xe9es par les cas de test. Y = nombre total de r\xe9sultats de d\xe9cision dans le code"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#25, LO : FL-4.3.2). Justification : X est le nombre de branches exerc\xe9es et Y le nombre total de branches dans le code.","source":"Official Sample Exam B Q#25"},{"id":313,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Lesquelles DEUX des affirmations suivantes fournissent la MEILLEURE justification pour utiliser les tests exploratoires ?  ","options":["A) Les testeurs ne disposent pas de suffisamment de temps pour la conception et l\'ex\xe9cution des tests","B) La strat\xe9gie de test existante exige que les testeurs utilisent des techniques formelles de bo\xeete noire","C) La sp\xe9cification est \xe9crite dans un langage formel qui peut \xeatre trait\xe9 par un outil","D) Les testeurs sont membres d\'une \xe9quipe agile et ont de bonnes comp\xe9tences en programmation","E) Les testeurs ont une exp\xe9rience du domaine m\xe9tier et de bonnes comp\xe9tences analytiques"],"correctAnswer":0,"explanation":"Les options A) et E) sont les bonnes r\xe9ponses selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#26, LO : FL-4.4.2). Justification : Les tests exploratoires sont id\xe9aux quand il y a peu de temps pour la conception formelle (A) et quand le testeur a une exp\xe9rience du domaine (E).","source":"Official Sample Exam B Q#26"},{"id":314,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des options suivantes convient le MIEUX comme \xe9l\xe9ment d\'une liste de v\xe9rification (checklist) dans les tests bas\xe9s sur une checklist ?  ","options":["A) \xab Le d\xe9veloppeur a commis une erreur en impl\xe9mentant le code \xbb","B) \xab La couverture des instructions atteinte d\xe9passe 85 % \xbb","C) \xab Le programme fonctionne correctement par rapport aux exigences fonctionnelles et non fonctionnelles \xbb","D) \xab Les messages d\'erreur sont \xe9crits dans un langage compr\xe9hensible pour l\'utilisateur \xbb"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#27, LO : FL-4.4.3). Justification : Les \xe9l\xe9ments d\'une checklist doivent \xeatre v\xe9rifiables par observation, comme v\xe9rifier si les messages sont compr\xe9hensibles pour l\'utilisateur.","source":"Official Sample Exam B Q#27"},{"id":315,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Consid\xe9rez le crit\xe8re d\'acceptation suivant pour une user story \xe9crite du point de vue du propri\xe9taire d\'une boutique en ligne. \xc9TANT DONN\xc9 que l\'utilisateur est connect\xe9 et se trouve sur la page d\'accueil, QUAND l\'utilisateur clique sur le bouton \'Ajouter un article\', ALORS le formulaire \'Cr\xe9er un article\' doit appara\xeetre, ET l\'utilisateur doit pouvoir saisir un nom et un prix pour le nouvel article. Dans quel format ce crit\xe8re d\'acceptation est-il \xe9crit ?  ","options":["A) Orient\xe9 r\xe8gles","B) Orient\xe9 sc\xe9narios","C) Orient\xe9 produit","D) Orient\xe9 processus"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#28, LO : FL-4.5.2). Justification : Le format \xc9TANT DONN\xc9/QUAND/ALORS (Given/When/Then) est le format orient\xe9 sc\xe9narios, typique du BDD.","source":"Official Sample Exam B Q#28"},{"id":316,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Votre \xe9quipe analyse la user story suivante pour d\xe9finir les crit\xe8res d\'acceptation : \xab En tant que client enregistr\xe9, je veux pouvoir voir mes commandes pr\xe9c\xe9dentes sur le site de l\'entreprise, afin de pouvoir suivre mes achats. \xbb Lequel des cas de test suivants ne sera PAS pertinent pour cette user story ?  ","options":["A) Entr\xe9e : le client se connecte et clique sur \'voir l\'historique des commandes\'. R\xe9sultat attendu : le syst\xe8me affiche une liste de toutes les commandes pr\xe9c\xe9dentes avec la date, le num\xe9ro de commande et le co\xfbt total","B) Entr\xe9e : le client clique sur une commande de la liste. R\xe9sultat attendu : le syst\xe8me affiche les articles individuels achet\xe9s avec leurs prix et quantit\xe9s","C) Entr\xe9e : le client clique sur \'Trier par ordre croissant\' sur l\'\xe9cran d\'historique des commandes. R\xe9sultat attendu : le syst\xe8me affiche l\'historique tri\xe9 par num\xe9ro de commande dans l\'ordre croissant","D) Entr\xe9e : un client non enregistr\xe9 s\'inscrit comme nouveau client avec un email valide qui n\'existe pas dans la base de donn\xe9es. R\xe9sultat attendu : le syst\xe8me accepte l\'inscription et cr\xe9e le compte"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#29, LO : FL-4.5.3). Justification : La user story concerne la consultation des commandes pr\xe9c\xe9dentes (client d\xe9j\xe0 enregistr\xe9), pas le processus d\'inscription de nouveaux clients.","source":"Official Sample Exam B Q#29"},{"id":342,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Quelle est la diff\xe9rence PRINCIPALE entre les techniques de test en bo\xeete noire et les techniques bas\xe9es sur l\'exp\xe9rience ?  ","options":["A) Les techniques en bo\xeete noire utilisent des mod\xe8les formels ; les techniques bas\xe9es sur l\'exp\xe9rience utilisent les connaissances des testeurs","B) Les techniques en bo\xeete noire utilisent la sp\xe9cification du syst\xe8me ; les techniques bas\xe9es sur l\'exp\xe9rience utilisent les connaissances et l\'intuition des testeurs","C) Les techniques en bo\xeete noire sont d\xe9riv\xe9es du code ; les techniques bas\xe9es sur l\'exp\xe9rience sont d\xe9riv\xe9es de la sp\xe9cification","D) Les techniques en bo\xeete noire incluent les tests exploratoires ; les techniques bas\xe9es sur l\'exp\xe9rience incluent le partitionnement d\'\xe9quivalence"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#18, LO : FL-4.1.1). Justification : Les techniques en bo\xeete noire reposent sur la sp\xe9cification du syst\xe8me ; celles bas\xe9es sur l\'exp\xe9rience reposent sur les connaissances et l\'intuition du testeur.","source":"Official Sample Exam C Q#19"},{"id":343,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous testez un validateur de PIN qui accepte les PIN valides et rejette les invalides. Un PIN est une s\xe9quence de 4 chiffres o\xf9 chaque chiffre est entre 0 et 9. Vous appliquez le partitionnement d\'\xe9quivalence au champ \'nombre de chiffres du PIN\'. Combien y a-t-il de partitions au total (y compris valides et invalides) ?  ","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#19, LO : FL-4.2.1). Justification : Il y a 3 partitions : longueur inf\xe9rieure \xe0 4 (invalide), exactement 4 chiffres (valide) et plus de 4 chiffres (invalide).","source":"Official Sample Exam C Q#20"},{"id":344,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"On a demand\xe9 \xe0 un d\xe9veloppeur d\'impl\xe9menter la r\xe8gle m\xe9tier suivante : ENTR\xc9E : valeur (entier). SI (valeur > 0) ET (valeur <= 10) -> Action A. SI (valeur > 10) ET (valeur <= 20) -> Action B. SI (valeur > 20) -> Action C. Combien de cas de test sont n\xe9cessaires au minimum pour atteindre 100 % de couverture des branches ?  ","options":["A) 2","B) 3","C) 4","D) 6"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#20, LO : FL-4.2.2). Justification : 4 cas de test sont n\xe9cessaires pour couvrir toutes les branches : une valeur <=0 (aucune condition), une dans 1-10 (Action A), une dans 11-20 (Action B) et une >20 (Action C).","source":"Official Sample Exam C Q#21"},{"id":345,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous travaillez sur un projet de d\xe9veloppement d\'un syst\xe8me d\'analyse des r\xe9sultats d\'examens de conduite. On vous a demand\xe9 de concevoir des cas de test en utilisant les tests par table de d\xe9cision pour la r\xe8gle suivante : Un candidat R\xc9USSIT s\'il obtient au moins 43 r\xe9ponses correctes sur 50 ET ne commet aucune faute grave. Un candidat \xc9CHOUE dans tout autre cas. Combien de r\xe8gles (colonnes) la table de d\xe9cision compl\xe8te aura-t-elle ?  ","options":["A) 2","B) 3","C) 4","D) 6"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#21, LO : FL-4.2.3). Justification : Il y a 2 conditions avec 2 valeurs chacune (>=43/non, sans faute grave/avec faute grave), ce qui donne 4 combinaisons (r\xe8gles).","source":"Official Sample Exam C Q#22"},{"id":346,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous concevez des cas de test \xe0 partir d\'un diagramme de transition d\'\xe9tats. Quel est le nombre MINIMUM de cas de test n\xe9cessaires pour atteindre la couverture de toutes les transitions valides (100 %) ?  ","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#23, LO : FL-4.2.4). Justification : Le nombre minimum de cas de test pour la couverture des transitions valides d\xe9pend du diagramme ; dans ce cas, 3 cas couvrent toutes les transitions.","source":"Official Sample Exam C Q#23"},{"id":347,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous voulez appliquer les tests des branches au code repr\xe9sent\xe9 par le graphe de flux de contr\xf4le suivant. Combien de cas de test sont n\xe9cessaires au MINIMUM pour atteindre 100 % de couverture des branches ?  ","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#25, LO : FL-4.3.2). Justification : Pour le graphe de flux de contr\xf4le donn\xe9, 2 cas de test sont n\xe9cessaires pour couvrir toutes les branches (TRUE et FALSE de chaque d\xe9cision).","source":"Official Sample Exam C Q#24"},{"id":348,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Comment les tests en bo\xeete blanche peuvent-ils \xeatre utiles comme support aux tests en bo\xeete noire ?  ","options":["A) Ils peuvent \xeatre utilis\xe9s pour v\xe9rifier que toutes les exigences sont impl\xe9ment\xe9es dans le code","B) Ils peuvent \xeatre utilis\xe9s pour cr\xe9er des cas de test qui couvrent le code que les cas en bo\xeete noire n\'ex\xe9cutent pas","C) Ils peuvent \xeatre utilis\xe9s pour \xe9valuer si la sp\xe9cification refl\xe8te correctement la logique m\xe9tier du syst\xe8me","D) Ils peuvent \xeatre utilis\xe9s pour \xe9viter de cr\xe9er des cas de test redondants avec ceux de la bo\xeete noire"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#26, LO : FL-4.3.2). Justification : Les tests en bo\xeete blanche peuvent identifier et couvrir le code que les cas en bo\xeete noire n\'exercent pas, compl\xe9tant ainsi la couverture.","source":"Official Sample Exam C Q#25"},{"id":349,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Consid\xe9rez la liste suivante de d\xe9fauts possibles : - Entr\xe9e correcte non accept\xe9e - Entr\xe9e incorrecte accept\xe9e - Sortie incorrecte produite - Fonctionnalit\xe9 omise. Laquelle des techniques de test suivantes est SP\xc9CIFIQUEMENT con\xe7ue pour d\xe9tecter tous ces types de d\xe9fauts ?  ","options":["A) Partitionnement d\'\xe9quivalence","B) Tests par table de d\xe9cision","C) Tests de transition d\'\xe9tats","D) Analyse des valeurs limites"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#27, LO : FL-4.4.1). Justification : Le partitionnement d\'\xe9quivalence est sp\xe9cifiquement con\xe7u pour d\xe9tecter ces types de d\xe9fauts en testant des valeurs repr\xe9sentatives de chaque partition.","source":"Official Sample Exam C Q#26"},{"id":350,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des options suivantes d\xe9crit le MIEUX comment l\'utilisation des tests bas\xe9s sur une checklist peut aboutir \xe0 une plus grande couverture par rapport aux tests bas\xe9s sur la sp\xe9cification sans checklist ?  ","options":["A) Les checklists incluent des \xe9l\xe9ments bas\xe9s sur l\'exp\xe9rience des d\xe9fauts pass\xe9s, ce qui aide \xe0 d\xe9tecter plus de d\xe9fauts","B) Les checklists sont des documents formels g\xe9n\xe9r\xe9s automatiquement par des outils d\'analyse statique","C) Les checklists permettent au testeur de couvrir plus de conditions de test sans besoin de sp\xe9cification","D) Les checklists garantissent 100 % de couverture des branches du code"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#28, LO : FL-4.4.3). Justification : Les checklists int\xe8grent l\'exp\xe9rience de projets pass\xe9s, ce qui permet de d\xe9tecter des d\xe9fauts que les sp\xe9cifications formelles ne couvrent pas explicitement.","source":"Official Sample Exam C Q#27"},{"id":351,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Lequel des \xe9l\xe9ments suivants fournit le MEILLEUR exemple de crit\xe8re d\'acceptation orient\xe9 sc\xe9nario ?  ","options":["A) Le syst\xe8me doit afficher un message d\'erreur si le nom d\'utilisateur d\xe9passe 50 caract\xe8res","B) \xc9TANT DONN\xc9 qu\'un client est connect\xe9, QUAND il clique sur \'Passer la commande\', ALORS le syst\xe8me affiche une confirmation de commande","C) Le temps de r\xe9ponse du syst\xe8me ne doit pas d\xe9passer 2 secondes pour 95 % des requ\xeates","D) Le champ mot de passe doit accepter entre 8 et 20 caract\xe8res alphanum\xe9riques"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#29, LO : FL-4.5.2). Justification : Le format \xc9TANT DONN\xc9/QUAND/ALORS (Given/When/Then) est le format orient\xe9 sc\xe9narios typique du BDD.","source":"Official Sample Exam C Q#28"},{"id":352,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous utilisez le d\xe9veloppement pilot\xe9 par les tests d\'acceptation (ATDD) et concevez des cas de test \xe0 partir de la user story suivante : \xab En tant qu\'utilisateur enregistr\xe9, je veux pouvoir changer mon mot de passe, pour garder mon compte s\xe9curis\xe9. \xbb Lequel des cas de test suivants n\'est PAS pertinent pour cette user story ?  ","options":["A) V\xe9rifier que l\'utilisateur peut changer son mot de passe en saisissant le mot de passe actuel correct et un nouveau mot de passe valide","B) V\xe9rifier que le syst\xe8me rejette le changement si le mot de passe actuel saisi est incorrect","C) V\xe9rifier que le syst\xe8me envoie un email de confirmation \xe0 l\'utilisateur apr\xe8s le changement de mot de passe","D) V\xe9rifier qu\'un utilisateur non enregistr\xe9 peut r\xe9initialiser son mot de passe via le lien \'mot de passe oubli\xe9\'"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon C, Q#30, LO : FL-4.5.3). Justification : La user story concerne le changement de mot de passe d\'un utilisateur D\xc9J\xc0 enregistr\xe9, pas la r\xe9initialisation de mot de passe pour des utilisateurs non enregistr\xe9s.","source":"Official Sample Exam C Q#29"},{"id":377,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous r\xe9alisez des tests syst\xe8me d\'une application web d\'e-commerce et on vous fournit l\'exigence suivante : REQ 05-017. Si le co\xfbt total des achats d\xe9passe 100 $, le client obtient une remise de 5 % sur les achats suivants. Sinon, le client ne re\xe7oit aucune remise. Quelles techniques de test seront les PLUS utiles pour concevoir des cas de test \xe0 partir de cette exigence ?  ","options":["A) Techniques de test en bo\xeete blanche","B) Techniques de test en bo\xeete noire","C) Techniques bas\xe9es sur l\'exp\xe9rience","D) Techniques de test bas\xe9es sur les risques"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#19, LO : FL-4.1.1). Justification : Techniques de test en bo\xeete noire (l\'exigence d\xe9crit un comportement observable de l\'ext\xe9rieur, ind\xe9pendant du code).","source":"Official Sample Exam D Q#19"},{"id":378,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Le syst\xe8me de vente de billets de cin\xe9ma calcule le type de remise \xe0 partir de l\'ann\xe9e de naissance (AN) du client et de l\'ann\xe9e actuelle (AA) comme suit : Soit D la diff\xe9rence entre AA et AN, c\'est-\xe0-dire D = AA - AN. - Si D < 0, afficher l\'erreur \xab l\'ann\xe9e de naissance ne peut pas \xeatre sup\xe9rieure \xe0 l\'ann\xe9e actuelle \xbb. - Si 0 <= D < 18, appliquer la remise \xe9tudiant. - Si 18 <= D < 65, n\'appliquer aucune remise. - Si D >= 65, appliquer la remise retrait\xe9. Votre ensemble de tests contient d\xe9j\xe0 deux cas : - AN = 1990, AA = 2020, r\xe9sultat attendu : aucune remise. - AN = 2030, AA = 2029, r\xe9sultat attendu : afficher l\'erreur. Lequel des ensembles de donn\xe9es de test suivants faut-il ajouter pour atteindre une couverture compl\xe8te des partitions d\'\xe9quivalence valides pour le type de remise ?  ","options":["A) AN = 2001, AA = 2065","B) AN = 1900, AA = 1965","C) AN = 1965, AA = 1900","D) AN = 2011, AA = 2029","E) AN = 2000, AA = 2000"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#20, LO : FL-4.2.1). Justification : AN = 1900, AA = 1965 donne D = 65, couvrant la partition de la remise retrait\xe9 (D >= 65), qui manquait.","source":"Official Sample Exam D Q#20"},{"id":379,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous testez un syst\xe8me de contr\xf4le de temp\xe9rature pour une installation de stockage frigorifique. Le syst\xe8me re\xe7oit la temp\xe9rature (en degr\xe9s Celsius entiers) en entr\xe9e. Si la temp\xe9rature est entre 0 et 2 degr\xe9s inclus, il affiche \xab temp\xe9rature OK \xbb. Pour des temp\xe9ratures plus basses, il affiche \xab temp\xe9rature trop basse \xbb, et pour des plus hautes \xab temp\xe9rature trop \xe9lev\xe9e \xbb. En utilisant l\'analyse des valeurs limites \xe0 2 valeurs, lequel des ensembles suivants fournit le plus haut niveau de couverture des valeurs limites ?  ","options":["A) -1, 3","B) 0, 2","C) -1, 0, 2, 3","D) -2, 0, 2, 4"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#21, LO : FL-4.2.2). Justification : -1, 0, 2, 3 couvrent les deux limites et leurs voisins imm\xe9diats (AVL \xe0 2 valeurs aux limites 0 et 2).","source":"Official Sample Exam D Q#21"},{"id":380,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous concevez des cas de test \xe0 partir d\'une table de d\xe9cision d\'\xe2ges et d\'exp\xe9rience. Jusqu\'\xe0 pr\xe9sent vous avez con\xe7u 4 cas de test. Lequel des cas de test suivants, ajout\xe9 \xe0 l\'ensemble existant, augmentera la couverture de la table de d\xe9cision ?  ","options":["A) Homme de 66 ans, non enregistr\xe9, sans exp\xe9rience ; r\xe9sultat attendu : cat\xe9gorie B","B) Femme de 55 ans, non enregistr\xe9e, avec 2 ans d\'exp\xe9rience ; r\xe9sultat attendu : cat\xe9gorie A","C) Femme de 19 ans, enregistr\xe9e, avec 5 ans d\'exp\xe9rience ; r\xe9sultat attendu : cat\xe9gorie D","D) Aucun cas suppl\xe9mentaire ne peut augmenter la couverture atteinte"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#22, LO : FL-4.2.3). Justification : Le cas d\'un homme de 66 ans, non enregistr\xe9, sans exp\xe9rience (cat\xe9gorie B) couvre une r\xe8gle pas encore exerc\xe9e par l\'ensemble existant.","source":"Official Sample Exam D Q#22"},{"id":381,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous appliquez les tests de transition d\'\xe9tats \xe0 un syst\xe8me de r\xe9servation de chambres d\'h\xf4tel. En supposant que tous les cas de test commencent dans l\'\xe9tat \xab Demande en cours \xbb (Requesting), lequel des cas de test suivants, repr\xe9sent\xe9s comme des s\xe9quences d\'\xe9v\xe9nements, atteint la plus grande couverture des transitions valides ?  ","options":["A) NotAvailable, Available, ChangeRoom, NotAvailable, Cancel","B) Available, ChangeRoom, NotAvailable, Available, Pay","C) Available, ChangeRoom, Available, ChangeRoom, NotAvailable","D) NotAvailable, Cancel, ChangeRoom, Available, Pay"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#23, LO : FL-4.2.4). Justification : La s\xe9quence Available, ChangeRoom, NotAvailable, Available, Pay parcourt le plus de transitions valides du diagramme.","source":"Official Sample Exam D Q#23"},{"id":382,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Votre ensemble de tests S pour un programme P atteint 100 % de couverture des instructions. Il est compos\xe9 de trois cas de test, chacun atteignant 50 % de couverture des instructions. Laquelle des affirmations suivantes est CORRECTE ?  ","options":["A) Ex\xe9cuter S provoquera toutes les d\xe9faillances possibles dans P","B) S atteint 100 % de couverture des branches pour P","C) Chaque instruction ex\xe9cutable dans P contenant un d\xe9faut a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois pendant l\'ex\xe9cution de S","D) Apr\xe8s avoir retir\xe9 un cas de test de S, les deux restants atteindront encore 100 % de couverture des instructions"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#24, LO : FL-4.3.1). Justification : 100 % de couverture des instructions garantit que chaque instruction ex\xe9cutable (y compris une contenant un d\xe9faut) a \xe9t\xe9 ex\xe9cut\xe9e au moins une fois, m\xeame si cela ne garantit pas que toutes les d\xe9faillances soient d\xe9clench\xe9es.","source":"Official Sample Exam D Q#24"},{"id":383,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Pourquoi les tests en bo\xeete blanche facilitent-ils la d\xe9tection des d\xe9fauts m\xeame lorsque la sp\xe9cification du logiciel est vague, obsol\xe8te ou incompl\xe8te ?  ","options":["A) Les cas de test sont con\xe7us \xe0 partir de la structure de l\'objet de test plut\xf4t que de la sp\xe9cification","B) Pour chaque technique de bo\xeete blanche, la couverture peut \xeatre bien d\xe9finie et facilement mesur\xe9e","C) Les techniques de bo\xeete blanche sont tr\xe8s bien con\xe7ues pour d\xe9tecter les omissions dans les exigences","D) Les techniques de bo\xeete blanche peuvent \xeatre utilis\xe9es dans les tests statiques et dynamiques"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#25, LO : FL-4.3.3). Justification : Les cas de test sont con\xe7us \xe0 partir de la structure de l\'objet de test plut\xf4t que de la sp\xe9cification, ils ne d\xe9pendent donc pas de la qualit\xe9 de la sp\xe9cification.","source":"Official Sample Exam D Q#25"},{"id":384,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des situations suivantes n\'est PAS anticip\xe9e par le testeur lorsqu\'il applique la technique de pr\xe9diction d\'erreurs (error guessing) ?  ","options":["A) Le d\xe9veloppeur a mal compris la formule de la user story pour calculer les int\xe9r\xeats","B) Le d\xe9veloppeur a \xe9crit \'FA = A*(1+IR^N)\' au lieu de \'FA = A*(1+IR)^N\' dans le code","C) Le d\xe9veloppeur a manqu\xe9 le s\xe9minaire sur la nouvelle l\xe9gislation des taux d\'int\xe9r\xeat compos\xe9s","D) La pr\xe9cision des int\xe9r\xeats calcul\xe9s par le syst\xe8me n\'est pas assez exacte"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#26, LO : FL-4.4.1). Justification : La pr\xe9diction d\'erreurs anticipe les d\xe9fauts probables du logiciel, pas des faits organisationnels comme le fait que le d\xe9veloppeur ait manqu\xe9 un s\xe9minaire.","source":"Official Sample Exam D Q#26"},{"id":385,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes est vraie \xe0 propos des tests exploratoires ?  ","options":["A) Les cas de test sont con\xe7us avant le d\xe9but de la session de tests exploratoires","B) Le testeur peut ex\xe9cuter des tests, mais ne peut pas les concevoir","C) Les r\xe9sultats des tests exploratoires sont de bons pr\xe9dicteurs du nombre de d\xe9fauts restants","D) Pendant les tests exploratoires, le testeur peut utiliser des techniques de bo\xeete noire"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#27, LO : FL-4.4.2). Justification : Pendant les tests exploratoires, le testeur peut utiliser des techniques de bo\xeete noire pour guider la conception et l\'ex\xe9cution simultan\xe9es des tests.","source":"Official Sample Exam D Q#27"},{"id":386,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Quelle pratique collaborative pour \xe9crire des user stories permet \xe0 l\'\xe9quipe d\'atteindre une compr\xe9hension collective de ce qui doit \xeatre livr\xe9 ?  ","options":["A) Planning poker, pour parvenir \xe0 un consensus sur l\'effort","B) Revues, pour d\xe9tecter les incoh\xe9rences et contradictions","C) Planification de l\'it\xe9ration, pour prioriser les stories \xe0 plus forte valeur","D) Conversation, pour que les membres de l\'\xe9quipe comprennent comment le logiciel sera utilis\xe9"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#28, LO : FL-4.5.1). Justification : La conversation est la pratique collaborative (le \xab C \xbb des 3 C : Carte, Conversation, Confirmation) qui construit une compr\xe9hension partag\xe9e.","source":"Official Sample Exam D Q#28"},{"id":387,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous concevez des cas de test pour une user story o\xf9 le client veut filtrer les produits par plage de prix. Pr\xe9condition : seuls deux produits sont disponibles, A (100 $) et B (110 $). Quel est le MEILLEUR exemple de cas de test pour cette user story ?  ","options":["A) Aller sur le site et fixer le filtre entre 90 $ et 100 $. R\xe9sultat : affiche seulement A. Changer le maximum \xe0 110 $. R\xe9sultat : affiche A et B.","B) Aller sur le site. Ajouter le produit C au prix de 120 $. Actualiser la page. R\xe9sultat : le prix maximum par d\xe9faut passe \xe0 120 $.","C) Aller sur le site et fixer le filtre entre 90 $ et 115 $. R\xe9sultat : affiche A et B. Changer la devise en EUR. R\xe9sultat : le filtre passe \xe0 des valeurs en EUR.","D) Aller sur le site avec Edge, Chrome et Opera. Dans chacun, fixer le filtre entre 90 $ et 110 $. R\xe9sultat : ils affichent A et B avec la m\xeame mise en page partout."],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#29, LO : FL-4.5.3). Justification : Ce cas teste directement le comportement de filtrage d\xe9crit dans la user story en utilisant les valeurs limites de la plage de prix.","source":"Official Sample Exam D Q#29"},{"id":400,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous \xeates testeur d\'un syst\xe8me bancaire. Le champ \xab montant du virement \xbb accepte des valeurs entre 1 euro et 10 000 euros. En appliquant l\'AVL \xe0 3 valeurs par limite, quel ensemble de valeurs de test est correct ?  ","options":["A) 0, 1, 2, 9999, 10000, 10001","B) 1, 10000","C) 0, 1, 5000, 10000, 10001","D) -1, 0, 1, 9999, 10000, 10001"],"correctAnswer":0,"explanation":"L\'AVL \xe0 3 valeurs par limite inclut : en dessous de la limite (0), \xe0 la limite (1), juste \xe0 l\'int\xe9rieur (2) pour la limite inf\xe9rieure ; et juste \xe0 l\'int\xe9rieur (9999), \xe0 la limite (10000), au-dessus (10001) pour la limite sup\xe9rieure.","source":"banco"},{"id":401,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un syst\xe8me de remises applique : 0 % si l\'achat < 100 euros, 5 % si 100 euros <= achat < 500 euros, 10 % si 500 euros <= achat < 1000 euros, 15 % si achat >= 1000 euros. En utilisant le partitionnement d\'\xe9quivalence, combien de classes d\'\xe9quivalence valides existe-t-il ?  ","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":2,"explanation":"Il existe 4 classes d\'\xe9quivalence valides : [0-99 euros], [100-499 euros], [500-999 euros], [>=1000 euros], une pour chaque plage de remise diff\xe9rente.","source":"banco"},{"id":402,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous concevez une table de d\xe9cision pour un syst\xe8me de pr\xeats avec 3 conditions bool\xe9ennes (revenus suffisants, bon historique de cr\xe9dit, garantie fournie). Combien de colonnes de r\xe8gles la table compl\xe8te aura-t-elle ?  ","options":["A) 3","B) 6","C) 8","D) 9"],"correctAnswer":2,"explanation":"Avec 3 conditions bool\xe9ennes (V/F chacune), le nombre de combinaisons possibles est 2^3 = 8 r\xe8gles/colonnes.","source":"banco"},{"id":403,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un distributeur automatique a des \xe9tats : Inactif, En attente du PIN, V\xe9rification, Distribution, Bloqu\xe9. Si vous saisissez 3 PIN incorrects cons\xe9cutifs, la transition va vers \xab Bloqu\xe9 \xbb. Quelle technique de conception de tests est la PLUS appropri\xe9e pour mod\xe9liser et v\xe9rifier ce comportement ?  ","options":["A) Partitionnement d\'\xe9quivalence","B) Valeurs limites","C) Tests de transition d\'\xe9tats","D) Tables de d\xe9cision"],"correctAnswer":2,"explanation":"Les tests de transition d\'\xe9tats mod\xe9lisent le comportement du syst\xe8me lorsqu\'il passe d\'un \xe9tat \xe0 un autre selon des \xe9v\xe9nements ou conditions, id\xe9al pour des syst\xe8mes avec des \xe9tats comme un distributeur ATM.","source":"banco"},{"id":404,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous avez le code suivant : IF (a > 0 AND b > 0) THEN result = a + b ELSE result = 0. Pour atteindre 100 % de couverture des d\xe9cisions, combien de cas de test sont n\xe9cessaires au minimum ?  ","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"Pour 100 % de couverture des d\xe9cisions, vous avez besoin d\'au moins 2 cas : un qui rend la condition vraie (ex. a=1, b=1) et un autre qui la rend fausse (ex. a=-1, b=1).","source":"banco"},{"id":405,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous travaillez sur une application de r\xe9servation de vols. Vous appliquez la m\xe9thode des \xab cas d\'utilisation \xbb pour concevoir des tests. Quel flux DEVEZ-vous tester pour trouver les d\xe9fauts les plus critiques dans le flux de r\xe9servation ?  ","options":["A) Uniquement le flux de base (chemin heureux)","B) Uniquement les flux alternatifs d\'erreur","C) Le flux de base et tous les flux alternatifs et d\'exception","D) Uniquement les flux qui ont la plus grande probabilit\xe9 de se produire"],"correctAnswer":2,"explanation":"Les tests bas\xe9s sur les cas d\'utilisation doivent couvrir le flux de base (happy path) ET tous les flux alternatifs et d\'exception pour garantir une couverture compl\xe8te du comportement sp\xe9cifi\xe9.","source":"banco"},{"id":406,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Pour un module avec 5 conditions ind\xe9pendantes dans une table de d\xe9cision, combien de r\xe8gles la table compl\xe8te aurait-elle, et combien en r\xe9sulteraient d\'un \xab regroupement \xbb (collapse) en supprimant les conditions non pertinentes s\'il n\'y a que 3 actions distinctes ?  ","options":["A) 32 compl\xe8te ; 3 regroup\xe9e","B) 10 compl\xe8te ; 3 regroup\xe9e","C) 32 compl\xe8te ; peut \xeatre moins de 32 une fois regroup\xe9e","D) 16 compl\xe8te ; 3 regroup\xe9e"],"correctAnswer":2,"explanation":"Avec 5 conditions bool\xe9ennes : 2^5 = 32 r\xe8gles compl\xe8tes. Le regroupement r\xe9duit les r\xe8gles en combinant celles o\xf9 une condition est non pertinente (\'don\'t care\'), aboutissant \xe0 moins de 32.","source":"banco"},{"id":422,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un champ de formulaire accepte des valeurs d\'\xe2ge entre 18 et 65 ans. En utilisant le partitionnement d\'\xe9quivalence, combien de classes sont identifi\xe9es (valides + invalides) ?  ","options":["A) 2","B) 3","C) 4","D) 5"],"correctAnswer":1,"explanation":"3 classes sont identifi\xe9es : invalide (<18), valide (18-65), invalide (>65). Il y a 1 classe valide et 2 invalides = 3 classes au total.","source":"banco"},{"id":424,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Analysez l\'organigramme suivant : START -> A -> IF X THEN B ELSE C -> IF Y THEN D ELSE E -> END. Combien de cas de test sont n\xe9cessaires pour atteindre 100 % de couverture des instructions ?  ","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"Pour ex\xe9cuter toutes les instructions (A, B ou C, D ou E), vous avez besoin d\'au moins 2 cas : un avec X=true,Y=true (ex\xe9cute A,B,D) et un autre avec X=false,Y=false (ex\xe9cute A,C,E). Avec 2 cas vous couvrez toutes les instructions.","source":"banco"},{"id":425,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous avez une fonction avec 4 conditions ind\xe9pendantes dans une expression AND : (A AND B AND C AND D). Pour atteindre 100 % de couverture des conditions modifi\xe9es/d\xe9cisions (MC/DC), combien de cas de test sont n\xe9cessaires au minimum ?  ","options":["A) 2","B) 4","C) 5","D) 16"],"correctAnswer":2,"explanation":"Le MC/DC n\xe9cessite N+1 cas de test pour N conditions ind\xe9pendantes. Avec 4 conditions : 4+1=5 cas minimum. Le MC/DC d\xe9montre que chaque condition affecte ind\xe9pendamment le r\xe9sultat.","source":"banco"},{"id":426,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un syst\xe8me de feux de circulation a des \xe9tats : Rouge, Orange_vers_Vert, Vert, Orange_vers_Rouge. La transition Rouge->Orange_vers_Vert se produit apr\xe8s 60 secondes. Combien de transitions valides le diagramme complet du feu a-t-il ?  ","options":["A) 2","B) 3","C) 4","D) 8"],"correctAnswer":2,"explanation":"Le cycle complet a 4 transitions : Rouge->Orange_vers_Vert, Orange_vers_Vert->Vert, Vert->Orange_vers_Rouge, Orange_vers_Rouge->Rouge. Il y a exactement 4 transitions dans le cycle normal.","source":"banco"},{"id":427,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Vous testez une fonction de recherche. D\'apr\xe8s votre exp\xe9rience, vous savez que les recherches avec des caract\xe8res sp\xe9ciaux (%, _, *) provoquent souvent des injections SQL. Quelle technique bas\xe9e sur l\'exp\xe9rience utilisez-vous ?  ","options":["A) Exploration structur\xe9e","B) Pr\xe9diction d\'erreurs (error guessing)","C) Test en bo\xeete blanche","D) Partitionnement d\'\xe9quivalence"],"correctAnswer":1,"explanation":"La pr\xe9diction d\'erreurs (error guessing) est une technique bas\xe9e sur l\'exp\xe9rience o\xf9 le testeur pr\xe9dit o\xf9 les d\xe9fauts sont les plus probables, \xe0 partir de sa connaissance des d\xe9faillances courantes comme l\'injection SQL avec des caract\xe8res sp\xe9ciaux.","source":"banco"},{"id":428,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Pour le code suivant IF (age >= 18 AND pays == \'ES\') THEN acces = true ELSE acces = false, combien de cas de test vous faut-il pour 100 % de couverture des d\xe9cisions ?  ","options":["A) 1","B) 2","C) 3","D) 4"],"correctAnswer":1,"explanation":"La couverture des d\xe9cisions exige que la condition compos\xe9e soit \xe9valu\xe9e comme TRUE et comme FALSE. Vous avez besoin de : cas 1 (age=20, pays=\'ES\' -> true) et cas 2 (age=15, pays=\'ES\' -> false). Minimum 2 cas.","source":"banco"},{"id":439,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"On applique le test par paires (pairwise) \xe0 un syst\xe8me avec 5 param\xe8tres, chacun avec 3 valeurs possibles. Si toutes les combinaisons \xe9taient test\xe9es, cela ferait 3^5=243 cas. \xc0 quoi sert le pairwise ?  ","options":["A) \xc0 tester syst\xe9matiquement toutes les combinaisons possibles","B) \xc0 r\xe9duire le nombre de cas de test en garantissant que chaque paire de valeurs apparaisse au moins une fois","C) \xc0 tester uniquement les valeurs limites de chaque param\xe8tre","D) \xc0 automatiser la g\xe9n\xe9ration de donn\xe9es de test"],"correctAnswer":1,"explanation":"Le test par paires (ou all-pairs) garantit que chaque combinaison de 2 param\xe8tres est test\xe9e au moins une fois, r\xe9duisant drastiquement le nombre de cas (de 243 \xe0 ~25 environ) tout en maintenant une bonne d\xe9tection des d\xe9fauts.","source":"banco"},{"id":445,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des techniques suivantes est de type \xab bo\xeete blanche \xbb ?  ","options":["A) Partitionnement d\'\xe9quivalence","B) Analyse des valeurs limites","C) Couverture des instructions","D) Tables de d\xe9cision"],"correctAnswer":2,"explanation":"Les techniques de bo\xeete blanche (bas\xe9es sur la structure) reposent sur le code interne : couverture des instructions, des branches, des conditions. Les autres options (EP, AVL, tables de d\xe9cision) sont des techniques de bo\xeete noire bas\xe9es sur les sp\xe9cifications.","source":"banco"},{"id":448,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"CAS PRATIQUE : Vous testez un syst\xe8me de r\xe9servation d\'h\xf4tel. Les prix varient selon la saison : Basse (janvier-mars, oct-nov) : 80 euros/nuit ; Moyenne (avril-juin, sep) : 120 euros/nuit ; Haute (juillet-ao\xfbt, d\xe9c) : 200 euros/nuit. En utilisant l\'EP, combien de classes d\'\xe9quivalence valides existe-t-il pour le prix par nuit ?  ","options":["A) 2","B) 3","C) 6","D) 12"],"correctAnswer":1,"explanation":"Il existe 3 classes d\'\xe9quivalence de prix valides : [80 euros - basse saison], [120 euros - moyenne saison], [200 euros - haute saison]. L\'EP regroupe par comportement \xe9quivalent du syst\xe8me, pas par nombre de mois.","source":"banco"},{"id":449,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"CAS PRATIQUE : Syst\xe8me de vote en ligne. Conditions de vote : (1) Citoyen enregistr\xe9, (2) \xc2g\xe9 de plus de 18 ans, (3) N\'a pas d\xe9j\xe0 vot\xe9. Il ne peut voter que s\'il remplit les 3. Concevez la table de d\xe9cision minimale. Combien de r\xe8gles de comportement distinctes (pas de r\xe8gles impossibles) existe-t-il ?  ","options":["A) 2","B) 3","C) 4","D) 8"],"correctAnswer":3,"explanation":"Avec 3 conditions bool\xe9ennes, il y a 2^3=8 combinaisons. Une seule combinaison (V,V,V) permet de voter ; les 7 autres le refusent. Il y a 8 r\xe8gles possibles d\xe9crivant des comportements distincts du syst\xe8me.","source":"banco"},{"id":450,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"CAS PRATIQUE : Tests d\'un feu pi\xe9ton. \xc9tats : ROUGE_PI\xc9TON, VERT_PI\xc9TON, CLIGNOTANT. Transitions : ROUGE->VERT (apr\xe8s 60s), VERT->CLIGNOTANT (apr\xe8s 25s), CLIGNOTANT->ROUGE (apr\xe8s 5s). Quelle couverture 0-switch (toutes les transitions) n\xe9cessite-t-elle au minimum ?  ","options":["A) 1 cas de test","B) 2 cas de test","C) 3 cas de test qui couvrent le cycle complet","D) 6 cas de test, un par transition possible"],"correctAnswer":2,"explanation":"La couverture 0-switch exige que chaque transition valide soit exerc\xe9e au moins une fois. Avec 3 transitions dans un cycle (R->V->C->R), un chemin qui parcourt le cycle complet les couvre toutes. En pratique, plusieurs cas sont utilis\xe9s pour les variantes.","source":"banco"},{"id":457,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"CAS PRATIQUE : Tests d\'un formulaire d\'inscription. Champs : nom (obligatoire), email (format valide), mot de passe (8-20 caract\xe8res, au moins 1 majuscule). En utilisant l\'EP, combien de classes d\'\xe9quivalence existe-t-il UNIQUEMENT pour le champ mot de passe ?  ","options":["A) 2 (valide et invalide)","B) 4 (valide ; invalide par longueur courte ; invalide par longueur longue ; invalide par absence de majuscule)","C) 3 (court, valide, long)","D) 6 (toutes les combinaisons de longueur et de format)"],"correctAnswer":1,"explanation":"Pour le mot de passe : 1) Valide (8-20 caract\xe8res + majuscule), 2) Invalide-court (<8 caract\xe8res), 3) Invalide-long (>20 caract\xe8res), 4) Invalide-sans majuscule (longueur OK mais sans majuscule). Ce sont 4 classes distinctes avec un comportement diff\xe9rent du syst\xe8me.","source":"banco"},{"id":462,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Une sp\xe9cification dit : \xab Si l\'utilisateur est premium ET est membre depuis plus d\'un an, appliquer une remise de 20 % \xbb. Quelle technique de conception de tests est la PLUS directement applicable \xe0 cette r\xe8gle m\xe9tier ?  ","options":["A) Analyse des valeurs limites","B) Tables de d\xe9cision","C) Transition d\'\xe9tats","D) Couverture des instructions"],"correctAnswer":1,"explanation":"Les tables de d\xe9cision sont id\xe9ales pour les r\xe8gles m\xe9tier avec plusieurs conditions et combinaisons (premium : oui/non, anciennet\xe9 : >1 an/<=1 an) qui d\xe9terminent diff\xe9rentes actions (remise ou non).","source":"banco"},{"id":467,"chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Que signifie une \xab couverture des branches \xbb de 100 % ?  ","options":["A) Que toutes les lignes de code ont \xe9t\xe9 test\xe9es","B) Que chaque d\xe9cision dans le code a pris la valeur vraie ET fausse au moins une fois","C) Que toutes les valeurs d\'entr\xe9e possibles ont \xe9t\xe9 test\xe9es","D) Que toutes les fonctions du syst\xe8me ont \xe9t\xe9 ex\xe9cut\xe9es"],"correctAnswer":1,"explanation":"Une couverture des branches (ou d\xe9cisions) de 100 % signifie que chaque r\xe9sultat possible de chaque point de d\xe9cision (if/else, switch) a \xe9t\xe9 ex\xe9cut\xe9 au moins une fois : la branche vraie et la branche fausse de chaque condition.","source":"banco"},{"id":"q_batch2_3dfvl4agj","chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Dans un projet agile, l\'\xe9quipe impl\xe9mente la user story suivante : \xab En tant que client, je veux rechercher des produits par cat\xe9gorie pour trouver rapidement ce dont j\'ai besoin \xbb. Les crit\xe8res d\'acceptation sont : Le syst\xe8me affiche les cat\xe9gories disponibles ; l\'utilisateur peut s\xe9lectionner une cat\xe9gorie ; les produits de la cat\xe9gorie s\xe9lectionn\xe9e sont affich\xe9s ; un message est affich\xe9 s\'il n\'y a pas de produits dans la cat\xe9gorie. Quel est le MEILLEUR exemple de cas de test ATDD pour cette story ?  ","options":["V\xe9rifier que la base de donn\xe9es contient au moins 10 cat\xe9gories","\xc9tant donn\xe9 qu\'il y a des produits dans \'\xc9lectronique\', quand je s\xe9lectionne \'\xc9lectronique\', alors je vois la liste des produits \xe9lectroniques","Tester que le temps de r\xe9ponse est inf\xe9rieur \xe0 2 secondes","V\xe9rifier que le code respecte les standards de codage"],"correctAnswer":1,"explanation":"A. Incorrect. Ce cas se concentre sur des aspects techniques d\'impl\xe9mentation plut\xf4t que sur un comportement visible par l\'utilisateur. B. Correct. Ce cas de test est bas\xe9 sur des crit\xe8res d\'acceptation sp\xe9cifiques (s\xe9lectionner une cat\xe9gorie et afficher les produits), utilise le format typique Given/When/Then, est compr\xe9hensible pour les parties prenantes, et couvre des caract\xe9ristiques sp\xe9cifiques de la user story sans en d\xe9passer le p\xe9rim\xe8tre. C. Incorrect. Bien qu\'importante, la performance n\'est pas couverte par les crit\xe8res d\'acceptation de cette story sp\xe9cifique. D. Incorrect. Les standards de codage sont des aspects techniques, pas des crit\xe8res d\'acceptation visibles par l\'utilisateur.","source":"banco-extra"},{"id":"q_batch2_7kt0gtwqg","chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Une \xe9quipe de d\xe9veloppement a impl\xe9ment\xe9 un nouveau syst\xe8me financier, mais toutes les exigences n\'ont pas \xe9t\xe9 document\xe9es. Le temps pour les tests est limit\xe9 et l\'\xe9quipe a besoin d\'obtenir rapidement des informations sur le comportement du syst\xe8me. Quelle approche de test serait la PLUS appropri\xe9e dans cette situation ?  ","options":["Tests de r\xe9gression","Tests exploratoires","Tests de charge","Tests unitaires"],"correctAnswer":1,"explanation":"A. Incorrect. Les tests de r\xe9gression n\xe9cessitent de comprendre les changements apport\xe9s au syst\xe8me et sont normalement utilis\xe9s lorsqu\'il existe une base de tests \xe9tablie. B. Correct. Les tests exploratoires sont id\xe9aux quand il y a peu de temps et peu de documentation, permettant aux testeurs d\'utiliser leur cr\xe9ativit\xe9 et leurs connaissances pour d\xe9couvrir des d\xe9fauts. C. Incorrect. Les tests de charge se concentrent sur la performance du syst\xe8me dans des conditions sp\xe9cifiques et n\xe9cessitent un ensemble clair d\'exigences de charge. D. Incorrect. Les tests unitaires se concentrent sur les composants individuels du code.","source":"banco-extra"},{"id":"q_batch2_j594nrl15","chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un syst\xe8me de lecteur de musique a les \xe9tats suivants : ARR\xcaT\xc9, EN LECTURE, EN PAUSE. Les transitions valides sont : ARR\xcaT\xc9 -> EN LECTURE (lire), EN LECTURE -> EN PAUSE (mettre en pause), EN PAUSE -> EN LECTURE (reprendre), EN LECTURE -> ARR\xcaT\xc9 (arr\xeater), EN PAUSE -> ARR\xcaT\xc9 (arr\xeater). Quel est le nombre MINIMUM de cas de test pour atteindre 100 % de couverture des transitions valides avec la contrainte que le cas doit commencer et finir dans l\'\xe9tat ARR\xcaT\xc9 ?  ","options":["2","3","4","5"],"correctAnswer":0,"explanation":"A. Correct. Avec 2 cas qui commencent et finissent en ARR\xcaT\xc9, toutes les transitions sont couvertes. Cas 1 : A -> Lecture -> Pause -> A (couvre lire, mettre en pause, arr\xeater depuis Pause). Cas 2 : A -> Lecture -> Pause -> Reprendre -> A (couvre reprendre et arr\xeater depuis Lecture). B. Incorrect. Possible, mais pas minimal. Toutes les transitions peuvent \xeatre couvertes avec 3 cas, mais 2 suffisent d\xe9j\xe0. C. Incorrect. Redondant. On peut aussi y parvenir avec 4 cas, mais c\'est plus que n\xe9cessaire. D. Incorrect. Tr\xe8s inefficace. Cela reviendrait \xe0 couvrir chaque transition s\xe9par\xe9ment, totalement redondant.","source":"banco-extra"},{"id":"q_batch2_sho8tyfr5","chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes sur la pr\xe9diction d\'erreurs est la plus pr\xe9cise ?  ","options":["La pr\xe9diction d\'erreurs repose sur l\'analyse des caract\xe9ristiques du syst\xe8me et sur des exp\xe9riences ant\xe9rieures pour anticiper d\'\xe9ventuelles d\xe9faillances.","La pr\xe9diction d\'erreurs est un processus r\xe9alis\xe9 exclusivement apr\xe8s l\'ex\xe9cution des tests.","La pr\xe9diction d\'erreurs se concentre uniquement sur les tests de r\xe9gression et les changements r\xe9cents du code.","La pr\xe9diction d\'erreurs ne peut \xeatre faite que par des d\xe9veloppeurs tr\xe8s exp\xe9riment\xe9s."],"correctAnswer":0,"explanation":"A. Correct. La pr\xe9diction d\'erreurs utilise la connaissance du syst\xe8me et les exp\xe9riences pass\xe9es pour formuler des hypoth\xe8ses sur les endroits o\xf9 des erreurs sont les plus susceptibles de se produire. B. Incorrect. La pr\xe9diction d\'erreurs doit \xeatre faite avant l\'ex\xe9cution des tests, en utilisant les connaissances pr\xe9alables pour anticiper les probl\xe8mes. C. Incorrect. Bien que les tests de r\xe9gression puissent faire partie du processus, la pr\xe9diction d\'erreurs ne se limite pas \xe0 ces tests ni aux changements r\xe9cents. D. Incorrect. La pr\xe9diction d\'erreurs peut \xeatre r\xe9alis\xe9e par n\'importe quel testeur, pas seulement par des d\xe9veloppeurs exp\xe9riment\xe9s.","source":"banco-extra"},{"id":"q_batch2_v5j9hx3qq","chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un formulaire d\'inscription web a les champs suivants : \xc2ge : 18-65 ans (valide), moins de 18 ou plus de 65 (invalide). Type d\'adh\xe9sion : \'Basique\', \'Premium\', \'VIP\' (valides), toute autre valeur (invalide). En appliquant le partitionnement d\'\xe9quivalence avec le crit\xe8re de couverture \xab Chaque Choix \xbb, combien de cas de test sont n\xe9cessaires au MINIMUM pour couvrir toutes les partitions valides ?  ","options":["2","3","4","5"],"correctAnswer":1,"explanation":"A. Incorrect. 2 cas de test ne couvriraient pas les 3 partitions du type d\'adh\xe9sion. B. Correct. Avec le crit\xe8re de couverture \xab Chaque Choix \xbb, nous devons couvrir chaque partition de chaque ensemble au moins une fois. Pour le champ \xc2ge nous avons 1 partition valide (18-65), et pour le Type d\'adh\xe9sion nous avons 3 partitions valides (\'Basique\', \'Premium\', \'VIP\'). 3 cas de test sont n\xe9cessaires : TC1(\xe2ge valide, Basique), TC2(\xe2ge valide, Premium), TC3(\xe2ge valide, VIP). C. Incorrect. 4 cas de test seraient plus que n\xe9cessaire. D. Incorrect. 5 cas de test d\xe9passent le minimum requis.","source":"banco-extra"},{"id":"q_batch2_yr0f7ze9n","chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Laquelle des affirmations suivantes d\xe9crit le mieux les techniques de test en bo\xeete noire ?  ","options":["Elles se concentrent sur la structure interne du code pour concevoir des cas de test.","Elles reposent sur la validation des exigences et des sp\xe9cifications fonctionnelles sans consid\xe9rer le code.","Elles utilisent la connaissance du testeur sur le code source pour identifier des cas de test.","Elles se concentrent sur l\'ex\xe9cution de tests au niveau unitaire des composants du logiciel."],"correctAnswer":1,"explanation":"A. Incorrect. Cette description s\'applique aux techniques de test en bo\xeete blanche, qui impliquent l\'analyse de la structure interne du logiciel. B. Correct. Les techniques de test en bo\xeete noire se concentrent sur la v\xe9rification que le logiciel fonctionne conform\xe9ment aux sp\xe9cifications, sans consid\xe9rer comment il est impl\xe9ment\xe9 en interne. C. Incorrect. L\'utilisation de la connaissance du code source est davantage align\xe9e avec les techniques de bo\xeete blanche. D. Incorrect. Cette affirmation d\xe9crit les tests r\xe9alis\xe9s au niveau unitaire des composants.","source":"banco-extra"},{"id":"q_batch2_zdybwbzfz","chapter":4,"topic":"Techniques d\'analyse et de conception des tests","question":"Un syst\xe8me de remises pour une boutique en ligne applique les r\xe8gles suivantes : Si le client est VIP ET la commande est > 100 $ : 20 % de remise. Si le client est VIP ET la commande est <= 100 $ : 10 % de remise. Si le client n\'est PAS VIP ET la commande est > 100 $ : 5 % de remise. Si le client n\'est PAS VIP ET la commande est <= 100 $ : aucune remise. Combien de r\xe8gles de d\xe9cision sont n\xe9cessaires dans la table de d\xe9cision compl\xe8te ?  ","options":["2","3","4","8"],"correctAnswer":2,"explanation":"A. Incorrect. 2 r\xe8gles ne couvriraient pas toutes les combinaisons possibles des conditions. B. Incorrect. 3 r\xe8gles laisseraient une combinaison non couverte. C. Correct. Il y a 2 conditions (Est VIP : Vrai/Faux, Commande > 100 $ : Vrai/Faux), donc math\xe9matiquement il y a 2^2 = 4 combinaisons possibles, et toutes sont r\xe9alisables selon les r\xe8gles m\xe9tier pr\xe9sent\xe9es. La table compl\xe8te n\xe9cessite 4 r\xe8gles de d\xe9cision pour couvrir toutes les combinaisons. D. Incorrect. 8 r\xe8gles seraient plus que n\xe9cessaire pour deux conditions bool\xe9ennes.","source":"banco-extra"},{"id":1004,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous participez \xe0 un projet logiciel d\xe9veloppant une plateforme d\'e-learning. L\'\xe9quipe a d\xe9cid\xe9 de r\xe9aliser des tests de r\xe9gression sur la version actuelle du syst\xe8me. Laquelle des activit\xe9s suivantes est r\xe9alis\xe9e pendant la phase de planification des tests ?  ","options":["D\xe9finir quelles fonctionnalit\xe9s seront test\xe9es lors de la prochaine it\xe9ration.","Ex\xe9cuter des cas de test pour v\xe9rifier que la fonctionnalit\xe9 de la plateforme d\'e-learning fonctionne.","Examiner les r\xe9sultats des tests et documenter les d\xe9fauts trouv\xe9s.","Analyser les exigences du syst\xe8me pour identifier les cas de test."],"correctAnswer":0,"explanation":"La planification inclut la d\xe9finition du p\xe9rim\xe8tre, c\'est-\xe0-dire ce qui sera test\xe9. Ex\xe9cuter rel\xe8ve de l\'ex\xe9cution ; analyser rel\xe8ve de l\'analyse ; examiner les r\xe9sultats rel\xe8ve de la cl\xf4ture ou de la surveillance.","source":"Pr\xe1ctica Adicional"},{"id":1006,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des activit\xe9s suivantes est TYPIQUE d\'un r\xf4le de responsable des tests ?  ","options":["D\xe9velopper des cas de test","G\xe9rer l\'\xe9quipe de test","Ex\xe9cuter des tests automatis\xe9s","R\xe9aliser l\'analyse des d\xe9fauts"],"correctAnswer":1,"explanation":"Le responsable des tests supervise, planifie et g\xe8re. D\xe9velopper et ex\xe9cuter des cas est g\xe9n\xe9ralement le r\xf4le du testeur.","source":"Pr\xe1ctica Adicional"},{"id":1030,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Dans votre projet pr\xe9c\xe9dent, le ratio entre l\'effort de d\xe9veloppement et l\'effort de test \xe9tait de 5:3. Le projet actuel estime 800 personnes-jours de d\xe9veloppement. En utilisant l\'estimation bas\xe9e sur les ratios, quelle serait l\'estimation de l\'effort de test ?  ","options":["400 personnes-jours","480 personnes-jours","533 personnes-jours","600 personnes-jours"],"correctAnswer":1,"explanation":"R\xe8gle de trois : Si 5 devs = 3 QA, alors 800 devs = X QA. X = (800 * 3) / 5 = 480 jours.","source":"Pr\xe1ctica Adicional"},{"id":1035,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des options suivantes repr\xe9sente un crit\xe8re d\'entr\xe9e pour un cycle de test ?  ","options":["Les crit\xe8res d\'acceptation du client ont \xe9t\xe9 d\xe9finis.","Tous les tests de r\xe9gression ont \xe9t\xe9 r\xe9alis\xe9s.","La couverture des exigences a \xe9t\xe9 document\xe9e.","Les livrables du projet respectent les sp\xe9cifications."],"correctAnswer":0,"explanation":"La d\xe9finition des crit\xe8res d\'acceptation est un crit\xe8re d\'entr\xe9e qui garantit que les exigences sont claires avant de commencer les tests. (Les options B et D sont des crit\xe8res de sortie).","source":"Errores Reportados - Set 2"},{"id":1036,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Votre \xe9quipe en est \xe0 la troisi\xe8me it\xe9ration d\'un projet agile. Les efforts de test des it\xe9rations pr\xe9c\xe9dentes \xe9taient : It\xe9ration 1 : 45 personnes-jours, It\xe9ration 2 : 52 personnes-jours. En utilisant l\'extrapolation, quelle serait l\'estimation la plus appropri\xe9e pour l\'It\xe9ration 3 ?  ","options":["45 personnes-jours (le minimum historique)","48,5 personnes-jours (moyenne des deux it\xe9rations)","52 personnes-jours (tendance croissante)","59 personnes-jours (extrapolation de la tendance)"],"correctAnswer":1,"explanation":"Selon le syllabus, en extrapolation l\'\xe9quipe peut extrapoler l\'effort de test de la prochaine it\xe9ration comme l\'effort moyen des derni\xe8res it\xe9rations. Avec deux it\xe9rations, la moyenne est (45 + 52) / 2 = 48,5 jours.","source":"Errores Reportados - Set 2"},{"id":1046,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lequel des \xe9l\xe9ments suivants est un crit\xe8re d\'entr\xe9e pour commencer \xe0 tester un logiciel ?  ","options":["La documentation de conception est termin\xe9e","Les rapports de tests pr\xe9c\xe9dents ont \xe9t\xe9 examin\xe9s","Un environnement de production a \xe9t\xe9 \xe9tabli","Les tests unitaires ont \xe9t\xe9 r\xe9alis\xe9s"],"correctAnswer":0,"explanation":"Une documentation de conception compl\xe8te indique que les exigences de base et les sp\xe9cifications sont pr\xeates pour permettre de cr\xe9er des conditions et de planifier le cycle de test (un crit\xe8re d\'entr\xe9e valide).","source":"Errores Reportados - Set 2"},{"id":1052,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"L\'\xe9quipe utilise la technique d\'estimation \xe0 trois points pour une nouvelle fonctionnalit\xe9. Les estimations en jours sont : Optimiste = 10, Plus probable = 15, Pessimiste = 26. Quelle est l\'estimation finale arrondie en utilisant la formule pond\xe9r\xe9e E = (o + 4m + p) / 6 ?  ","options":["15 jours","16 jours","17 jours","18 jours"],"correctAnswer":1,"explanation":"En appliquant la formule E = (o + 4m + p) / 6 : (10 + (4 * 15) + 26) / 6 = (10 + 60 + 26) / 6 = 96 / 6 = 16 jours.","source":"Generadas (Agile/Metrics)"},{"id":1053,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Pour planifier l\'effort de test du prochain Sprint, le responsable propose un sc\xe9nario optimiste o\xf9 tout fonctionne du premier coup (5 jours), un sc\xe9nario pessimiste avec de multiples blocages (15 jours) et un sc\xe9nario plus probable bas\xe9 sur l\'exp\xe9rience r\xe9cente (7 jours). En utilisant la technique \xe0 trois points, quel est l\'effort estim\xe9 ?  ","options":["8 jours","9 jours","7 jours","10 jours"],"correctAnswer":0,"explanation":"En appliquant la formule pond\xe9r\xe9e \xe0 trois points : (5 + 4*7 + 15) / 6 = (5 + 28 + 15) / 6 = 48 / 6 = 8 jours.","source":"Generadas (Agile/Metrics)"},{"id":1054,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"L\'\xe9quipe de test doit estimer l\'effort pour un nouveau projet. Elle d\xe9cide de baser son estimation sur la m\xe9trique \'Nombre de cas d\'utilisation\'. Historiquement, tester un cas d\'utilisation complet prend 3 jours. Si le nouveau projet a 12 cas d\'utilisation, elle estime 36 jours. Quelle technique a \xe9t\xe9 utilis\xe9e ?  ","options":["Estimation bas\xe9e sur le consensus (Planning Poker)","Estimation \xe0 trois points","Estimation bas\xe9e sur les ratios (ou bas\xe9e sur des m\xe9triques proportionnelles)","Extrapolation"],"correctAnswer":2,"explanation":"Une estimation bas\xe9e sur les m\xe9triques/ratios a \xe9t\xe9 utilis\xe9e. Multiplier une m\xe9trique standard (3 jours par cas d\'utilisation) par la taille du nouveau projet (12 cas) est la base des estimations param\xe9triques ou bas\xe9es sur les ratios.","source":"Generadas (Agile/Metrics)"},{"id":1055,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Sur quoi repose principalement la technique d\'estimation connue sous le nom de Planning Poker ?  ","options":["Sur des formules math\xe9matiques complexes bas\xe9es sur les lignes de code.","Sur l\'exp\xe9rience des membres de l\'\xe9quipe recherchant un consensus it\xe9ratif et interactif.","Sur l\'extrapolation directe des trois derni\xe8res it\xe9rations de l\'\xe9quipe.","Sur la formule math\xe9matique d\'estimation \xe0 trois points."],"correctAnswer":1,"explanation":"Le Planning Poker est une technique d\'estimation bas\xe9e sur l\'exp\xe9rience et le consensus interactif. L\'\xe9quipe discute et vote anonymement jusqu\'\xe0 atteindre un accord commun sur l\'effort requis.","source":"Generadas (Agile/Metrics)"},{"id":1057,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Dans le contexte des tests logiciels, laquelle des affirmations suivantes d\xe9crit le mieux l\'objectif de la planification des tests ?  ","options":["Identifier tous les d\xe9fauts possibles dans le logiciel.","D\xe9finir les ressources, le p\xe9rim\xe8tre et l\'approche des tests \xe0 r\xe9aliser.","Cr\xe9er des cas de test sp\xe9cifiques pour chaque module du logiciel.","Examiner le code source pour garantir la qualit\xe9 du logiciel."],"correctAnswer":1,"explanation":"A. Incorrect. Bien qu\'identifier les d\xe9fauts soit un objectif des tests, la planification se concentre sur la d\xe9finition de la mani\xe8re dont les tests seront r\xe9alis\xe9s. B. Correct. La planification d\xe9finit les ressources n\xe9cessaires, le p\xe9rim\xe8tre et l\'approche des tests. C. Incorrect. Cr\xe9er des cas de test fait partie de l\'ex\xe9cution, pas de la planification. D. Incorrect. Examiner le code source fait partie de la revue de qualit\xe9.","source":"Generadas (Test Planning)"},{"id":1077,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous participez \xe0 un projet logiciel d\xe9veloppant une plateforme d\'e-learning. L\'\xe9quipe a d\xe9cid\xe9 de r\xe9aliser des tests de r\xe9gression. Laquelle des activit\xe9s suivantes est r\xe9alis\xe9e pendant la phase de planification des tests ?  ","options":["D\xe9finir quelles fonctionnalit\xe9s seront test\xe9es lors de la prochaine it\xe9ration.","Ex\xe9cuter des cas de test pour v\xe9rifier que la fonctionnalit\xe9 de la plateforme fonctionne.","Examiner les r\xe9sultats des tests et documenter les d\xe9fauts trouv\xe9s.","Analyser les exigences du syst\xe8me pour identifier les cas de test."],"correctAnswer":0,"explanation":"A. Correct. D\xe9finir les fonctionnalit\xe9s \xe0 tester fait partie de la planification des tests. B. Incorrect. L\'ex\xe9cution fait partie de la phase d\'ex\xe9cution des tests. C. Incorrect. Examiner les r\xe9sultats et documenter les d\xe9fauts se fait apr\xe8s l\'ex\xe9cution. D. Incorrect. Analyser les exigences pour identifier les cas de test fait partie de l\'analyse des tests.","source":"Generadas (Test Planning)"},{"id":1078,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des activit\xe9s suivantes est TYPIQUE d\'un r\xf4le de responsable des tests ?  ","options":["D\xe9velopper des cas de test","G\xe9rer l\'\xe9quipe de test","Ex\xe9cuter des tests automatis\xe9s","R\xe9aliser l\'analyse des d\xe9fauts"],"correctAnswer":1,"explanation":"A. Incorrect. D\xe9velopper des cas de test est une t\xe2che g\xe9n\xe9ralement r\xe9alis\xe9e par un testeur. B. Correct. G\xe9rer l\'\xe9quipe de test est une responsabilit\xe9 cl\xe9 du responsable des tests. C. Incorrect. Ex\xe9cuter des tests automatis\xe9s est la t\xe2che des testeurs. D. Incorrect. L\'analyse des d\xe9fauts rel\xe8ve principalement des testeurs.","source":"Generadas (Test Roles)"},{"id":1079,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des t\xe2ches suivantes est TYPIQUEMENT r\xe9alis\xe9e par un chef des tests (test leader) ?  ","options":["D\xe9velopper des cas de test","Coordonner les ressources de l\'\xe9quipe de test","Ex\xe9cuter des tests de r\xe9gression","Sp\xe9cifier les exigences du syst\xe8me"],"correctAnswer":1,"explanation":"A. Incorrect. D\xe9velopper des cas de test rel\xe8ve des testeurs ou analystes. B. Correct. Un chef des tests est charg\xe9 de coordonner les ressources et les activit\xe9s de l\'\xe9quipe de test. C. Incorrect. Ex\xe9cuter des tests de r\xe9gression est plus couramment r\xe9alis\xe9 par les testeurs. D. Incorrect. Sp\xe9cifier les exigences rel\xe8ve des analystes m\xe9tier ou du product owner.","source":"Generadas (Test Roles)"},{"id":279,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Parmi les DEUX crit\xe8res suivants, lesquels constituent les crit\xe8res de sortie pour tester un syst\xe8me\xa0?  ","options":["A) Pr\xe9paration de l\'environnement de test","B) La possibilit\xe9 de se connecter \xe0 l\'objet de test par le testeur","C) La densit\xe9 de d\xe9fauts estim\xe9e est atteinte","D) Les exigences sont traduites au format donn\xe9/quand/alors","E) Les tests de r\xe9gression sont automatis\xe9s"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#31, LO : FL-5.1.3). Justification\xa0:\xa0la densit\xe9 de d\xe9fauts estim\xe9e est atteinte","source":"Official Sample Exam A Q#31"},{"id":280,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Son \xe9quipe utilise la technique d\'estimation en trois points pour estimer l\'effort de test d\'une nouvelle fonctionnalit\xe9 \xe0 haut risque. Les estimations suivantes ont \xe9t\xe9 faites : \u2022 Estimation la plus optimiste : 2 heures-personnes \u2022 Estimation la plus probable : 11 heures-personnes \u2022 Estimation la plus pessimiste : 14 heures-personnes Quelle est l\'estimation finale ?  ","options":["A) 9 heures-personnes","B) 14 heures-personnes","C) 11 heures-personnes","D) 10 heures-personnes"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#32, LO : FL-5.1.4). Justification\xa0: 10\xa0heures-personnes","source":"Official Sample Exam A Q#32"},{"id":281,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Elle teste une application mobile qui permet aux utilisateurs de trouver un restaurant \xe0 proximit\xe9 en fonction du type de nourriture qu\'ils souhaitent manger. Consid\xe9rez la liste suivante de cas de test, de priorit\xe9s (c\'est-\xe0-dire qu\'un nombre inf\xe9rieur signifie une priorit\xe9 plus \xe9lev\xe9e) et de d\xe9pendances\xa0: Num\xe9ro de cas de test Condition de test couverte Priorit\xe9 D\xe9pendance logique TC 001 S\xe9lectionner le type de nourriture 3 aucun TC 002 S\xe9lectionner le restaurant 2 TC 001 TC 003 Obtenir un itin\xe9raire 1 TC 002 TC 004 Appeler le restaurant 2 TC 002 TC 005 Faire une r\xe9servation 3 TC 002 Lequel des \xe9l\xe9ments suivants les cas de test doivent \xeatre ex\xe9cut\xe9s en troisi\xe8me lieu\xa0?  ","options":["A) TC 003","B) TC 005","C) TC 002","D) TC 001"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#33, LO : FL-5.1.5). Justification : TC 003","source":"Official Sample Exam A Q#33"},{"id":282,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Consid\xe9rez les cat\xe9gories de tests suivantes (1-4) et les quadrants de tests agiles (A-D) : Comment les cat\xe9gories de tests suivantes correspondent-elles aux quadrants des tests agiles ?\\n\\n1. Tests d\'utilisabilit\xe9\\n2. Tests de composants\\n3. Tests fonctionnels\\n4. Tests de fiabilit\xe9\\n\\nA. Quadrant de tests agiles Q1 : orient\xe9 technologie, soutenant l\'\xe9quipe de d\xe9veloppement  \\nB. Quadrant de tests agiles Q2 : orient\xe9 commercial, soutenant l\'\xe9quipe de d\xe9veloppement  \\nC. Quadrant de tests agiles Q3 : orient\xe9 commercial, critique produit  \\nD. Quadrant de tests agiles Q4 : Orient\xe9 technologie, critique produit","options":["A) 1C, 2A, 3B, 4D","B)1D, 2A, 3C, 4B","C) 1C, 2B, 3D, 4A","D)1D, 2B, 3C, 4A"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#34, LO : FL-5.1.7). Justification\xa0: 1C, 2A, 3B, 4D","source":"Official Sample Exam A Q#34"},{"id":283,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lors d\'une analyse des risques, le risque suivant a \xe9t\xe9 identifi\xe9 et \xe9valu\xe9 : \u2022 Risque : le temps de r\xe9ponse est trop long pour g\xe9n\xe9rer un rapport \u2022 Probabilit\xe9 du risque : moyenne ; impact du risque : \xe9lev\xe9 \u2022 R\xe9ponse au risque : o Une \xe9quipe de test ind\xe9pendante effectue des tests d\'efficacit\xe9 des performances pendant les tests du syst\xe8me o Un \xe9chantillon s\xe9lectionn\xe9 d\'utilisateurs finaux effectue des tests alpha et b\xeata avant la sortie. Quelle action proposez-vous de prendre en r\xe9ponse \xe0 ce risque analys\xe9 ?  ","options":["A) Acceptation du risque","B) Plan d\'urgence","C) Att\xe9nuation des risques","D) Transfert des risques"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#35, LO : FL-5.2.4). Justification\xa0:\xa0Att\xe9nuation des risques","source":"Official Sample Exam A Q#35"},{"id":284,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Quel produit de travail une \xe9quipe agile peut-elle utiliser pour afficher la quantit\xe9 de travail effectu\xe9e et la quantit\xe9 totale de travail restant pour une it\xe9ration donn\xe9e\xa0?  ","options":["A) Crit\xe8res d\'acceptation","B) Rapport de d\xe9faut","C) Rapport de fin de test","D) Graphique d\'avancement"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#36, LO : FL-5.3.3). Justification\xa0: diagramme d\'avancement","source":"Official Sample Exam A Q#36"},{"id":285,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous devez mettre \xe0 jour l\'un des scripts de test automatis\xe9s pour l\'aligner sur une nouvelle exigence. Quel processus indique que vous devez cr\xe9er une nouvelle version du script de test dans le r\xe9f\xe9rentiel de test\xa0?  ","options":["A) Gestion de la tra\xe7abilit\xe9","B) Essais d\'entretien","C) Gestion des configurations","D) Ing\xe9nierie des exigences"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#37, LO : FL-5.4.1). Justification\xa0:\xa0gestion de la configuration","source":"Official Sample Exam A Q#37"},{"id":286,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Re\xe7u le rapport de d\xe9faut suivant des d\xe9veloppeurs indiquant que l\'anomalie d\xe9crite dans ce rapport de test n\'est pas reproductible. L\'application se bloque 03 mai 2022 \u2013 John Doe \u2013 L\'application rejet\xe9e se bloque apr\xe8s avoir entr\xe9 \xab Test d\'entr\xe9e : $\xe4 \xbb dans le champ Nom de l\'\xe9cran de cr\xe9ation d\'un nouvel utilisateur. J\'ai essay\xe9 de me d\xe9connecter, de me connecter avec le compte test_admin01, m\xeame probl\xe8me. Essay\xe9 avec d\'autres comptes d\'administrateur de test, m\xeame probl\xe8me. Aucun message d\'erreur re\xe7u\xa0; Le journal (voir ci-joint) contient une notification d\'erreur fatale. Sur la base du sc\xe9nario de test TC-1305, l\'application doit accepter l\'entr\xe9e fournie et cr\xe9er l\'utilisateur. Veuillez corriger avec une priorit\xe9 \xe9lev\xe9e, cette fonctionnalit\xe9 est li\xe9e \xe0 REQ-0012 qui est une nouvelle exigence commerciale critique. Quelles informations critiques MANQUENT dans ce rapport de test qui auraient \xe9t\xe9 utiles aux d\xe9veloppeurs\xa0?  ","options":["A) R\xe9sultat attendu et r\xe9sultat r\xe9el","B) R\xe9f\xe9rences et statut du d\xe9faut","C) Environnement de test et \xe9l\xe9ment de test","D) Priorit\xe9 et gravit\xe9"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#38, LO : FL-5.5.1). Justification\xa0:\xa0Environnement de test et \xe9l\xe9ment de test","source":"Official Sample Exam A Q#38"},{"id":317,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Votre \xe9quipe suit un processus utilisant le pipeline de livraison DevOps. Les trois premi\xe8res \xe9tapes sont : (1) D\xe9veloppement du code (2) Pousser le code vers le syst\xe8me de contr\xf4le de version et le fusionner avec la branche \'test\' (3) Ex\xe9cuter les tests de composants du code pouss\xe9. Lequel des \xe9l\xe9ments suivants est la MEILLEURE option comme crit\xe8re d\'entr\xe9e pour l\'\xe9tape (2) de ce pipeline ?  ","options":["A) L\'analyse statique ne renvoie aucun avertissement de s\xe9v\xe9rit\xe9 \xe9lev\xe9e pour le code pouss\xe9","B) Le syst\xe8me de contr\xf4le de version ne signale aucun conflit lors de la fusion du code avec la branche \'test\'","C) Les tests de composants sont compil\xe9s et pr\xeats \xe0 \xeatre ex\xe9cut\xe9s","D) La couverture des instructions est d\'au moins 80 %"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#30, LO : FL-5.1.3). Justification : L\'analyse statique sans avertissements graves est le crit\xe8re d\'entr\xe9e le plus appropri\xe9 avant de pousser le code vers le syst\xe8me de contr\xf4le de version.","source":"Official Sample Exam B Q#30"},{"id":318,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous voulez estimer l\'effort de test pour un nouveau projet \xe0 l\'aide de l\'estimation bas\xe9e sur les ratios. Vous calculez le ratio effort de test/effort de d\xe9veloppement \xe0 partir de donn\xe9es moyenn\xe9es de quatre projets historiques similaires. Le tableau montre : P1 : D\xe9veloppement 800 000 $, Test 40 000 $ | P2 : 1 200 000 $ / 130 000 $ | P3 : 600 000 $ / 70 000 $ | P4 : 1 000 000 $ / 120 000 $. L\'effort de d\xe9veloppement estim\xe9 pour le nouveau projet est de 800 000 $. Quelle est votre estimation de l\'effort de test ?  ","options":["A) 40 000 $","B) 80 000 $","C) 81 250 $","D) 82 500 $"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#31, LO : FL-5.1.4). Justification : Le ratio moyen est (40+130+70+120)/(800+1200+600+1000) = 360/3600 = 10 %. 10 % de 800 000 $ = 80 000 $.","source":"Official Sample Exam B Q#31"},{"id":320,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Selon le mod\xe8le des quadrants de test, lequel des \xe9l\xe9ments suivants se situe dans le quadrant Q1 (\'orient\xe9 technologie\' et \'soutient l\'\xe9quipe\') ?  ","options":["A) Tests d\'utilisabilit\xe9","B) Tests fonctionnels","C) Tests d\'acceptation utilisateur","D) Tests d\'int\xe9gration de composants"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#33, LO : FL-5.1.7). Justification : Les tests d\'int\xe9gration de composants sont techniques et soutiennent l\'\xe9quipe de d\xe9veloppement, c\'est pourquoi ils appartiennent au quadrant Q1.","source":"Official Sample Exam B Q#33"},{"id":321,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"\xc9tant donn\xe9s les risques suivants : Laquelle des options suivantes \xe9tablit la MEILLEURE correspondance entre les risques et les activit\xe9s d\'att\xe9nuation ?\\n\\n1. Une impl\xe9mentation inefficace des boucles provoque des r\xe9ponses lentes du syst\xe8me\\n2. Les consommateurs changent leurs pr\xe9f\xe9rences\\n3. Inondation de la salle des serveurs\\n4. Les patients au-del\xe0 d\'un certain \xe2ge re\xe7oivent des rapports incorrects\\n\\nA. Acceptation du risque  \\nB. Tests d\'efficacit\xe9 de performance  \\nC. Utilisation de l\'analyse des valeurs limites comme technique  \\nD. Transfert du risque","options":["A) 1C, 2D, 3A, 4B","B) 1B, 2D, 3A, 4C","C) 1B, 2A, 3D, 4C","D) 1C, 2A, 3D, 4B"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#34, LO : FL-5.2.4). Justification : Risque de performance->tests de performance (1B), risque de march\xe9->acceptation (2A), risque d\'inondation->transfert/assurance (3D), risque de pr\xe9cision->valeurs limites (4C).","source":"Official Sample Exam B Q#34"},{"id":322,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des options suivantes est une m\xe9trique de qualit\xe9 du produit ?  ","options":["A) Temps moyen avant d\xe9faillance (MTTF)","B) Nombre de d\xe9fauts trouv\xe9s","C) Couverture des exigences","D) Pourcentage de d\xe9tection des d\xe9fauts"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#35, LO : FL-5.3.1). Justification : Le MTTF (temps moyen avant d\xe9faillance) mesure la fiabilit\xe9 du produit en production, c\'est donc une m\xe9trique de qualit\xe9 du produit.","source":"Official Sample Exam B Q#35"},{"id":323,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous \xeates membre d\'une \xe9quipe de test situ\xe9e en Am\xe9rique du Nord, d\xe9veloppant un produit pour un client en Europe. L\'\xe9quipe est agile, suit DevOps et utilise un pipeline CI/CD. Laquelle des options suivantes est la MOINS efficace pour communiquer l\'avancement des tests au client ?  ","options":["A) En face \xe0 face (en personne)","B) Tableaux de bord (Dashboards)","C) Courrier \xe9lectronique","D) Visioconf\xe9rence"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#36, LO : FL-5.3.3). Justification : Avec l\'\xe9quipe en Am\xe9rique du Nord et le client en Europe, la communication en personne est irr\xe9alisable et constitue l\'option la moins efficace.","source":"Official Sample Exam B Q#36"},{"id":324,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des options suivantes d\xe9crit le MIEUX un exemple de la mani\xe8re dont la gestion de la configuration (CM) soutient les tests ?  ","options":["A) Avec le num\xe9ro de version de l\'environnement, l\'outil de CM peut r\xe9cup\xe9rer les num\xe9ros de version des biblioth\xe8ques, stubs et drivers utilis\xe9s dans cet environnement","B) Avec un enregistrement des valeurs d\'entr\xe9e, l\'outil de CM peut ex\xe9cuter les cas de test pour ces configurations et calculer la couverture","C) Avec des donn\xe9es sur la date d\'achat d\'une licence logicielle, l\'outil de CM g\xe9n\xe8re automatiquement des informations sur la proximit\xe9 de la fin de la licence","D) Avec le num\xe9ro de version du cas de test, l\'outil de CM peut g\xe9n\xe9rer automatiquement des donn\xe9es de test pour ce cas"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#37, LO : FL-5.4.1). Justification : La CM permet de lier les versions de l\'environnement \xe0 des versions sp\xe9cifiques des biblioth\xe8ques, stubs et drivers, garantissant la reproductibilit\xe9 des environnements de test.","source":"Official Sample Exam B Q#37"},{"id":353,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lequel des \xe9l\xe9ments suivants n\'est PAS un objectif d\'un plan de test ?  ","options":["A) Documenter les moyens et le calendrier des activit\xe9s de test","B) Servir de moyen de communication entre les membres de l\'\xe9quipe de test","C) Consigner les d\xe9fauts trouv\xe9s pendant l\'ex\xe9cution des tests","D) Documenter les risques et les approches d\'att\xe9nuation"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#1, LO : FL-5.1.1). Justification : La consignation des d\xe9fauts rel\xe8ve du syst\xe8me de gestion des d\xe9fauts, pas du plan de test.","source":"Official Sample Exam C Q#30"},{"id":354,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Au d\xe9but de chaque it\xe9ration, l\'\xe9quipe estime la quantit\xe9 de travail (en personnes-jours) qu\'elle peut r\xe9aliser pendant cette it\xe9ration. \xc0 la fin de l\'it\xe9ration, le travail r\xe9ellement r\xe9alis\xe9 est mesur\xe9. Au fil du temps, les donn\xe9es historiques montrent que l\'\xe9quipe r\xe9alise en moyenne 80 % du travail estim\xe9. Si lors de la prochaine it\xe9ration l\'\xe9quipe estime 50 personnes-jours de travail, combien de personnes-jours le responsable des tests devrait-il planifier comme effort r\xe9el ?  ","options":["A) 40","B) 50","C) 62","D) 63"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#2, LO : FL-5.1.4). Justification : Si historiquement 80 % de l\'estimation est r\xe9alis\xe9e, l\'estimation r\xe9elle serait 50 x 0,80 = 40 personnes-jours.","source":"Official Sample Exam C Q#31"},{"id":356,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Que montre le mod\xe8le de la pyramide des tests ?  ","options":["A) Les diff\xe9rents niveaux de test et les types de d\xe9fauts les plus probables \xe0 chaque niveau","B) Le nombre relatif de tests recommand\xe9s \xe0 chaque niveau de test, avec plus de tests aux niveaux inf\xe9rieurs","C) Le co\xfbt relatif de la d\xe9tection et de la correction des d\xe9fauts \xe0 chaque niveau de test","D) La s\xe9quence recommand\xe9e dans laquelle les diff\xe9rents niveaux de test doivent \xeatre ex\xe9cut\xe9s"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#4, LO : FL-5.1.7). Justification : La pyramide des tests montre qu\'il doit y avoir de nombreux tests de composants (base) et peu de tests syst\xe8me ou E2E (sommet), car les inf\xe9rieurs sont plus rapides et moins co\xfbteux.","source":"Official Sample Exam C Q#33"},{"id":357,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Quelle est la relation entre les quadrants de test, les niveaux de test et les types de test ?  ","options":["A) Les quadrants de test incluent les niveaux de test ; les types de test aident \xe0 identifier quels quadrants de test s\'appliquent \xe0 chaque niveau","B) Les types de test aident \xe0 identifier quels quadrants de test s\'appliquent ; les quadrants de test aident \xe0 identifier quels niveaux de test utiliser","C) Les quadrants de test aident \xe0 identifier quels types de test s\'appliquent \xe0 chaque niveau ; les types de test peuvent couvrir plusieurs niveaux","D) Les niveaux de test sont des sous-ensembles des quadrants de test ; les quadrants de test sont des sous-ensembles des types de test"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#5, LO : FL-5.1.7). Justification : Les quadrants de test aident \xe0 identifier quels types de test (fonctionnel, non fonctionnel, bo\xeete blanche, etc.) sont applicables \xe0 chaque niveau de test.","source":"Official Sample Exam C Q#34"},{"id":358,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lequel des \xe9l\xe9ments suivants est un exemple de la mani\xe8re dont l\'analyse des risques produit peut influencer l\'exhaustivit\xe9 et l\'approche des tests ?  ","options":["A) Augmenter la couverture de test des fonctionnalit\xe9s les plus \xe0 risque","B) Prioriser les tests des fonctionnalit\xe9s r\xe9cemment impl\xe9ment\xe9es par rapport aux plus anciennes","C) Ex\xe9cuter d\'abord les tests les plus courts pour obtenir des r\xe9sultats rapides","D) Concentrer l\'effort de test sur les composants d\xe9velopp\xe9s par les testeurs les moins exp\xe9riment\xe9s"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#6, LO : FL-5.2.3). Justification : L\'analyse des risques dirige l\'effort de test vers les zones les plus \xe0 risque, augmentant leur couverture.","source":"Official Sample Exam C Q#35"},{"id":359,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des activit\xe9s du processus de test suivantes utilise le PLUS les rapports d\'avancement des tests ?  ","options":["A) Planification des tests","B) Surveillance et contr\xf4le des tests","C) Analyse des tests","D) Conception des tests"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#7, LO : FL-5.3.2). Justification : La surveillance et le contr\xf4le des tests utilisent les rapports d\'avancement pour comparer l\'avancement r\xe9el \xe0 celui planifi\xe9 et prendre des d\xe9cisions correctives.","source":"Official Sample Exam C Q#36"},{"id":360,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lequel des \xe9l\xe9ments suivants n\'est PAS un exemple de la mani\xe8re dont la gestion de la configuration (CM) soutient les tests ?  ","options":["A) Tenir un registre des \xe9l\xe9ments de configuration qui composent l\'environnement de test","B) G\xe9n\xe9rer automatiquement des cas de test suppl\xe9mentaires lorsque des d\xe9fauts sont d\xe9tect\xe9s dans le logiciel","C) Permettre la tra\xe7abilit\xe9 entre les cas de test et les \xe9l\xe9ments de travail qu\'ils testent","D) Garantir que tous les membres de l\'\xe9quipe utilisent la m\xeame version des cas de test"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#8, LO : FL-5.4.1). Justification : La g\xe9n\xe9ration automatique de cas de test n\'est pas une fonction de la gestion de la configuration.","source":"Official Sample Exam C Q#37"},{"id":361,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Consid\xe9rez le rapport de d\xe9faut suivant pour une application web d\'achat : Application : WebShop v0.9.1. Module : Panier. R\xe9sum\xe9 : \'Le bouton Supprimer du panier ne fonctionne pas lorsqu\'il y a exactement 1 article\'. \xc9tapes :  \\n  \\n1) Se connecter  \\n  \\n2) Ajouter 1 article au panier  \\n  \\n3) Cliquer sur Supprimer. R\xe9sultat attendu : L\'article est supprim\xe9 et le panier est vide. R\xe9sultat r\xe9el : Rien ne se passe. Lequel des \xe9l\xe9ments suivants est ABSENT de ce rapport de d\xe9faut ?  ","options":["A) L\'identifiant du cas de test qui a r\xe9v\xe9l\xe9 le d\xe9faut","B) Les donn\xe9es d\'environnement/configuration du syst\xe8me","C) La s\xe9v\xe9rit\xe9 du d\xe9faut","D) La priorit\xe9 du d\xe9faut"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#9, LO : FL-5.5.1). Justification : Le rapport ne pr\xe9cise pas la version du syst\xe8me d\'exploitation, le navigateur ou d\'autres donn\xe9es d\'environnement n\xe9cessaires pour reproduire le d\xe9faut.","source":"Official Sample Exam C Q#38"},{"id":388,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lequel des \xe9l\xe9ments suivants d\xe9finit le MIEUX les crit\xe8res de sortie (EXIT criteria) dans un projet de test ?  ","options":["A) Le budget est approuv\xe9","B) Le budget est \xe9puis\xe9","C) La base de test est disponible","D) Les cas de test ont atteint au moins 80 % de couverture des instructions"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#30, LO : FL-5.1.3). Justification : Le budget est \xe9puis\xe9.","source":"Official Sample Exam D Q#30"},{"id":389,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"L\'\xe9quipe veut estimer le temps pour ex\xe9cuter quatre cas de test. Les mesures pour un cas sont : Meilleur sc\xe9nario : 1 h, Pire sc\xe9nario : 8 h, Plus probable : 3 h. En utilisant la technique d\'estimation \xe0 trois points, quelle est l\'estimation finale pour les QUATRE cas de test ?  ","options":["A) 14 heures","B) 3,5 heures","C) 16 heures","D) 12 heures"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#31, LO : FL-5.1.4). Justification : Trois points par cas = (1 + 4x3 + 8)/6 = 3,5 h ; x4 cas = 14 heures.","source":"Official Sample Exam D Q#31"},{"id":390,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous disposez d\'une matrice de tra\xe7abilit\xe9 et vous souhaitez prioriser les cas de test selon la technique de priorisation par couverture additionnelle. Vous ex\xe9cuterez quatre cas de test. Selon les techniques standard, quel cas de test devrait \xeatre ex\xe9cut\xe9 en DERNIER ?  ","options":["A) TC1","B) TC2","C) TC3","D) TC4"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#32, LO : FL-5.1.5). Justification : TC2.","source":"Official Sample Exam D Q#32"},{"id":391,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Comment les quadrants de test peuvent-ils \xeatre b\xe9n\xe9fiques ?  ","options":["A) Ils aident \xe0 planifier en divisant en quatre phases : composant, int\xe9gration, syst\xe8me, acceptation","B) Ils aident \xe0 \xe9valuer la couverture de haut niveau \xe0 partir de celle de bas niveau","C) Ils aident les parties prenantes non techniques \xe0 comprendre les diff\xe9rents types de test et leur pertinence par niveaux","D) Ils aident les \xe9quipes agiles \xe0 communiquer selon des profils psychologiques"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#33, LO : FL-5.1.7). Justification : Ils aident les parties prenantes non techniques \xe0 comprendre les diff\xe9rents types de test et leur pertinence par niveaux.","source":"Official Sample Exam D Q#33"},{"id":392,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Pour un risque donn\xe9, le niveau de risque est de 1 000 $ et sa probabilit\xe9 est estim\xe9e \xe0 50 %. Quel est l\'impact du risque ?  ","options":["A) 500 $","B) 2 000 $","C) 50 000 $","D) 200 $"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#34, LO : FL-5.2.1). Justification : Niveau de risque = impact x probabilit\xe9, donc impact = 1 000 / 0,50 = 2 000 $.","source":"Official Sample Exam D Q#34"},{"id":393,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lequel des \xe9l\xe9ments suivants est un risque produit ?  ","options":["A) D\xe9rive du p\xe9rim\xe8tre (Scope creep)","B) Architecture d\xe9ficiente (Poor architecture)","C) R\xe9duction des co\xfbts","D) Manque de support des outils","E) Temps de r\xe9ponse trop long"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#35, LO : FL-5.2.2). Justification : Architecture d\xe9ficiente (Poor architecture).","source":"Official Sample Exam D Q#35"},{"id":394,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lequel des \xe9l\xe9ments suivants n\'est PAS un objectif valide pour un rapport de test ?  ","options":["A) Suivre l\'avancement et identifier les zones n\xe9cessitant attention","B) Fournir des informations sur les tests ex\xe9cut\xe9s, les r\xe9sultats et les d\xe9fauts","C) Fournir des informations sur la mani\xe8re de reproduire chaque d\xe9faut \xe9tape par \xe9tape","D) Fournir des informations sur les tests planifi\xe9s pour la prochaine p\xe9riode"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#36, LO : FL-5.3.2). Justification : Fournir les \xe9tapes pour reproduire chaque d\xe9faut rel\xe8ve du rapport de d\xe9faut, pas du rapport de test.","source":"Official Sample Exam D Q#36"},{"id":395,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Un utilisateur a signal\xe9 une d\xe9faillance. Le support lui a demand\xe9 la version du logiciel. Avec cette version, l\'\xe9quipe a reconstruit les fichiers de la version, ce qui a permis au d\xe9veloppeur d\'analyser et de corriger le d\xe9faut. Quel processus a rendu cette activit\xe9 possible ?  ","options":["A) Gestion des risques","B) Surveillance et contr\xf4le des tests","C) Approche d\'\xe9quipe enti\xe8re (Whole team)","D) Gestion de la configuration"],"correctAnswer":3,"explanation":"L\'option D) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#37, LO : FL-5.4.1). Justification : Gestion de la configuration.","source":"Official Sample Exam D Q#37"},{"id":396,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Consid\xe9rez un rapport de d\xe9faut d\'un syst\xe8me de pr\xeat de livres. Laquelle des actions suivantes aiderait le PLUS le d\xe9veloppeur \xe0 reproduire rapidement la d\xe9faillance ?  ","options":["A) Ajouter des informations sur les utilisateurs et les livres concern\xe9s dans la section \'Description\'","B) Remplir la valeur manquante du champ \'Priorit\xe9\'","C) Ajouter des vidages de m\xe9moire apr\xe8s chaque \xe9tape \xe0 la section \'Pi\xe8ces jointes\'","D) R\xe9p\xe9ter le cas de test pour diff\xe9rents environnements et cr\xe9er un rapport distinct pour chacun"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#38, LO : FL-5.5.1). Justification : Ajouter des informations sur les utilisateurs et les livres concern\xe9s aide le d\xe9veloppeur \xe0 reproduire la d\xe9faillance.","source":"Official Sample Exam D Q#38"},{"id":413,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous \xeates responsable des tests et devez estimer l\'effort de test pour un nouveau projet. Vous disposez de donn\xe9es historiques de 5 projets similaires. Quelle approche d\'estimation utiliseriez-vous PRINCIPALEMENT ?  ","options":["A) Wideband Delphi exclusivement","B) Estimation bas\xe9e sur les m\xe9triques \xe0 partir de donn\xe9es historiques de projets similaires","C) Planning Poker avec l\'\xe9quipe de d\xe9veloppement","D) Estimation par points de fonction sans donn\xe9es historiques"],"correctAnswer":1,"explanation":"L\'estimation bas\xe9e sur les m\xe9triques utilise des donn\xe9es historiques de projets ant\xe9rieurs similaires pour calculer l\'effort. Avec 5 projets historiques disponibles, cette approche est la plus solide et objective.","source":"banco"},{"id":414,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Votre plan de test indique 200 cas de test planifi\xe9s pour la semaine. \xc0 la fin de la semaine, vous en avez ex\xe9cut\xe9 140 et trouv\xe9 25 d\xe9fauts, dont 8 sont critiques et toujours non corrig\xe9s. Quelle information est la PLUS pertinente pour d\xe9cider de livrer ou non le logiciel ?  ","options":["A) Uniquement le pourcentage d\'ex\xe9cution (70 %)","B) Uniquement le nombre total de d\xe9fauts (25)","C) La densit\xe9 de d\xe9fauts critiques non r\xe9solus et les crit\xe8res de sortie d\xe9finis dans le plan","D) Le nombre de tests en attente (60)"],"correctAnswer":2,"explanation":"Les crit\xe8res de sortie du plan de test d\xe9finissent les conditions pour livrer. Les d\xe9fauts critiques non r\xe9solus sont le facteur le plus pertinent pour la d\xe9cision de mise en production.","source":"banco"},{"id":415,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Un d\xe9faut a une s\xe9v\xe9rit\xe9 \'critique\' (le syst\xe8me plante) mais une priorit\xe9 \'basse\' attribu\xe9e par le product owner. Quelle est l\'explication la PLUS probable ?  ","options":["A) C\'est une erreur ; la s\xe9v\xe9rit\xe9 et la priorit\xe9 doivent toujours co\xefncider","B) Le d\xe9faut affecte une fonctionnalit\xe9 rarement utilis\xe9e ou non critique pour le m\xe9tier en ce moment","C) Le product owner ne comprend pas la s\xe9v\xe9rit\xe9 technique","D) La priorit\xe9 est toujours plus importante que la s\xe9v\xe9rit\xe9 en Agile"],"correctAnswer":1,"explanation":"La s\xe9v\xe9rit\xe9 (impact technique) et la priorit\xe9 (urgence m\xe9tier) sont des concepts ind\xe9pendants. Un plantage dans une fonctionnalit\xe9 peu utilis\xe9e peut avoir une s\xe9v\xe9rit\xe9 technique \xe9lev\xe9e mais une priorit\xe9 m\xe9tier basse.","source":"banco"},{"id":416,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous travaillez sur un projet avec un risque produit identifi\xe9 : \'Le module de paiement pourrait \xe9chouer sous forte charge\'. Quel type de test devriez-vous prioriser pour att\xe9nuer ce risque ?  ","options":["A) Tests de r\xe9gression du module de paiement","B) Tests de performance/charge du module de paiement","C) Revue statique du code du module de paiement","D) Tests d\'acceptation utilisateur du module de paiement"],"correctAnswer":1,"explanation":"Le risque identifi\xe9 concerne la performance sous charge, donc les tests de performance/charge sont les plus appropri\xe9s pour valider et att\xe9nuer ce risque produit sp\xe9cifique.","source":"banco"},{"id":423,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Quel document d\xe9crit le p\xe9rim\xe8tre, l\'approche, les ressources, le calendrier et les objectifs des activit\xe9s de test pour un projet sp\xe9cifique ?  ","options":["A) Strat\xe9gie de test","B) Plan de test","C) Sp\xe9cification de cas de test","D) Rapport de synth\xe8se des tests"],"correctAnswer":1,"explanation":"Le plan de test d\xe9crit, pour un projet sp\xe9cifique : le p\xe9rim\xe8tre, les objectifs, l\'approche, les crit\xe8res d\'entr\xe9e/sortie, les ressources, les risques et le calendrier des activit\xe9s de test.","source":"banco"},{"id":436,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous \xeates responsable des tests. Le projet a 2 semaines de retard. Le directeur demande de r\xe9duire de moiti\xe9 le temps de test. Quelle est la r\xe9ponse la PLUS professionnelle ?  ","options":["A) Accepter et ex\xe9cuter tous les tests plus rapidement","B) Supprimer au hasard la moiti\xe9 des cas de test","C) Pr\xe9senter l\'analyse des risques : quelle couverture est perdue, quels risques augmentent, et proposer une priorisation bas\xe9e sur les risques","D) Refuser compl\xe8tement de r\xe9duire le temps de test"],"correctAnswer":2,"explanation":"La r\xe9ponse professionnelle est d\'utiliser la gestion des risques : montrer quelles zones resteront non couvertes, l\'impact sur la qualit\xe9, et proposer une strat\xe9gie de priorisation bas\xe9e sur les risques pour maximiser la valeur avec le temps disponible.","source":"banco"},{"id":437,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lequel des \xe9l\xe9ments suivants est un exemple de \'risque projet\' (par opposition au risque produit) dans le contexte des tests ?  ","options":["A) Le module de paiement peut pr\xe9senter des vuln\xe9rabilit\xe9s de s\xe9curit\xe9","B) L\'indisponibilit\xe9 de l\'environnement de test peut retarder l\'ex\xe9cution","C) L\'algorithme de recherche peut renvoyer des r\xe9sultats incorrects","D) Le syst\xe8me peut se d\xe9grader sous forte charge d\'utilisateurs"],"correctAnswer":1,"explanation":"Les risques projet menacent le plan du projet (ressources, environnements, outils, calendrier). Les risques produit menacent la qualit\xe9 du logiciel. Le manque d\'environnement est un risque projet.","source":"banco"},{"id":443,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Quel est l\'objectif du \'rapport de synth\xe8se des tests\' (test summary report) \xe0 la fin d\'une phase ?  ","options":["A) Lister tous les cas de test \xe0 ex\xe9cuter","B) Communiquer les r\xe9sultats, les m\xe9triques, les d\xe9fauts et l\'\xe9valuation des crit\xe8res de sortie aux parties prenantes","C) D\xe9crire les techniques de conception de tests utilis\xe9es","D) D\xe9finir le budget pour la prochaine phase de test"],"correctAnswer":1,"explanation":"Le rapport de synth\xe8se des tests communique les r\xe9sultats des tests aux parties prenantes : cas ex\xe9cut\xe9s/r\xe9ussis/\xe9chou\xe9s, d\xe9fauts trouv\xe9s, couverture atteinte et \xe9valuation des crit\xe8res de sortie.","source":"banco"},{"id":451,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"CAS PRATIQUE : Vous avez 100 cas de test \xe0 ex\xe9cuter en 5 jours. Apr\xe8s 3 jours, vous avez ex\xe9cut\xe9 50 cas, trouv\xe9 15 d\xe9fauts (5 critiques), et l\'\xe9quipe de d\xe9veloppement en a corrig\xe9 8. Les crit\xe8res de sortie exigent : 90 % d\'ex\xe9cution, 0 d\xe9faut critique ouvert. Quelle est votre situation ?  ","options":["A) Vous pouvez livrer : vous avez satisfait les crit\xe8res de sortie","B) Vous ne pouvez pas livrer : il manque des cas de test et vous avez des d\xe9fauts critiques ouverts","C) Vous pouvez livrer car vous avez trouv\xe9 et corrig\xe9 la plupart des d\xe9fauts","D) Vous devez escalader au client pour qu\'il d\xe9cide de livrer ou non"],"correctAnswer":1,"explanation":"Vous ne satisfaites pas les crit\xe8res de sortie : vous n\'avez que 50 % d\'ex\xe9cution (il en faut 90 %) et il reste des d\xe9fauts critiques ouverts. Avec des d\xe9fauts critiques ouverts, les crit\xe8res de sortie ne sont pas remplis.","source":"banco"},{"id":452,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"CAS PRATIQUE : Votre \xe9quipe a identifi\xe9 les risques produit suivants : R1(prob=\xc9lev\xe9e, impact=\xc9lev\xe9), R2(prob=Faible, impact=\xc9lev\xe9), R3(prob=\xc9lev\xe9e, impact=Faible), R4(prob=Faible, impact=Faible). En utilisant les tests bas\xe9s sur les risques, dans quel ordre priorisez-vous les tests ?  ","options":["A) R4, R3, R2, R1","B) R1, R2, R3, R4","C) R1, R3, R2, R4","D) R2, R1, R4, R3"],"correctAnswer":2,"explanation":"Le niveau de risque = probabilit\xe9 x impact. R1(\xc9 x \xc9 = tr\xe8s \xe9lev\xe9), R3 et R2 (moyen-\xe9lev\xe9), R4(F x F = faible). R1 d\'abord, puis R3 et R2 (niveau similaire), enfin R4. L\'ordre correct est R1, R3, R2, R4.","source":"banco"},{"id":459,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"CAS PRATIQUE : Vous g\xe9rez les tests d\'une application mobile. 3 jours avant la mise en production, votre \xe9quipe trouve un d\xe9faut grave dans le flux de paiement. La correction du d\xe9veloppeur prendra 2 jours. Quel est le processus correct selon l\'ISTQB ?  ","options":["A) Annuler automatiquement la mise en production","B) Enregistrer le d\xe9faut, \xe9valuer l\'impact et le risque, escalader pour une d\xe9cision m\xe9tier sur le report ou la livraison avec un contournement document\xe9","C) Le testeur doit corriger le d\xe9faut directement","D) Ignorer le d\xe9faut si le client ne l\'a pas encore signal\xe9"],"correctAnswer":1,"explanation":"Le processus correct est : documenter le d\xe9faut (rapport de bug), analyser l\'impact/risque et escalader aux parties prenantes avec les informations pour d\xe9cider. Ce n\'est pas au testeur de d\xe9cider unilat\xe9ralement de reporter ou de livrer ; c\'est une d\xe9cision m\xe9tier \xe9clair\xe9e.","source":"banco"},{"id":464,"chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des options suivantes d\xe9crit le mieux les \'crit\xe8res de sortie\' (exit criteria) d\'une phase de test ?  ","options":["A) Les conditions pour commencer les tests","B) Les conditions qui doivent \xeatre remplies pour consid\xe9rer une phase de test comme termin\xe9e","C) Le nombre maximal de d\xe9fauts autoris\xe9s en production","D) La date limite du projet"],"correctAnswer":1,"explanation":"Les crit\xe8res de sortie (ou Definition of Done) d\xe9finissent quand une phase de test peut \xeatre consid\xe9r\xe9e comme termin\xe9e : ex. 95 % des cas ex\xe9cut\xe9s, 0 d\xe9faut critique ouvert, couverture d\'au moins 80 %.","source":"banco"},{"id":"q_batch2_1ksnvb89h","chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des affirmations suivantes d\xe9crit le mieux comment la gestion de la configuration contribue \xe0 des tests efficaces ?  ","options":["Elle permet aux testeurs de travailler avec des versions obsol\xe8tes des cas de test.","Elle facilite l\'identification et le contr\xf4le des \xe9l\xe9ments de test et de leurs versions.","Elle garantit que tous les d\xe9fauts sont document\xe9s sans besoin de versions.","Elle \xe9limine le besoin de maintenir des enregistrements de modifications pour les cas de test."],"correctAnswer":1,"explanation":"A. Incorrect. Travailler avec des versions obsol\xe8tes peut causer confusion et erreurs dans les tests. B. Correct. La gestion de la configuration permet de contr\xf4ler et d\'identifier les \xe9l\xe9ments de test tout au long de leur cycle de vie, facilitant ainsi des tests efficaces. C. Incorrect. La documentation des d\xe9fauts ne d\xe9pend pas de cette gestion. D. Incorrect. La gestion de la configuration n\xe9cessite bien de maintenir des enregistrements de modifications pour garantir la tra\xe7abilit\xe9 et le contr\xf4le des versions.","source":"banco-extra"},{"id":"q_batch2_apxr5xluy","chapter":5,"topic":"Gestion des activit\xe9s de test","question":"De quelle mani\xe8re les testeurs peuvent-ils contribuer \xe0 l\'am\xe9lioration des processus dans la planification de la livraison ?  ","options":["Les testeurs analysent les r\xe9sultats des tests pr\xe9c\xe9dents pour identifier des axes d\'am\xe9lioration dans le processus de d\xe9veloppement.","Les testeurs ne font qu\'ex\xe9cuter des cas de test sans s\'impliquer dans la planification.","Les testeurs sont charg\xe9s de documenter toutes les erreurs qu\'ils trouvent, sans participer aux discussions sur la planification.","Les testeurs n\'ont aucune influence sur la planification de la livraison, car leur r\xf4le est strictement technique."],"correctAnswer":0,"explanation":"A. Correct. Analyser les r\xe9sultats des tests pr\xe9c\xe9dents permet aux testeurs de sugg\xe9rer des am\xe9liorations du processus, ce qui ajoute de la valeur \xe0 la planification. B. Incorrect. La participation active des testeurs \xe0 la planification est essentielle au succ\xe8s du projet. C. Incorrect. Documenter les erreurs est important, mais les testeurs doivent aussi participer \xe0 la planification et aux discussions sur les processus. D. Incorrect. Les testeurs jouent un r\xf4le crucial dans la planification et la livraison, car leur exp\xe9rience peut influencer le processus.","source":"banco-extra"},{"id":"q_batch2_du99np3p4","chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Pendant le test d\'un syst\xe8me, plusieurs erreurs ont \xe9t\xe9 signal\xe9es et corrig\xe9es. Apr\xe8s la publication d\'une nouvelle version du logiciel, il est d\xe9cid\xe9 d\'ex\xe9cuter \xe0 nouveau les tests. Lesquels des tests suivants sont consid\xe9r\xe9s comme des tests de confirmation ?  ","options":["Tester un nouveau module qui n\'avait pas \xe9t\xe9 test\xe9 auparavant.","Les tests qui avaient \xe9t\xe9 ex\xe9cut\xe9s pr\xe9c\xe9demment et avaient \xe9chou\xe9, maintenant r\xe9alis\xe9s pour v\xe9rifier la correction.","Tests de charge r\xe9alis\xe9s pour v\xe9rifier la performance dans des conditions extr\xeames.","Tests d\'int\xe9gration de modules ajout\xe9s dans la nouvelle version."],"correctAnswer":1,"explanation":"A. Cette option n\'est pas consid\xe9r\xe9e comme un test de confirmation, car elle concerne un nouveau module et n\'est pas li\xe9e \xe0 la v\xe9rification de d\xe9fauts corrig\xe9s. B. Correct. Les tests qui avaient \xe9chou\xe9 sont r\xe9p\xe9t\xe9s pour confirmer que les d\xe9fauts ont \xe9t\xe9 corrig\xe9s, ce qui les classe comme tests de confirmation. C. Les tests de charge se concentrent sur la performance et ne sont pas li\xe9s \xe0 la v\xe9rification des corrections. D. Les tests d\'int\xe9gration ne sont pas des tests de confirmation \xe0 moins d\'\xeatre ex\xe9cut\xe9s sp\xe9cifiquement pour valider des corrections de tests pr\xe9c\xe9dents.","source":"banco-extra"},{"id":"q_batch2_j0vlxcr58","chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Lequel des rapports suivants est le plus appropri\xe9 pour communiquer l\'\xe9tat actuel des tests aux parties prenantes pendant le cycle de vie de d\xe9veloppement logiciel ?  ","options":["Rapport d\'avancement des tests","Rapport de tests de r\xe9gression","Rapport de d\xe9fauts ouverts","Rapport d\'incidents"],"correctAnswer":0,"explanation":"A. Correct. Le rapport d\'avancement des tests fournit un r\xe9sum\xe9 de l\'\xe9tat actuel des tests, y compris quels tests ont \xe9t\xe9 r\xe9alis\xe9s et lesquels sont en attente. B. Incorrect. Le rapport de tests de r\xe9gression se concentre sur les tests r\xe9alis\xe9s apr\xe8s des changements logiciels. C. Incorrect. Le rapport de d\xe9fauts ouverts montre les probl\xe8mes existants mais ne communique pas l\'avancement des tests lui-m\xeame. D. Incorrect. Le rapport d\'incidents se r\xe9f\xe8re aux probl\xe8mes trouv\xe9s, pas \xe0 une vue d\'ensemble de l\'\xe9tat des tests.","source":"banco-extra"},{"id":"q_batch2_jfwjvhmmc","chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Vous avez pr\xe9par\xe9 le rapport de d\xe9faut suivant : ID du d\xe9faut : BUG-00456. Date : 15-01-2025. Titre : Le bouton \'Envoyer le paiement\' ne r\xe9pond pas apr\xe8s la s\xe9lection d\'une m\xe9thode de paiement. S\xe9v\xe9rit\xe9 : \xc9lev\xe9e. Priorit\xe9 : Critique. Signal\xe9 par : Analyste de tests. Configuration : Version de l\'application 2.15.087, Navigateur : Firefox 118.0.2.0. R\xe9sultat attendu : Le bouton \'Envoyer le paiement\' devrait traiter les informations de paiement et rediriger vers la page de confirmation. Pi\xe8ces jointes : Capture d\'\xe9cran, Enregistrement d\'\xe9cran. Quelle est l\'information la PLUS importante manquante dans ce rapport de d\xe9faut qu\'un analyste de tests devrait inclure pour faciliter une r\xe9solution rapide ?  ","options":["La s\xe9quence d\xe9taill\xe9e des actions qui ont reproduit la d\xe9faillance.","La m\xe9thode d\'analyse utilis\xe9e pour identifier le probl\xe8me.","Les sp\xe9cifications du syst\xe8me d\'exploitation et l\'architecture de l\'appareil.","Une proposition de solution technique pour r\xe9soudre l\'incident."],"correctAnswer":0,"explanation":"A. Correct. Sans les \xe9tapes de reproduction, les d\xe9veloppeurs ne peuvent ni reproduire ni investiguer le d\xe9faut. B. Incorrect. La technique de test utilis\xe9e n\'est pas n\xe9cessaire pour r\xe9soudre le d\xe9faut. C. Incorrect. La configuration de l\'environnement est d\xe9j\xe0 partiellement incluse et n\'est pas la plus critique. D. Incorrect. Les testeurs ne doivent pas sugg\xe9rer de solutions techniques ; c\'est la responsabilit\xe9 des d\xe9veloppeurs.","source":"banco-extra"},{"id":"q_batch2_p48e09xyk","chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Un risque a \xe9t\xe9 identifi\xe9 lors de l\'analyse d\'un nouveau logiciel : Risque : L\'application peut ne pas \xeatre compatible avec les anciens navigateurs. Probabilit\xe9 du risque : \xe9lev\xe9e ; impact du risque : moyen. R\xe9ponse au risque : r\xe9aliser des tests de compatibilit\xe9 sur divers anciens navigateurs, fournir de la documentation sur les exigences du syst\xe8me. Quelle serait la mesure la plus appropri\xe9e \xe0 mettre en \u0153uvre face \xe0 ce risque analys\xe9 ?  ","options":["Att\xe9nuation du risque","Transfert du risque","Acceptation du risque","\xc9limination du risque"],"correctAnswer":0,"explanation":"A. Correct. Les tests de compatibilit\xe9 sont une action d\'att\xe9nuation du risque. B. Incorrect. Le transfert du risque n\'est pas applicable dans ce contexte. C. Incorrect. Accepter le risque n\'implique pas de prendre des actions concr\xe8tes pour le g\xe9rer. D. Incorrect. L\'\xe9limination du risque n\'est pas faisable dans ce cas.","source":"banco-extra"},{"id":"q_batch2_py9kk1zxn","chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des situations suivantes justifierait le mieux l\'utilisation de l\'analyse des valeurs limites (AVL) \xe0 3 valeurs plut\xf4t qu\'\xe0 2 valeurs ?  ","options":["Lorsqu\'il faut r\xe9duire le nombre de cas de test en raison de contraintes de temps","Lorsque l\'on soup\xe7onne des d\xe9fauts d\'impl\xe9mentation tr\xe8s subtils de type off-by-one","Lorsque les partitions ne sont pas ordonn\xe9es num\xe9riquement","Lorsque le code impl\xe9mente des comparaisons simples comme \'sup\xe9rieur \xe0\' ou \'inf\xe9rieur \xe0\'"],"correctAnswer":1,"explanation":"A. Incorrect. L\'AVL \xe0 3 valeurs n\xe9cessite plus de cas de test, pas moins. B. Correct. Selon le syllabus, l\'AVL \xe0 3 valeurs est plus rigoureuse que l\'AVL \xe0 2 valeurs car elle peut d\xe9tecter des d\xe9fauts n\xe9glig\xe9s par l\'AVL \xe0 2 valeurs (par exemple un d\xe9faut off-by-one que la valeur limite suppl\xe9mentaire d\xe9tecte). C. Incorrect. L\'AVL ne peut \xeatre utilis\xe9e que pour des partitions ordonn\xe9es. D. Incorrect. L\'AVL \xe0 2 valeurs serait suffisante pour des comparaisons simples bien impl\xe9ment\xe9es.","source":"banco-extra"},{"id":"q_batch2_zras116y8","chapter":5,"topic":"Gestion des activit\xe9s de test","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX le r\xf4le d\'un chef des tests dans une \xe9quipe de test ?  ","options":["Il est responsable de l\'ex\xe9cution de tous les tests manuels.","Il coordonne les activit\xe9s de test et g\xe8re l\'\xe9quipe de test.","Il est le contact principal avec le client pour la livraison des exigences.","Il est charg\xe9 de documenter les exigences du logiciel."],"correctAnswer":1,"explanation":"A. Incorrect. Bien qu\'il puisse participer aux tests, il n\'est pas charg\xe9 d\'ex\xe9cuter tous les tests manuels. B. Correct. Le chef des tests coordonne les activit\xe9s et g\xe8re l\'\xe9quipe. C. Incorrect. Ce r\xf4le correspond g\xe9n\xe9ralement au product owner ou \xe0 l\'analyste m\xe9tier. D. Incorrect. Documenter les exigences est g\xe9n\xe9ralement r\xe9alis\xe9 par les analystes m\xe9tier ou les d\xe9veloppeurs.","source":"banco-extra"},{"id":1042,"chapter":6,"topic":"Outils de test","question":"Lequel des outils de test suivants facilite la gestion des exigences et leur tra\xe7abilit\xe9 ?  ","options":["Outils de gestion des tests","Outils d\'automatisation des tests","Outils de gestion des d\xe9fauts","Outils de gestion des exigences"],"correctAnswer":3,"explanation":"Les outils de gestion des exigences sont sp\xe9cifiquement con\xe7us pour faciliter la gestion et la tra\xe7abilit\xe9 des exigences tout au long du cycle de vie du projet.","source":"Errores Reportados - Set 2"},{"id":287,"chapter":6,"topic":"Outils de test","question":"Quelle activit\xe9 de test un outil de pr\xe9paration de donn\xe9es prend-il en charge\xa0?  ","options":["A) Surveillance des tests et contr\xf4le des tests","B) Analyse des tests","C) Conception des tests et mise en \u0153uvre des tests","D) Ach\xe8vement du test"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#39, LO : FL-6.1.1). Justification\xa0: conception des tests et mise en \u0153uvre des tests","source":"Official Sample Exam A Q#39"},{"id":288,"chapter":6,"topic":"Outils de test","question":"Quel \xe9l\xe9ment identifie correctement un risque potentiel li\xe9 \xe0 l\u2019automatisation des tests\xa0?  ","options":["A) Obstacles aux tests","B) Couverture des succursales atteinte","C) Progression des tests","D) Nouveaux risques dans le cycle de test","E) Temps requis pour r\xe9parer un d\xe9faut Question #A26 (1 point) Lequel des \xe9l\xe9ments d\'information suivants contenus dans un rapport d\'avancement de test est le MOINS utile aux repr\xe9sentants d\'affaires ?"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#40, LO : FL-6.2.1). Justification\xa0: Couverture des succursales atteinte","source":"Official Sample Exam A Q#40"},{"id":326,"chapter":6,"topic":"Outils de test","question":"\xc9tant donn\xe9es les descriptions suivantes : Laquelle des options suivantes \xe9tablit la MEILLEURE correspondance entre les descriptions et les cat\xe9gories ?\\n\\n1. Prennent en charge le suivi du flux de travail\\n2. Facilitent la communication\\n3. Machines virtuelles\\n4. Prennent en charge les revues\\n\\nA. Outils de test statique  \\nB. Outils qui soutiennent l\'\xe9volutivit\xe9 et la standardisation du d\xe9ploiement  \\nC. Outils DevOps  \\nD. Outils de collaboration","options":["A) 1A, 2B, 3C, 4D","B) 1B, 2D, 3C, 4A","C) 1C, 2D, 3B, 4A","D) 1D, 2C, 3A, 4B"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#39, LO : FL-6.1.1). Justification : DevOps\u2192suivi du flux (1C), Collaboration\u2192communication (2D), \xc9volutivit\xe9\u2192machines virtuelles (3B), Statique\u2192revues (4A).","source":"Official Sample Exam B Q#39"},{"id":327,"chapter":6,"topic":"Outils de test","question":"Lequel des \xe9l\xe9ments suivants est le PLUS PROBABLEMENT un avantage de l\'automatisation des tests ?  ","options":["A) Fournit des mesures de couverture trop complexes pour \xeatre obtenues manuellement par des humains","B) Partage la responsabilit\xe9 des tests avec le fournisseur de l\'outil","C) \xc9limine le besoin de pens\xe9e critique lors de l\'analyse des r\xe9sultats des tests","D) G\xe9n\xe8re des cas de test \xe0 partir de l\'analyse du code du programme"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon B, Q#40, LO : FL-6.2.1). Justification : L\'automatisation permet d\'obtenir des m\xe9triques de couverture complexes qu\'il serait peu pratique de calculer manuellement.","source":"Official Sample Exam B Q#40"},{"id":362,"chapter":6,"topic":"Outils de test","question":"Les outils de quelle cat\xe9gorie aident \xe0 organiser les cas de test, les d\xe9fauts d\xe9tect\xe9s et les r\xe9sultats des tests ?  ","options":["A) Outils de gestion des tests","B) Outils d\'analyse statique","C) Outils d\'ex\xe9cution des tests","D) Outils d\'automatisation des tests"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#10, LO : FL-6.1.1). Justification : Les outils de gestion des tests (comme Jira, TestRail) organisent et suivent les cas de test, les d\xe9fauts et les r\xe9sultats.","source":"Official Sample Exam C Q#39"},{"id":397,"chapter":6,"topic":"Outils de test","question":"\xc9tant donn\xe9es les cat\xe9gories d\'outils de test (i. Collaboration,  \\n  \\nii. DevOps,  \\n  \\niii. Gestion,  \\n  \\niv. Non fonctionnels,  \\n  \\nv. Conception/Impl\xe9mentation). Les outils de quelles cat\xe9gories sont les PLUS susceptibles de faciliter l\'ex\xe9cution des tests ?  ","options":["A) i, v","B) ii, iv","C) i, iii, v","D) ii, iii, iv"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#39, LO : FL-6.1.1). Justification : ii, iv (DevOps, Non fonctionnels).","source":"Official Sample Exam D Q#39"},{"id":398,"chapter":6,"topic":"Outils de test","question":"Lequel des \xe9l\xe9ments suivants est le PLUS susceptible d\'\xeatre un risque de l\'automatisation des tests ?  ","options":["A) D\xe9tection de d\xe9fauts suppl\xe9mentaires de s\xe9v\xe9rit\xe9 \xe9lev\xe9e","B) Fournir des m\xe9triques trop complexes pour les humains","C) Incompatibilit\xe9 avec la plateforme de d\xe9veloppement","D) R\xe9duction substantielle du temps d\'ex\xe9cution"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xc9chantillon D, Q#40, LO : FL-6.2.1). Justification : Incompatibilit\xe9 avec la plateforme de d\xe9veloppement.","source":"Official Sample Exam D Q#40"},{"id":417,"chapter":6,"topic":"Outils de test","question":"Votre organisation souhaite mettre en place un outil d\'automatisation des tests d\'IHM (GUI). Lequel des facteurs suivants repr\xe9sente le PLUS GRAND risque \xe0 long terme ?  ","options":["A) Le co\xfbt initial de la licence de l\'outil","B) La fragilit\xe9 des scripts lorsque l\'interface utilisateur change fr\xe9quemment","C) Le temps d\'apprentissage initial de l\'\xe9quipe","D) L\'incompatibilit\xe9 avec le langage de programmation du syst\xe8me"],"correctAnswer":1,"explanation":"Les scripts d\'automatisation d\'IHM sont tr\xe8s fragiles face aux changements d\'interface (localisateurs, ID, positions). Dans les projets dont l\'IHM \xe9volue rapidement, la maintenance peut d\xe9passer le b\xe9n\xe9fice de l\'automatisation.","source":"banco"},{"id":418,"chapter":6,"topic":"Outils de test","question":"Quelle est la diff\xe9rence cl\xe9 entre un outil d\'ex\xe9cution des tests et un outil de gestion des tests ?  ","options":["A) Il n\'y a aucune diff\xe9rence, c\'est le m\xeame outil","B) L\'outil d\'ex\xe9cution automatise le lancement des scripts ; l\'outil de gestion organise, planifie et enregistre la progression et les r\xe9sultats des tests","C) L\'outil de gestion ne sert qu\'aux tests manuels ; l\'outil d\'ex\xe9cution aux tests automatis\xe9s","D) L\'outil d\'ex\xe9cution g\xe9n\xe8re des rapports ; l\'outil de gestion ex\xe9cute les cas de test"],"correctAnswer":1,"explanation":"Les outils d\'ex\xe9cution (ex. Selenium, JUnit) lancent les tests automatiquement. Les outils de gestion (ex. TestRail, Zephyr) organisent les cas, les plans, les cycles de test et suivent les r\xe9sultats et la couverture.","source":"banco"},{"id":438,"chapter":6,"topic":"Outils de test","question":"Une entreprise \xe9value le ROI de l\'automatisation de sa suite de r\xe9gression (500 cas manuels, 2 h par ex\xe9cution manuelle). Si l\'automatisation co\xfbte 200 heures et que chaque ex\xe9cution automatis\xe9e prend 15 min, combien d\'ex\xe9cutions sont n\xe9cessaires pour rentabiliser l\'investissement ?  ","options":["A) 10 ex\xe9cutions","B) 50 ex\xe9cutions","C) 100 ex\xe9cutions","D) 200 ex\xe9cutions"],"correctAnswer":2,"explanation":"\xc9conomie par ex\xe9cution : 2 h - 0,25 h = 1,75 h. Pour r\xe9cup\xe9rer 200 h d\'investissement : 200/1,75 \u2248 114 ex\xe9cutions. L\'option la plus proche est 100, bien que le calcul exact donne ~114. (Dans de nombreux examens, le calcul est simplifi\xe9.)","source":"banco"},{"id":444,"chapter":6,"topic":"Outils de test","question":"Lequel des \xe9l\xe9ments suivants est un b\xe9n\xe9fice R\xc9EL de l\'automatisation des tests ?  ","options":["A) Elle \xe9limine compl\xe8tement le besoin de tests manuels","B) Elle permet d\'ex\xe9cuter une r\xe9gression fr\xe9quente et coh\xe9rente avec moins d\'effort par ex\xe9cution apr\xe8s l\'investissement initial","C) Elle trouve plus de types de d\xe9fauts que les tests manuels","D) Elle est toujours rentable quel que soit le type de projet"],"correctAnswer":1,"explanation":"L\'automatisation permet d\'ex\xe9cuter la r\xe9gression de mani\xe8re r\xe9p\xe9t\xe9e, avec coh\xe9rence et moins d\'effort par cycle. Elle n\'\xe9limine pas les tests manuels, n\'est pas toujours rentable, et les humains d\xe9tectent certains d\xe9fauts que l\'automatisation ne d\xe9tecte pas.","source":"banco"},{"id":456,"chapter":6,"topic":"Outils de test","question":"CAS PRATIQUE : Votre entreprise souhaite adopter un outil d\'automatisation des tests d\'API. L\'\xe9quipe \xe9value : le co\xfbt, la courbe d\'apprentissage, l\'int\xe9gration CI/CD, la prise en charge des protocoles REST/SOAP et la maintenabilit\xe9. Quel est le facteur le PLUS critique pour garantir le succ\xe8s \xe0 long terme ?  ","options":["A) Le co\xfbt de licence le plus bas","B) La facilit\xe9 de maintenance et l\'int\xe9gration avec le pipeline CI/CD existant","C) Qu\'il prenne en charge le plus grand nombre possible de protocoles","D) Qu\'il ait l\'interface la plus intuitive"],"correctAnswer":1,"explanation":"\xc0 long terme, la maintenabilit\xe9 des scripts et l\'int\xe9gration CI/CD sont critiques. Les tests difficiles \xe0 maintenir sont abandonn\xe9s. Sans int\xe9gration au pipeline, l\'automatisation n\'apporte pas de valeur continue.","source":"banco"},{"id":463,"chapter":6,"topic":"Outils de test","question":"Qu\'est-ce qu\'un \xab framework d\'automatisation des tests pilot\xe9 par mots-cl\xe9s \xbb (keyword-driven) ?  ","options":["A) Un framework o\xf9 les mots-cl\xe9s sont des mots de passe d\'acc\xe8s","B) Un framework o\xf9 les cas de test sont d\xe9crits \xe0 l\'aide de mots-cl\xe9s de haut niveau repr\xe9sentant des actions (ex. : \xab Login \xbb, \xab ClickButton \xbb, \xab VerifyText \xbb)","C) Un framework uniquement pour les tests de s\xe9curit\xe9","D) Un framework qui utilise l\'intelligence artificielle pour g\xe9n\xe9rer des tests"],"correctAnswer":1,"explanation":"Le test pilot\xe9 par mots-cl\xe9s utilise des mots-cl\xe9s ou mots d\'action qui repr\xe9sentent des op\xe9rations du syst\xe8me. Les cas de test sont \xe9crits dans des tableaux avec ces mots-cl\xe9s, s\xe9parant la conception des tests de leur impl\xe9mentation technique.","source":"banco"},{"id":"q_batch3_bi3fp7yfr","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Parmi les affirmations suivantes concernant la gestion des tests, laquelle est correcte\xa0?  ","options":["La gestion des tests n\'est pas n\xe9cessaire si le d\xe9veloppement est effectu\xe9 dans un environnement agile.","La gestion des tests ne doit \xeatre appliqu\xe9e que dans les \xe9tapes finales du d\xe9veloppement.","La gestion des tests aide \xe0 planifier, surveiller et contr\xf4ler le processus de test.","La gestion des tests rel\xe8ve de la seule responsabilit\xe9 de l\u2019\xe9quipe de d\xe9veloppement."],"correctAnswer":2,"explanation":"R. Incorrect. La gestion des tests est importante dans tous les environnements, y compris les environnements agiles. B. Incorrect. La gestion des tests doit \xeatre continue tout au long du cycle de vie du d\xe9veloppement. C. Exactement. La gestion des tests est essentielle pour une planification et un contr\xf4le appropri\xe9s. D. Incorrect. La gestion des tests rel\xe8ve de la responsabilit\xe9 de toute l\u2019\xe9quipe, pas seulement du d\xe9veloppement.","source":"User Provided Batch 3"},{"id":"q_batch3_nfi6e89ri","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Quel niveau de tests correspond le mieux \xe0 l\u2019identification des d\xe9fauts li\xe9s \xe0 l\u2019interface entre les diff\xe9rents modules d\u2019un syst\xe8me ?  ","options":["Tests d\'acceptation","Tests syst\xe8me","Tests d\'int\xe9gration","Tests de composants"],"correctAnswer":2,"explanation":"R. Incorrect. Les tests d\'acceptation se concentrent sur la validation si le syst\xe8me r\xe9pond aux exigences du client, et non sur l\'interface entre les modules. B. Incorrect. Les tests syst\xe8me \xe9valuent le syst\xe8me dans son ensemble, mais ne se concentrent pas sp\xe9cifiquement sur l\'interaction entre les modules. C. Exactement. Les tests d\'int\xe9gration se concentrent sur la v\xe9rification de la communication et de l\'interaction entre les diff\xe9rents composants ou modules du syst\xe8me. D. Incorrect. Les tests de composants se concentrent sur le test d\'un seul module de mani\xe8re isol\xe9e, et non sur son interaction avec d\'autres.","source":"User Provided Batch 3"},{"id":"q_batch3_vitftajfv","chapter":2,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Lequel des \xe9nonc\xe9s suivants d\xe9crit de mani\xe8re ad\xe9quate les niveaux de tests (1-4) et leurs approches sp\xe9cifiques (A-D) ?\\n\\n1. Tests effectu\xe9s pour valider la fonctionnalit\xe9 compl\xe8te du syst\xe8me dans un environnement de production simul\xe9.\\n2. Tests qui visent \xe0 v\xe9rifier que les modules individuels fonctionnent correctement.\\n3. Tests qui garantissent que les diff\xe9rents modules s\'int\xe8grent et fonctionnent ensemble.\\n4. Tests qui impliquent la validation des exigences du point de vue de l\'utilisateur final.\\n\\nA. Tests du syst\xe8me  \\nB. Tests des composants  \\nC. Tests d\'int\xe9gration  \\nD. Tests d\'acceptation","options":["A. 1A, 2B, 3C, 4D","B.1C, 2A, 3D, 4B","C.1D, 2C, 3A, 4B","D.1B, 2D, 3A, 4C"],"correctAnswer":0,"explanation":"A. L\'\xe9nonc\xe9 1 d\xe9crit correctement les tests du syst\xe8me (1A), qui valident l\'ensemble du syst\xe8me. L\'\xe9nonc\xe9 2 fait r\xe9f\xe9rence aux tests de composants (2B), o\xf9 la fonctionnalit\xe9 des modules individuels est v\xe9rifi\xe9e. 3 est li\xe9 aux tests d\'int\xe9gration (3C), qui se concentrent sur l\'interaction entre les modules. 4 correspond aux tests d\'acceptation (4D), o\xf9 les exigences sont valid\xe9es du point de vue de l\'utilisateur final. B. Le choix B est incorrect. L\'instruction 1 n\'est pas associ\xe9e aux tests d\'int\xe9gration (1C), mais aux tests du syst\xe8me. L\'\xe9nonc\xe9 2 d\xe9crit correctement les tests de composants, mais l\'\xe9nonc\xe9 3 ne concerne pas correctement les tests d\'acceptation. C. Le choix C est incorrect. L\'\xe9nonc\xe9 1 ne d\xe9crit pas les tests d\'acceptation (1D), mais constitue plut\xf4t une approche de test du syst\xe8me. Les autres descriptions ne correspondent pas non plus aux niveaux de test correspondants. D. Le choix D est incorrect. L\'\xe9nonc\xe9 1 ne correspond pas au test des composants (1B), mais au test du syst\xe8me. Les autres descriptions sont \xe9galement incorrectes concernant les niveaux de test.","source":"User Provided Batch 3"},{"id":"q_batch4_x1vez8tp7","chapter":2,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Parmi les \xe9l\xe9ments suivants, lesquels sont des facteurs pouvant affecter la strat\xe9gie de test dans un projet logiciel\xa0? Le profil de l\'\xe9quipe de test La complexit\xe9 du syst\xe8me \xe0 tester La disponibilit\xe9 des ressources mat\xe9rielles Les techniques de gestion de projet utilis\xe9es  ","options":["i, ii et iii sont des facteurs qui affectent la strat\xe9gie de test","ii, iii et iv sont des facteurs qui affectent la strat\xe9gie de test","i, iii et iv sont des facteurs qui affectent la strat\xe9gie de test","i, ii, iii et iv sont des facteurs qui affectent la strat\xe9gie de test"],"correctAnswer":0,"explanation":"A.i. C\'est vrai. Le profil de l\u2019\xe9quipe de test peut influencer la mani\xe8re dont les tests sont effectu\xe9s. ii. C\'est vrai. La complexit\xe9 du syst\xe8me affecte directement l\'approche et les outils utilis\xe9s lors des tests. iii. C\'est vrai. La disponibilit\xe9 des ressources mat\xe9rielles est cruciale pour l\u2019ex\xe9cution des tests. Ce sont donc tous des facteurs qui affectent la strat\xe9gie de test. B. ii. C\'est vrai. La complexit\xe9 du syst\xe8me affecte l\'approche de test. iii. C\'est vrai. La disponibilit\xe9 des ressources mat\xe9rielles est importante. iv. C\'est vrai. Les techniques de gestion de projet peuvent jouer un r\xf4le, mais elles ne couvrent pas tous les aspects. Ce n\u2019est donc pas l\u2019option la plus compl\xe8te. C.i. C\'est vrai. Le profil de l\u2019\xe9quipe de test est important. iii. C\'est vrai. La disponibilit\xe9 des ressources est cruciale. iv. C\'est vrai. Les techniques de gestion de projet peuvent jouer un r\xf4le, mais elles ne sont pas aussi pertinentes que les autres facteurs mentionn\xe9s. Il ne couvre donc pas tous les aspects pertinents. D.i. C\'est vrai. Le profil de l\'\xe9quipe de test influence la strat\xe9gie de test. ii. C\'est vrai. La complexit\xe9 du syst\xe8me \xe0 tester impacte la strat\xe9gie. iii. C\'est vrai. La disponibilit\xe9 des ressources mat\xe9rielles est essentielle. iv. C\'est vrai. Les techniques de gestion de projet ont \xe9galement un impact. La bonne r\xe9ponse est donc D.P.","source":"User Provided Batch 4"},{"id":"q_batch4_d9p5xynen","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Laquelle des comp\xe9tences suivantes est essentielle pour un testeur lors de l\'\xe9valuation de la qualit\xe9 d\'un produit logiciel\xa0? Communication efficace Connaissances techniques Comp\xe9tences analytiques Gestion du temps  ","options":["i et ii sont essentiels\xa0; iii et iv ne sont pas","iii et iv sont essentiels\xa0; moi et ii ne le sommes pas","ii et iii sont essentiels\xa0; moi et iv ne le sommes pas","i et iii sont essentiels\xa0; ii et iv ne sont pas"],"correctAnswer":3,"explanation":"R. Bien qu\'une communication efficace et des connaissances techniques soient importantes, elles ne sont pas essentielles \xe0 l\'\xe9valuation de la qualit\xe9, car l\'analyse et la gestion du temps sont essentielles au processus de test. B. Bien que les comp\xe9tences analytiques et la gestion du temps soient importantes, le besoin de comp\xe9tences en communication et de connaissances techniques pour \xe9valuer correctement un produit ne peut \xeatre ignor\xe9. C. Les connaissances techniques sont cruciales, mais l\'\xe9valuation de la qualit\xe9 ne peut \xeatre r\xe9alis\xe9e sans des comp\xe9tences en communication et des comp\xe9tences analytiques, qui sont tout aussi essentielles. D. Exactement. Des comp\xe9tences de communication et d\u2019analyse efficaces sont des comp\xe9tences fondamentales pour un testeur, leur permettant d\u2019interpr\xe9ter et d\u2019\xe9valuer correctement les r\xe9sultats des tests. Q","source":"User Provided Batch 4"},{"id":"q_batch4_fb7uzan6z","chapter":3,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Dans votre organisation, les r\xe9visions effectu\xe9es pr\xe9sentent les caract\xe9ristiques suivantes : Aucun r\xf4le sp\xe9cifique n\'est attribu\xe9 au mod\xe9rateur. Le but est de trouver des d\xe9fauts et d\u2019am\xe9liorer le produit. Les participants discutent ouvertement de leurs opinions. Aucune documentation formelle requise \xe0 la fin. Quel type de r\xe9vision est effectu\xe9 ?  ","options":["Examen informel","Examen technique","Inspection","Examen guid\xe9"],"correctAnswer":0,"explanation":"R. Les fonctionnalit\xe9s mentionn\xe9es sont typiques d\'une r\xe9vision informelle, o\xf9 un mod\xe9rateur n\'est pas requis et o\xf9 la documentation est minime ou inexistante. B. Les examens techniques incluent g\xe9n\xe9ralement un mod\xe9rateur et une approche plus structur\xe9e, ce qui n\'est pas mentionn\xe9 ici. C. Lors d\'une inspection, une documentation formelle et une approche m\xe9thodique pour trouver les d\xe9fauts sont attendues, ce qui n\'est pas le cas ici. D. Les r\xe9visions guid\xe9es incluent un mod\xe9rateur et mettent l\'accent sur l\'\xe9valuation de la qualit\xe9, ce qui ne s\'applique pas \xe0 la description donn\xe9e. Q","source":"User Provided Batch 4"},{"id":"q_batch4_8s5zi6k9s","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Vous testez un syst\xe8me de notation qui accepte des scores sur une \xe9chelle de 0 \xe0 100. Le syst\xe8me classe les scores comme suit : 0-59 : \xc9chec 60-69 : R\xe9ussite 70-89 : Bon 90-100 : Excellent En utilisant le partitionnement d\'\xe9quivalence, quel est le nombre MINIMUM de cas de test n\xe9cessaire pour obtenir une couverture \xe0 100\xa0% des partitions valides\xa0?  ","options":["3","4","5","6"],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. 3 cas de test ne couvriraient pas les 4 partitions valides identifi\xe9es. B. C\u2019est exact. 4 cas de tests sont n\xe9cessaires pour couvrir les 4 partitions valides identifi\xe9es\xa0: une pour \xc9chec (0-59), une pour R\xe9ussite (60-69), une pour Bon (70-89) et une pour Excellent (90-100). Selon le programme, pour obtenir une couverture \xe0 100\xa0% avec un partitionnement d\'\xe9quivalence, les cas de test doivent exercer toutes les partitions identifi\xe9es couvrant chaque partition au moins une fois. C. Ce n\u2019est pas exact. 5 cas de tests seraient plus que n\xe9cessaires pour couvrir les partitions minimales valides. D. Ce n\u2019est pas exact. 6 cas de test d\xe9passent le nombre minimum requis. Q","source":"User Provided Batch 4"},{"id":"q_batch4_9dq3pcf6l","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Pour un champ \xab \xc2ge \xbb qui accepte des valeurs de 16 \xe0 65 ans, votre suite de tests comprend les valeurs suivantes : 15, 16, 17, 64, 65, 66. Quel pourcentage de couverture d\'analyse des valeurs limites (LVA) \xe0 3 valeurs obtenez-vous ?  ","options":["50%","67%","83%","100%"],"correctAnswer":3,"explanation":"R. Ce n\'est pas exact. 50 % correspondraient \xe0 3 des 6 \xe9l\xe9ments couverts. B. Ce n\u2019est pas correct. 67 % seraient 4 des 6 \xe9l\xe9ments couverts. C. Ce n\u2019est pas exact. 83 % seraient 5 des 6 \xe9l\xe9ments couverts. D. C\'est exact. En BVA \xe0 3 valeurs, pour chaque valeur seuil (16 et 65), il existe trois \xe9l\xe9ments de couverture\xa0: la valeur seuil et ses deux voisins. Pour la limite 16\xa0: 15, 16, 17. Pour la limite 65\xa0: 64, 65, 66. La suite de tests couvre les 6 \xe9l\xe9ments requis (15, 16, 17, 64, 65, 66), donc 6/6 = 100%. Q","source":"User Provided Batch 4"},{"id":"q_batch4_lwvrb8dbo","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Dans une table de d\xe9cision pour un syst\xe8me d\'approbation de pr\xeat, vous avez les conditions suivantes : \xc2ge \u2265 18 ans Revenu \u2265 30 000 $ Bon historique de cr\xe9dit Employ\xe9 depuis \u2265 2 ans Si vous vouliez minimiser la table en raison du grand nombre de combinaisons, quelle serait la meilleure strat\xe9gie ?  ","options":["Supprimez toutes les conditions moins importantes","Utiliser une approche bas\xe9e sur les risques pour affiner les r\xe8gles \xe0 tester","Combinez toutes les conditions en une seule r\xe8gle","Cr\xe9ez plusieurs petites tables distinctes"],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. La suppression de conditions peut laisser des lacunes importantes dans la couverture. B. C\u2019est exact. Selon le programme, \xab\xa0s\'il existe de nombreuses conditions, l\'application de toutes les r\xe8gles de d\xe9cision peut prendre beaucoup de temps, car le nombre de r\xe8gles augmente de fa\xe7on exponentielle avec le nombre de conditions. Dans un tel cas, pour r\xe9duire le nombre de r\xe8gles \xe0 appliquer, une table de d\xe9cision minimis\xe9e ou une approche bas\xe9e sur les risques peuvent \xeatre utilis\xe9es. C. Ce n\u2019est pas exact. La combinaison de toutes les conditions ne r\xe9sout pas le probl\xe8me de complexit\xe9. D. Ce n\u2019est pas exact. Plusieurs tables distinctes ne r\xe9solvent pas le probl\xe8me des jointures exponentielles. Q","source":"User Provided Batch 4"},{"id":"q_batch4_paz05v6hi","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Laquelle des affirmations suivantes SE FAIT R\xc9F\xc9RER \xe0 la pr\xe9diction d\u2019erreurs dans un processus de test\xa0?  ","options":["La pr\xe9diction des bogues est bas\xe9e uniquement sur des mesures quantitatives des d\xe9fauts pass\xe9s sans tenir compte du contexte de d\xe9veloppement.","La pr\xe9diction des bogues consiste \xe0 identifier les zones du logiciel les plus susceptibles de contenir des d\xe9fauts, en fonction de l\'historique des bogues et de la complexit\xe9 du code.","La pr\xe9diction des bogues n\xe9cessite que les testeurs effectuent des tests unitaires sur toutes les fonctions avant de pouvoir pr\xe9dire les bogues.","La pr\xe9diction de bogues est un processus que seuls les d\xe9veloppeurs peuvent effectuer, car ce sont eux qui connaissent le mieux leur code."],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. Bien que les mesures quantitatives soient utiles, la pr\xe9diction des erreurs prend \xe9galement en compte le contexte et l\u2019exp\xe9rience ant\xe9rieure pour \xeatre efficaces. B. C\u2019est exact. La pr\xe9diction des bogues implique l\'utilisation de l\'historique des bogues ainsi que de facteurs tels que la complexit\xe9 du code pour identifier les zones probl\xe9matiques. C. Ce n\u2019est pas exact. La pr\xe9diction des bogues ne d\xe9pend pas de la r\xe9alisation de tests unitaires, mais de l\'analyse des mod\xe8les de d\xe9fauts pass\xe9s. D. Ce n\u2019est pas exact. La pr\xe9diction des bogues est une t\xe2che qui peut \xe9galement \xeatre effectu\xe9e par les testeurs, qui peuvent apporter une perspective diff\xe9rente sur les zones \xe0 risque. Q","source":"User Provided Batch 4"},{"id":"q_batch4_a4nevsfk4","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Une \xe9quipe de d\xe9veloppement cr\xe9e une application mobile innovante et a d\xe9cid\xe9 de recourir \xe0 des tests exploratoires en raison d\'un manque de documentation. Parmi les affirmations suivantes concernant les tests exploratoires, laquelle est CORRECT\xa0?  ","options":["Les tests exploratoires sont toujours moins efficaces que les tests bas\xe9s sur les exigences.","Les tests exploratoires permettent aux testeurs de s\'adapter rapidement aux modifications apport\xe9es au logiciel.","Les tests exploratoires n\xe9cessitent un plan de test d\xe9taill\xe9 avant d\u2019\xeatre effectu\xe9s.","Les tests exploratoires ne conviennent pas aux applications complexes."],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. Les tests exploratoires peuvent \xeatre tr\xe8s efficaces, en particulier dans les environnements o\xf9 les exigences sont ambigu\xebs ou changent fr\xe9quemment. B. C\u2019est exact. Les tests exploratoires permettent aux testeurs de s\'adapter et de r\xe9pondre avec plus de flexibilit\xe9 aux modifications logicielles. C. Ce n\u2019est pas exact. Bien qu\'il puisse exister une approche g\xe9n\xe9rale, les tests exploratoires se caract\xe9risent par le fait qu\'ils ne d\xe9pendent pas d\'un plan de test rigoureux et d\xe9taill\xe9. D. Ce n\u2019est pas exact. Les tests exploratoires peuvent \xeatre tr\xe8s utiles dans des applications complexes en permettant une exploration plus dynamique et cr\xe9ative. Q","source":"User Provided Batch 4"},{"id":"q_batch4_q2p8s0mdy","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Laquelle des affirmations suivantes d\xe9crit le MIEUX comment les crit\xe8res d\u2019acceptation peuvent \xeatre structur\xe9s dans une user story\xa0?  ","options":["D\xe9fini uniquement par l\'\xe9quipe de d\xe9veloppement, sans n\xe9cessiter d\'examen par les parties prenantes.","R\xe9dig\xe9 dans un format clair et concis qui facilite la compr\xe9hension par toutes les parties int\xe9ress\xe9es impliqu\xe9es.","Cr\xe9er une liste compl\xe8te d\'exigences techniques qui doivent \xeatre remplies pour la livraison de la user story.","\xc9tabli en fonction des attentes personnelles des membres de l\'\xe9quipe, sans tenir compte des objectifs du projet."],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. Les crit\xe8res d\'acceptation doivent \xeatre examin\xe9s et accept\xe9s par toutes les parties prenantes, et pas seulement par l\'\xe9quipe de d\xe9veloppement. B. C\u2019est exact. Un format clair et concis aide toutes les parties prenantes \xe0 comprendre ce qui est n\xe9cessaire pour consid\xe9rer la user story comme compl\xe8te. C. Ce n\u2019est pas exact. M\xeame si les exigences techniques peuvent \xeatre importantes, les crit\xe8res d\'acceptation doivent se concentrer sur les conditions de satisfaction des utilisateurs et non sur une liste technique exhaustive. D. Ce n\u2019est pas exact. Les crit\xe8res d\'acceptation doivent s\'aligner sur les objectifs du projet et les besoins des utilisateurs, et non \xeatre bas\xe9s sur des attentes individuelles. Q","source":"User Provided Batch 4"},{"id":"q_batch4_m7s7cmw0j","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Lors d\'un atelier de sp\xe9cification ATDD, l\'\xe9quipe identifie les ambigu\xeft\xe9s dans une user story concernant le traitement des paiements. Quelle est l\u2019action LA PLUS appropri\xe9e selon l\u2019approche ATDD\xa0?  ","options":["Le testeur doit cr\xe9er des cas de tests qui couvrent toutes les interpr\xe9tations possibles","R\xe9soudre les ambigu\xeft\xe9s pendant l\'atelier avant de cr\xe9er des cas de test","Reporter la cr\xe9ation de cas de test jusqu\'\xe0 ce que le d\xe9veloppement soit termin\xe9","Cr\xe9ez des cas de test uniquement pour les sc\xe9narios les plus probables"],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. Cr\xe9er des cas pour toutes les interpr\xe9tations sans r\xe9soudre les ambigu\xeft\xe9s peut conduire \xe0 des cas contradictoires ou incorrects. B. C\u2019est exact. Selon le programme, lors de l\'atelier de sp\xe9cification, \xab les incompl\xe9tude, les ambigu\xeft\xe9s ou les d\xe9fauts de la user story sont r\xe9solus au cours de ce processus \xbb avant de proc\xe9der \xe0 la cr\xe9ation des cas de test. Ceci est essentiel chez ATDD pour garantir que tout le monde ait la m\xeame compr\xe9hension. Q","source":"User Provided Batch 4"},{"id":"q_batch4_s9bm5wa3g","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Lequel des \xe9l\xe9ments suivants est un crit\xe8re d\u2019entr\xe9e pour l\u2019ex\xe9cution d\u2019un test\xa0?  ","options":["Les r\xe9sultats des tests pr\xe9c\xe9dents ont \xe9t\xe9 document\xe9s.","Les crit\xe8res d\'acceptation des exigences ont \xe9t\xe9 d\xe9finis.","L\'\xe9quipe de test a termin\xe9 la planification des tests.","Le logiciel a r\xe9ussi tous les tests unitaires."],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. Documenter les r\xe9sultats des tests ant\xe9rieurs est une bonne pratique, mais ce n\'est pas un crit\xe8re d\'entr\xe9e sp\xe9cifique. B. C\u2019est exact. La d\xe9finition des crit\xe8res d\u2019acceptation des exigences est essentielle pour garantir que les crit\xe8res d\u2019entr\xe9e sont clairs avant les tests. C. Ce n\u2019est pas exact. La planification des tests peut \xeatre une \xe9tape pr\xe9liminaire, mais ce n\'est pas un crit\xe8re d\'entr\xe9e en soi. D. Ce n\u2019est pas exact. La r\xe9ussite de tous les tests unitaires est un crit\xe8re de sortie, car elle indique qu\'une phase de test s\'est termin\xe9e avec succ\xe8s. Q","source":"User Provided Batch 4"},{"id":"q_batch4_jq145tq22","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Dans votre plan de test, vous avez hi\xe9rarchis\xe9 les cas de test en fonction des exigences. Cependant, vous r\xe9alisez que certains cas hautement prioritaires ne peuvent pas \xeatre ex\xe9cut\xe9s dans l\u2019ordre id\xe9al en raison des d\xe9pendances et de la disponibilit\xe9 des ressources. Quelle est l\u2019action LA PLUS appropri\xe9e selon le programme\xa0?  ","options":["Maintenir l\'ordre en fonction de la priorit\xe9 des exigences en ignorant les d\xe9pendances","Ajustez l\'ordre en tenant compte des d\xe9pendances et de la disponibilit\xe9 des ressources","Passer \xe0 une strat\xe9gie de priorisation diff\xe9rente","Ex\xe9cuter uniquement les cas autonomes hautement prioritaires"],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. Ignorer les d\xe9pendances peut entra\xeener l\'\xe9chec des tests pour des raisons techniques plut\xf4t que pour des d\xe9fauts r\xe9els. B. C\u2019est exact. Le programme indique que \xab\xa0si un sc\xe9nario de test avec une priorit\xe9 plus \xe9lev\xe9e d\xe9pend d\'un sc\xe9nario de test avec une priorit\xe9 inf\xe9rieure, le sc\xe9nario de test de priorit\xe9 inf\xe9rieure doit \xeatre ex\xe9cut\xe9 en premier\xa0\xbb et que \xab\xa0l\'ordre d\'ex\xe9cution des tests doit \xe9galement prendre en compte la disponibilit\xe9 des ressources\xa0\xbb. C. Ce n\u2019est pas exact. Il n\'est pas n\xe9cessaire de changer la strat\xe9gie de priorisation, il suffit d\'ajuster l\'ordre d\'ex\xe9cution. D. Ce n\u2019est pas exact. Cela limiterait excessivement la couverture des tests. Q","source":"User Provided Batch 4"},{"id":"q_batch4_f4ffyxzso","chapter":4,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Comment les tests suivants sont-ils class\xe9s selon les quadrants de tests agiles (A-D) ? S\xe9lectionnez la bonne option.\\n\\n1. Tests de composants\\n2. Tests fonctionnels\\n3. Tests exploratoires\\n4. Tests non fonctionnels\\n\\nA (Q1). Orient\xe9 technologie, soutient l\'\xe9quipe  \\nB (Q2). Orient\xe9 m\xe9tier, soutient l\'\xe9quipe  \\nC (Q3). Orient\xe9 m\xe9tier, critique le produit  \\nD (Q4). Orient\xe9 technologie, critique le produit","options":["1A, 2B, 3C, 4D","1B, 2A, 3D, 4C","1C, 2D, 3A, 4B","1D, 2C, 3B, 4A"],"correctAnswer":0,"explanation":"A. Correct \u2013 selon le programme (section 5.1.7, p. 53) : 1 (tests de composants) \u2192 Q1 (technologie, support d\'\xe9quipe) 2 (tests fonctionnels) \u2192 Q2 (business, support d\'\xe9quipe) 3 (tests exploratoires) \u2192 Q3 (business, critique de produit) 4 (tests non fonctionnels) \u2192 Q4 (technologie, critique de produit) Les tests de ces quadrants se rapportent directement aux niveaux et types de tests indiqu\xe9s dans le Mod\xe8le Marick/Crispin. B. Incorrect \u2013 les tests des composants (1) ne sont pas en Q2\xa0; Ils sont au premier trimestre. Les tests fonctionnels (2) ne sont pas au T1 ; Ils sont au deuxi\xe8me trimestre. C. Incorrect \u2013 les tests exploratoires (3) ne sont pas en Q1\xa0; Ils sont au troisi\xe8me trimestre. Les tests non fonctionnels (4) ne sont pas au T2 ; Ils sont au quatri\xe8me trimestre. D. Incorrect \u2013 les tests des composants (1) ne sont pas au quatri\xe8me trimestre\xa0; Ils sont au premier trimestre. Les tests exploratoires (3) ne sont pas en Q2 ; Ils sont au troisi\xe8me trimestre. Q","source":"User Provided Batch 4"},{"id":"q_batch4_z9hth9gwh","chapter":3,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Dans un projet de d\xe9veloppement logiciel, le risque suivant a \xe9t\xe9 identifi\xe9 : Risque : La documentation utilisateur n\'est pas \xe0 jour. Probabilit\xe9 de risque : \xe9lev\xe9e ; impact du risque : moyen R\xe9ponse au risque : une revue approfondie de la documentation est organis\xe9e avec l\'\xe9quipe de d\xe9veloppement les utilisateurs sont inform\xe9s des \xe9ventuelles incoh\xe9rences dans la documentation Quelle est la mesure la plus appropri\xe9e pour r\xe9pondre \xe0 ce risque analys\xe9 ?  ","options":["Att\xe9nuation des risques","Acceptation du risque","Transfert de risque","\xc9limination des risques"],"correctAnswer":0,"explanation":"R. C\'est exact. L\u2019examen de la documentation permet d\u2019att\xe9nuer le risque d\u2019incoh\xe9rences. B. Ce n\u2019est pas correct. Accepter le risque ne r\xe9sout pas le probl\xe8me de la documentation obsol\xe8te. C. Ce n\u2019est pas exact. Le risque n\u2019est pas transf\xe9r\xe9, mais plut\xf4t trait\xe9 directement. D. Ce n\u2019est pas exact. Ce risque ne peut pas \xeatre compl\xe8tement \xe9limin\xe9, mais des mesures peuvent \xeatre prises pour l\'att\xe9nuer. Q","source":"User Provided Batch 4"},{"id":"q_batch4_kzxw2m4i9","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Lors du suivi des d\xe9fauts d\xe9tect\xe9s lors des tests, quel est l\u2019avantage de la gestion de la configuration dans ce processus\xa0?  ","options":["Aide \xe0 documenter les exigences de test.","Il permet d\'identifier la version du logiciel dans laquelle le d\xe9faut a \xe9t\xe9 trouv\xe9.","Facilite la cr\xe9ation de nouveaux cas de test.","S\'assure que tous les d\xe9fauts sont r\xe9solus avant la livraison."],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. La gestion de la configuration ne se concentre pas sur les exigences, mais sur la gestion des \xe9l\xe9ments de test et de leur version. B. C\u2019est exact. La gestion de la configuration permet d\'associer les d\xe9fauts \xe0 des versions sp\xe9cifiques du logiciel, ce qui facilite leur suivi et leur r\xe9solution. C. Ce n\u2019est pas exact. La cr\xe9ation de nouveaux cas de test fait partie de la conception des tests et n\'est pas un avantage direct de la gestion de la configuration. D. Ce n\u2019est pas exact. Bien que la gestion de la configuration P","source":"User Provided Batch 4"},{"id":"q_batch4_attdk2hjt","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Un analyste de test pr\xe9pare le rapport de d\xe9faut suivant\xa0: ID\xa0: BUG-00721 \u200b\u200b\u200b\u200b\u200b\u200b| Titre\xa0: Le champ \xab\xa0Date de naissance\xa0\xbb accepte les dates futures | Gravit\xe9\xa0: moyenne | Priorit\xe9\xa0:\xa0\xc9lev\xe9e | Rapport\xe9 par: A. L\xf3pez | Configuration\xa0: application v3.2.1, Chrome 120 | \xc9tapes \xe0 reproduire\xa0: (1) Ouvrez le formulaire d\'inscription, (2) Saisissez la date de naissance \'15/08/2030\', (3) Cliquez sur \'Enregistrer\'. Quelle est l\u2019information la PLUS importante qui manque dans ce rapport\xa0?  ","options":["Le nom du d\xe9veloppeur charg\xe9 de r\xe9soudre le d\xe9faut.","Le r\xe9sultat r\xe9el obtenu et le r\xe9sultat attendu, pour faciliter la reproduction et la correction.","Une estimation du temps n\xe9cessaire pour corriger le d\xe9faut.","Le nombre d\'utilisateurs concern\xe9s par le d\xe9faut."],"correctAnswer":1,"explanation":"R. Incorrect. L\'attribution du d\xe9faut \xe0 un d\xe9veloppeur est une activit\xe9 post-gestion et non un \xe9l\xe9ment essentiel du rapport initial. B. Exactement. Selon CTFL Syllabus v4.0 \xa75.5.1, un rapport de d\xe9faut complet doit inclure les r\xe9sultats r\xe9els obtenus et les r\xe9sultats attendus. Sans ces informations, le d\xe9veloppeur ne peut pas confirmer le comportement incorrect ni valider le correctif. C. Incorrect. L\'estimation du temps de r\xe9paration rel\xe8ve de la responsabilit\xe9 de l\'\xe9quipe de d\xe9veloppement, et non du rapport de d\xe9faut. D. Incorrect. L\'impact sur les utilisateurs peut \xeatre indiqu\xe9 dans la priorit\xe9/gravit\xe9, mais ne constitue pas un champ essentiel du rapport de d\xe9faut selon le programme. Q","source":"User Provided Batch 4"},{"id":"q_batch4_83alrpwtk","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Lequel des outils de test suivants est g\xe9n\xe9ralement utilis\xe9 pour automatiser l\u2019ex\xe9cution des tests\xa0?  ","options":["Outils de gestion des tests","Outils de test de performances","Outils d\'automatisation des tests","Outils de gestion des d\xe9fauts"],"correctAnswer":2,"explanation":"R. Ce n\'est pas exact. Les outils de gestion des tests sont utilis\xe9s pour planifier, organiser et suivre le processus de test, mais pas pour ex\xe9cuter les tests de mani\xe8re automatis\xe9e. B. Ce n\u2019est pas correct. Les outils de test de performances sont con\xe7us pour \xe9valuer les performances du syst\xe8me sous charge, et non pour automatiser l\'ex\xe9cution des tests en g\xe9n\xe9ral. C. C\'est exact. Les outils d\'automatisation des tests sont sp\xe9cialement con\xe7us pour ex\xe9cuter des tests automatiquement, permettant ainsi des tests plus rapides et plus efficaces. D. Ce n\u2019est pas exact. Les outils de gestion des d\xe9fauts sont utilis\xe9s pour suivre et g\xe9rer les bogues d\xe9tect\xe9s au cours du processus de test, et non pour automatiser l\'ex\xe9cution des tests. Q","source":"User Provided Batch 4"},{"id":"q_batch4_7576lzkad","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Lequel des \xe9nonc\xe9s suivants d\xe9crit un avantage de l\u2019automatisation des tests\xa0?  ","options":["Augmentez la couverture des tests en moins de temps","\xc9limine compl\xe8tement le besoin de tests manuels","R\xe9duit la complexit\xe9 du d\xe9veloppement de logiciels","Augmente la possibilit\xe9 d\u2019erreurs humaines lors de l\u2019ex\xe9cution"],"correctAnswer":0,"explanation":"R. C\'est exact. L\'automatisation vous permet d\'ex\xe9cuter des tests plus rapidement et plus fr\xe9quemment, ce qui peut augmenter la couverture des tests. B. Ce n\u2019est pas correct. M\xeame si l\u2019automatisation peut r\xe9duire le besoin de tests manuels, elle ne peut pas l\u2019\xe9liminer compl\xe8tement dans tous les cas. C. Ce n\u2019est pas exact. L\u2019automatisation ne r\xe9duit pas n\xe9cessairement la complexit\xe9 des logiciels ; elle peut en fait introduire sa propre complexit\xe9. D. Ce n\u2019est pas exact. L\'automatisation, si elle est effectu\xe9e correctement, peut r\xe9duire le risque d\'erreur humaine lors de l\'ex\xe9cution des tests.","source":"User Provided Batch 4"},{"id":263,"chapter":2,"topic":"Testing a lo largo del SDLC","question":"Vous testez une user story avec trois crit\xe8res d\u2019acceptation : AC1, AC2 et AC3. AC1 est couvert par le sc\xe9nario de test TC1, AC2 par TC2 et AC3 par TC3. L\'historique d\'ex\xe9cution des tests comprenait trois s\xe9ries de tests sur trois versions cons\xe9cutives du logiciel, comme suit\xa0:  \\n  \\n| | Ex\xe9cution 1 | Ex\xe9cution 2 | Ex\xe9cution 3 |  \\n|---|---|---|---|  \\n| TC1 (1) | \xc9chec (4) | Pass\xe9 (7) | Pass\xe9 |  \\n| TC2 (2) | Pass\xe9 (5) | \xc9chec (8) | Pass\xe9 |  \\n| TC3 (3) | \xc9chec (6) | \xc9chec (9) | Pass\xe9 |  \\n  \\nLes tests sont r\xe9p\xe9t\xe9s une fois que vous \xeates inform\xe9 que tous les d\xe9fauts d\xe9tect\xe9s lors de la s\xe9rie de tests sont corrig\xe9s et qu\'une nouvelle version du logiciel est disponible. Parmi les tests ci-dessus, lesquels sont ex\xe9cut\xe9s en tant que tests de r\xe9gression\xa0?  ","options":["A) Seulement 4, 7, 8, 9","B) Seulement 5, 7","C) Seulement 4, 6, 8, 9","D) Seulement 5, 6"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#14, LO : FL-2.2.3). Justification\xa0: seulement 5, 7","source":"Official Sample Exam A Q#14"},{"id":270,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Vous testez un syst\xe8me qui calcule la note finale du cours pour un \xe9tudiant donn\xe9. La note finale est attribu\xe9e en fonction du r\xe9sultat final, selon les r\xe8gles suivantes :  \\n- 0 \u2013 50 points : \xe9chec  \\n- 51 \u2013 60 points : suffisant  \\n- 61 \u2013 70 points : satisfaisant  \\n- 71 \u2013 80 points : bien  \\n- 81 \u2013 90 points : tr\xe8s bien  \\n- 91 \u2013 100 points : excellent  \\n  \\nVous avez pr\xe9par\xe9 l\'ensemble de sc\xe9narios de test suivant\xa0:  \\n  \\n| TC | R\xe9sultat final | Note finale |  \\n|---|---|---|  \\n| TC1 | 91 | excellent |  \\n| TC2 | 50 | suspense |  \\n| TC3 | 81 | tr\xe8s bien |  \\n| TC4 | 60 | assez |  \\n| TC5 | 70 | satisfaisant |  \\n| TC6 | 80 | bon |  \\n  \\nQuelle est la couverture de l\'analyse des valeurs limites (BVA) \xe0 2 valeurs pour le r\xe9sultat final obtenu avec les cas de test existants\xa0?  ","options":["A) 50\xa0%","B) 60\xa0%","C) 33,3%","D) 100\xa0%"],"correctAnswer":0,"explanation":"L\'option A) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon A, Q#21, LO : FL-4.2.2). Justification : 50%","source":"Official Sample Exam A Q#21"},{"id":309,"chapter":4,"topic":"T\xe9cnicas de An\xe1lisis y Dise\xf1o de Pruebas","question":"Le tableau de d\xe9cision suivant contient les r\xe8gles permettant de d\xe9terminer le risque d\u2019art\xe9rioscl\xe9rose.  \\n  \\n| | R\xe8gle 1 | R\xe8gle 2 | R\xe8gle 3 | R\xe8gle 4 | R\xe8gle 5 |  \\n|---|---|---|---|---|---|  \\n| Cholest\xe9rol (mg/dl) | \u2264124 | \u2264124 | 125-200 | 125-200 | \u2265201 |  \\n| Pression art\xe9rielle (mm Hg) | \u2264140 | >140 | \u2264140 | >140 | \u2013 |  \\n| Niveau de risque | tr\xe8s faible | faible | moyen | \xe9lev\xe9 | tr\xe8s \xe9lev\xe9 |  \\n  \\nVous avez con\xe7u les cas de tests suivants\xa0:  \\n- TC1 : Cholest\xe9rol=125, TA=141  \\n- TC2 : Cholest\xe9rol=200, TA=201  \\n- TC3 : Cholest\xe9rol=124, TA=201  \\n- TC4 : Cholest\xe9rol=109, TA=200  \\n- TC5 : Cholest\xe9rol=201, TA=140  \\n  \\nQuelle couverture de table de d\xe9cision ces cas de test atteignent-ils\xa0?  ","options":["A) 40\xa0%","B) 60\xa0%","C) 80\xa0%","D) 100\xa0%"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon B, Q#22, LO : FL-4.2.3). Justification : Le tableau comporte 5 r\xe8gles. Les cas de test couvrent les r\xe8gles 2 (TC1), 4 (TC2 \u2013 pas exactement applicable), 1 (TC4) et 5 (TC5). Seules 3 r\xe8gles sur 5 sont correctement couvertes, ce qui donne 60 %.","source":"Official Sample Exam B Q#22"},{"id":319,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Vous testez une application Web qui permet aux utilisateurs de RECHERCHER des produits, d\'AFFICHER les d\xe9tails, d\'AJOUTER au panier et de passer une COMMANDE. Vous disposez de 7 cas de test avec ces priorit\xe9s (1 = la plus \xe9lev\xe9e)\xa0:  \\n- TC1 : RECHERCHE produit A (4)  \\n- TC2 : RECHERCHE produit B (4)  \\n- TC3 : VOIR d\xe9tails A (3)  \\n- TC4 : VOIR d\xe9tails B (2)  \\n- TC5\xa0: AJOUTER le produit \xc0 (3)  \\n- TC6 : AJOUTER le produit B (1)  \\n- TC7\xa0: passer la COMMANDE (5)  \\n  \\nD\xe9pendances\xa0:\xa0LOOKUP doit \xeatre test\xe9 avant VIEW, VIEW avant ADD et ADD avant ORDER. Quel sc\xe9nario de test doit \xeatre ex\xe9cut\xe9 en quatri\xe8me\xa0?  ","options":["A) TC3","B) TC1","C) SS7","D) TC2"],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon B, Q#32, LO : FL-5.1.5). Justification : Respect des d\xe9pendances et de la priorit\xe9 : 1er TC6 (p1), 2\xe8me TC4 (p2), 3\xe8me TC5 ou TC3 (p3), 4\xe8me TC1 (p4 apr\xe8s avoir rempli les d\xe9pendances).","source":"Official Sample Exam B Q#32"},{"id":325,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Vous testez une fonction de tri qui prend un ensemble de nombres et les renvoie tri\xe9s par ordre croissant. Le journal d\'ex\xe9cution est\xa0:  \\n  \\n- TC1 : Entr\xe9e : \'3\'. Sortie : \xab\xa03\xa0\xbb. R\xe9sultat : r\xe9ussi  \\n- TC2 : Entr\xe9e : `3 11 6 5`. Sortie : \xab 3 5 6 11 \xbb. R\xe9sultat : r\xe9ussi  \\n- TC3 : Entr\xe9e : `8 7 3 7 1`. Sortie\xa0:\xa0`1 3 7 8`. R\xe9sultat\xa0: \xe9chec  \\n- TC4 : Entr\xe9e : `-2 -2 -2 -3 -3`. Sortie : `-3 -2`. R\xe9sultat\xa0: \xe9chec  \\n- TC5 : Entr\xe9e : `0 -2 0 3 4 4`. Sortie : `-2 0 3 4`. R\xe9sultat\xa0: \xe9chec  \\n  \\nLequel des \xe9l\xe9ments suivants fournit la MEILLEURE description du bogue \xe0 utiliser dans un rapport de d\xe9faut\xa0?  ","options":["A) Le syst\xe8me ne parvient pas \xe0 trier plusieurs ensembles de nombres. R\xe9f\xe9rence : TC3, TC4, TC5.","B) Le syst\xe8me semble ignorer les doublons lors du tri. R\xe9f\xe9rence : TC3, TC4, TC5.","C) Le syst\xe8me ne peut pas trier les nombres n\xe9gatifs. R\xe9f\xe9rence : TC4, TC5.","D) TC3, TC4 et TC5 pr\xe9sentent des d\xe9fauts (donn\xe9es d\'entr\xe9e en double) et doivent \xeatre corrig\xe9s."],"correctAnswer":1,"explanation":"L\'option B) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon B, Q#38, LO : FL-5.5.1). Justification\xa0: Le mod\xe8le commun aux trois bogues est que la fonction ignore les \xe9l\xe9ments en double lors du tri, ce qui constitue la description la plus pr\xe9cise du d\xe9faut.","source":"Official Sample Exam B Q#38"},{"id":355,"chapter":5,"topic":"Gesti\xf3n de las Actividades de Prueba","question":"Vous pr\xe9parez un planning d\'ex\xe9cution de tests pour 7 cas de tests (TC1-TC7).  \\n  \\nLes d\xe9pendances sont :  \\n- TC2 d\xe9pend de TC1  \\n- TC4 d\xe9pend de TC2 et TC3  \\n- TC5 d\xe9pend du TC3  \\n- TC6 d\xe9pend de TC4 et TC5  \\n- TC7 d\xe9pend du TC6  \\n  \\nLes priorit\xe9s (1=la plus \xe9lev\xe9e) sont\xa0: TC1-p3, TC2-p5, TC3-p1, TC4-p4, TC5-p2, TC6-p6, TC7-p7.  \\n  \\nQuel est le bon ordre d\u2019ex\xe9cution en respectant les d\xe9pendances et les priorit\xe9s\xa0?  ","options":["A) TC3, TC5, TC1, TC2, TC4, TC6, TC7","B) TC1, TC2, TC3, TC4, TC5, TC6, TC7","C) TC3, TC1, TC5, TC2, TC4, TC6, TC7","D) TC1, TC3, TC2, TC5, TC4, TC6, TC7"],"correctAnswer":2,"explanation":"L\'option C) est la bonne r\xe9ponse selon l\'examen officiel ISTQB CTFL v4.0 (\xe9chantillon D, Q#3, LO : FL-5.1.5). Justification\xa0:\xa0TC3 a la priorit\xe9 la plus \xe9lev\xe9e (p1) et n\'a aucune d\xe9pendance, il passe donc en premier. Puis TC1 (p3, pas de d\xe9pendances), puis TC5 (d\xe9pend de TC3), etc.","source":"Official Sample Exam C Q#32"},{"id":1014,"chapter":2,"topic":"Regresi\xf3n vs Confirmaci\xf3n","question":"Les cas de tests ont \xe9t\xe9 ex\xe9cut\xe9s\xa0:  \\n- \xc9chec du TC1  \\n- SS2 r\xe9ussi  \\n- \xc9chec de SS3  \\n  \\nApr\xe8s corrections, TC1, TC2 et TC3 sont \xe0 nouveau ex\xe9cut\xe9s. Lesquelles de ces ex\xe9cutions sont consid\xe9r\xe9es comme des tests de r\xe9gression\xa0?  ","options":["CT1","TC2","TC3","TC1 et TC3"],"correctAnswer":1,"explanation":"L\'ex\xe9cution de TC2 est une r\xe9gression, puisqu\'il fonctionnait auparavant et on v\xe9rifie que les changements ne l\'ont pas cass\xe9. TC1 et TC3 sont des tests de confirmation.","source":"Pr\xe1ctica Adicional"},{"id":"q_batch2_t5hos07b9","topic":"Gesti\xf3n de las Actividades de Prueba","question":"Vous disposez des cas de test suivants pour un syst\xe8me bancaire en ligne\xa0:  \\n  \\n| Cas | Risque de fonctionnalit\xe9 | Probabilit\xe9 du risque | Impact du risque | D\xe9pendance |  \\n|---|---|---|---|---|  \\n| TC1 | Connexion | 2 | 2 | Aucun |  \\n| TC2 | V\xe9rifier le solde | 3 | 3 | TC1 |  \\n| TC3 | Transf\xe9rer de l\'argent | 2 | 2 | TC1, TC2 |  \\n| TC4 | Changer le code PIN | 4 | 4 | TC1 |  \\n  \\nEn appliquant une priorisation bas\xe9e sur les risques, o\xf9 l\'impact et la probabilit\xe9 sont mesur\xe9s sur une \xe9chelle de 1 \xe0 5 (1=Tr\xe8s \xe9lev\xe9, 2=\xc9lev\xe9, 3=Moyen, 4=Faible, 5=Tr\xe8s faible), quel serait l\'ordre d\'ex\xe9cution LE PLUS appropri\xe9\xa0?  ","options":["TC1, TC3, TC2, TC4","TC1, TC2, TC3, TC4","TC3, TC1, TC2, TC4","TC1, TC4, TC2, TC3"],"correctAnswer":1,"explanation":"R. Incorrect. Probl\xe8me 1\xa0:\xa0TC3 d\xe9pend de TC2 (n\xe9cessite un solde interrog\xe9), mais TC3 s\'ex\xe9cute avant TC2. Cela rompt la d\xe9pendance. Probl\xe8me 2\xa0: TC2 a un risque plus \xe9lev\xe9 (9) que TC4 (16), mais TC4 est ex\xe9cut\xe9 avant TC2. Mauvaise priorit\xe9 des risques. B. Exactement. TC1 en premier\xa0: il est ind\xe9pendant et sert de base \xe0 tous les autres cas. TC2 avant TC3/TC4\xa0: TC2 a un risque plus \xe9lev\xe9 (9) que TC4 (16), et TC3 d\xe9pend de TC2. C. Incorrect. Probl\xe8me critique\xa0: TC3 d\xe9pend de TC1 et TC2, mais s\'ex\xe9cute en premier, avant les deux. Il \xe9chouera en raison du manque de d\xe9pendances. D. Incorrect. Probl\xe8me 1 : TC2 a un risque plus \xe9lev\xe9 (9) que TC4 (16), mais TC4 est ex\xe9cut\xe9 avant TC2. Mauvaise priorit\xe9 des risques. Probl\xe8me 2 : TC3 d\xe9pend de TC2, mais TC2 s\'ex\xe9cute apr\xe8s TC3. Brisez la d\xe9pendance.","chapter":5,"source":"banco-extra"},{"id":"q_batch3_l6n0dvnvr","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Une \xe9quipe de d\xe9veloppement a corrig\xe9 plusieurs d\xe9fauts dans une nouvelle version de l\'application. Les cas de test suivants ont \xe9t\xe9 ex\xe9cut\xe9s dans la version pr\xe9c\xe9dente\xa0:  \\n  \\n| Test | R\xe9sultat dans la version pr\xe9c\xe9dente |  \\n|---|---|  \\n| TC1 | \xc9chec |  \\n| TC2 | Pass\xe9 |  \\n| TC3 | \xc9chec |  \\n  \\nApr\xe8s les corrections, l\u2019\xe9quipe ex\xe9cute \xe0 nouveau les cas de test TC1, TC2 et TC3. Lesquelles de ces ex\xe9cutions sont consid\xe9r\xe9es comme des tests de r\xe9gression\xa0?  ","options":["TC1 et TC3","TC2 et TC3","TC1 et TC2","TC2 uniquement"],"correctAnswer":3,"explanation":"R. Incorrect. TC1 et TC3 \xe9chouaient dans la version pr\xe9c\xe9dente, leur relance constitue donc des tests de confirmation (re-testing) : on v\xe9rifie que le d\xe9faut a \xe9t\xe9 corrig\xe9. Ce ne sont pas des tests de r\xe9gression. B. Incorrect. TC2 est un test de r\xe9gression, mais TC3 a \xe9chou\xe9 dans la version pr\xe9c\xe9dente et est donc un test de confirmation. La combinaison TC2+TC3 n\'est pas correcte. C. Incorrect. TC2 est un test de r\xe9gression, mais TC1 a \xe9chou\xe9 dans la version pr\xe9c\xe9dente et est un test de confirmation, pas un test de r\xe9gression. De plus, cette option \xe9tait identique \xe0 l\'option D, ce qui constituait un d\xe9faut structurel de la question. D. Exactement. TC2 r\xe9ussi dans la version pr\xe9c\xe9dente. En le r\xe9ex\xe9cutant apr\xe8s les corrections, on v\xe9rifie que les modifications n\'ont pas introduit de nouveaux d\xe9fauts dans les fonctionnalit\xe9s qui fonctionnaient d\xe9j\xe0. C\'est exactement la d\xe9finition des tests de r\xe9gression selon la secte CTFL v4.0. 2.2.3. TC1 et TC3, qui ont \xe9chou\xe9 auparavant, sont des tests de confirmation.","source":"User Provided Batch 3"},{"id":"q_batch5_oy2vhh5m6","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Quel type d\'outil de test est le mieux adapt\xe9 \xe0 la gestion des probl\xe8mes dans un projet logiciel\xa0?  ","options":["Outil de gestion des tests","Outil d\'automatisation des tests","Outil de suivi des incidents","Outil de gestion des configurations"],"correctAnswer":2,"explanation":"R. Ce n\'est pas exact. Bien que les outils de gestion des tests aident \xe0 organiser et planifier les tests, ils ne sont pas sp\xe9cifiquement con\xe7us pour g\xe9rer les probl\xe8mes. B. Ce n\u2019est pas correct. Les outils d\'automatisation des tests se concentrent sur l\'ex\xe9cution automatique des tests et non sur la gestion des probl\xe8mes. C. C\'est exact. Les outils de suivi des probl\xe8mes sont essentiels pour enregistrer, suivre et g\xe9rer les d\xe9fauts d\xe9tect\xe9s lors des tests. D. Ce n\u2019est pas exact. Les outils de gestion de configuration sont utilis\xe9s pour contr\xf4ler et maintenir les configurations logicielles, mais ne sont pas destin\xe9s \xe0 la gestion des incidents.","source":"User Provided Batch 4"},{"id":"q_batch5_o536w1du4","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Quel est le principal avantage d\u2019utiliser un outil de gestion de tests ?  ","options":["Automatisez les tests sans intervention humaine","Faciliter la planification et le suivi des tests","G\xe9n\xe9rer automatiquement des cas de test \xe0 partir du code","Identifiez les erreurs dans le code sans ex\xe9cuter de tests"],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. Bien que certains outils puissent faciliter l\u2019automatisation, l\u2019objectif principal d\u2019un outil de gestion des tests est la planification et le suivi. B. C\u2019est exact. Un outil de gestion des tests permet aux \xe9quipes de planifier, d\'organiser et de suivre la progression des tests, facilitant ainsi la coordination et la communication. C. Ce n\u2019est pas exact. Les outils qui g\xe9n\xe8rent automatiquement des cas de test sont g\xe9n\xe9ralement des outils d\'analyse et non des outils de gestion de tests. D. Ce n\u2019est pas exact. L\'identification des bogues dans le code sans ex\xe9cuter de tests n\'est pas une fonction des outils de gestion des tests ; c\'est davantage une fonction des outils d\'analyse statique.","source":"User Provided Batch 4"},{"id":"q_batch5_pdbyrk068","chapter":5,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Lequel des \xe9nonc\xe9s suivants d\xe9crit un avantage de l\u2019automatisation des tests\xa0?  ","options":["Besoin accru de personnel hautement qualifi\xe9 en programmation","Permet l\u2019ex\xe9cution de tests r\xe9p\xe9titifs de mani\xe8re rapide et coh\xe9rente","Le co\xfbt de maintenance des logiciels de test augmente consid\xe9rablement","N\xe9cessite moins de temps pour planifier des tests manuels"],"correctAnswer":1,"explanation":"R. Ce n\'est pas exact. M\xeame si l\u2019automatisation n\xe9cessite une certaine formation, elle ne constitue pas un avantage intrins\xe8que. B. C\u2019est exact. L\'automatisation vous permet d\'ex\xe9cuter des tests r\xe9p\xe9titifs de mani\xe8re rapide et coh\xe9rente, ce qui constitue un \xe9norme avantage. C. Ce n\u2019est pas exact. M\xeame s\u2019il peut y avoir des co\xfbts de maintenance, l\u2019avantage est que l\u2019efficacit\xe9 peut augmenter. D. Ce n\u2019est pas exact. L\'automatisation ne r\xe9duit pas n\xe9cessairement le temps de planification manuelle des tests.","source":"User Provided Batch 4"},{"id":"q_batch5_aqadcfs6i","chapter":1,"topic":"Desarrollo y Testing","difficulty":"medium","question":"Parmi les \xe9l\xe9ments suivants, lequel constitue un avantage de l\u2019automatisation des tests\xa0?  ","options":["Augmentation de la couverture des tests","Augmentation du temps requis pour ex\xe9cuter les tests","Recours \xe0 des outils de test sp\xe9cifiques","R\xe9duction de la documentation n\xe9cessaire"],"correctAnswer":0,"explanation":"R. C\'est exact. L\'automatisation des tests vous permet d\'ex\xe9cuter plus de tests en moins de temps, augmentant ainsi la couverture. B. Ce n\u2019est pas correct. L\'automatisation r\xe9duit g\xe9n\xe9ralement le temps n\xe9cessaire \xe0 l\'ex\xe9cution d\'une suite de tests. C. Ce n\u2019est pas exact. M\xeame si l\u2019automatisation peut cr\xe9er une d\xe9pendance aux outils, cela ne constitue pas un avantage. D. Ce n\u2019est pas exact. L\'automatisation ne r\xe9duit pas n\xe9cessairement la documentation, elle n\xe9cessite souvent une documentation suppl\xe9mentaire pour les scripts de test.","source":"User Provided Batch 4"}]')}}]);